__disc("api/actor/1579878",{"cik":1579878,"name":"Figma, Inc.","regime":"10-K","filings":[{"acc":"0001579878-25-000027","form":"10-Q","date":"2025-09-03","url":"https://www.sec.gov/Archives/edgar/data/1579878/000157987825000027/fig-20250630.htm","rf_words":36171,"rf_ai":null,"rf_method":null,"txt":"cf96d23d842138d3","coded":true,"n_ai_harm":6,"n_passages":24},{"acc":"0001579878-25-000026","form":"8-K","date":"2025-09-03","url":"https://www.sec.gov/Archives/edgar/data/1579878/000157987825000026/fig-20250903.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"393d74ff6f9f8310","coded":true,"n_ai_harm":0,"n_passages":4},{"acc":"0001628280-25-049683","form":"10-Q","date":"2025-11-05","url":"https://www.sec.gov/Archives/edgar/data/1579878/000162828025049683/fig-20250930.htm","rf_words":35768,"rf_ai":null,"rf_method":null,"txt":"20387644d120cfcd","coded":true,"n_ai_harm":6,"n_passages":24},{"acc":"0001628280-25-049555","form":"8-K","date":"2025-11-05","url":"https://www.sec.gov/Archives/edgar/data/1579878/000162828025049555/fig-20251105.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"6704b0889096721a","coded":true,"n_ai_harm":0,"n_passages":3},{"acc":"0001628280-26-009228","form":"10-K","date":"2026-02-18","url":"https://www.sec.gov/Archives/edgar/data/1579878/000162828026009228/fig-20251231.htm","rf_words":39040,"rf_ai":null,"rf_method":null,"txt":"42d059d966685e3e","coded":true,"n_ai_harm":8,"n_passages":34},{"acc":"0001628280-26-009024","form":"8-K","date":"2026-02-18","url":"https://www.sec.gov/Archives/edgar/data/1579878/000162828026009024/fig-20260218.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"9631a9e8b8c49b36","coded":true,"n_ai_harm":0,"n_passages":5},{"acc":"0001628280-26-035209","form":"10-Q","date":"2026-05-14","url":"https://www.sec.gov/Archives/edgar/data/1579878/000162828026035209/fig-20260331.htm","rf_words":41012,"rf_ai":null,"rf_method":null,"txt":"07db22ec2238378a","coded":true,"n_ai_harm":9,"n_passages":39},{"acc":"0001628280-26-035087","form":"8-K","date":"2026-05-14","url":"https://www.sec.gov/Archives/edgar/data/1579878/000162828026035087/fig-20260514.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"90fff9b2ebef21b9","coded":true,"n_ai_harm":0,"n_passages":4},{"acc":"0001628280-26-053348","form":"10-Q","date":"2026-08-05","url":"https://www.sec.gov/Archives/edgar/data/1579878/000162828026053348/fig-20260630.htm","rf_words":41483,"rf_ai":null,"rf_method":null,"txt":"df58d5c0f47fa0a6","coded":true,"n_ai_harm":9,"n_passages":42},{"acc":"0001628280-26-053331","form":"8-K","date":"2026-08-05","url":"https://www.sec.gov/Archives/edgar/data/1579878/000162828026053331/fig-20260805.htm","rf_words":null,"rf_ai":null,"rf_method":null,"txt":"66e4bed9fd9f58a2","coded":true,"n_ai_harm":0,"n_passages":5}],"passages":[{"id":"1579878-a8ed87fc6e","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"retain and increase adoption of our products and services by existing customers, as well as attract new customers and grow our customer base; develop new offerings and functionality for our platform and successfully optimize our existing products and services, including through integration of AI into our platform; successfully expand our business domestically and internationally;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228","0001628280-26-035209"],"forms":{"10-K":1,"10-Q":1},"first":"2026-02-18","last":"2026-05-14","end":null},{"id":"1579878-2e1759c35b","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"protect against security incidents; successfully price and package our platform in a rapidly changing software industry, including due to advancements and increasing use of AI; and 17 Table of Contents successfully identify and acquire or invest in businesses, products, offerings, or technologies that we believe could complement or expand our platform and successfully integrate such businesses, products, offerings, or technologies into our business.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-c72defc6ff","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"If we fail to properly manage technical debt, our platform performance may suffer, we may face increased downtime, and our business, operating results, and financial condition could be harmed. Additionally, as we further integrate AI capabilities and expand our product offerings, technical complexity may increase, potentially exacerbating these challenges. To manage any future growth effectively, we must continue to improve and expand our infrastructure, including information technology and financial infrastructure, our operating and administrative systems and controls, and our ability to manage headcount, capital, and processes in an efficient manner.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-5394e37b11","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"the amount and timing of investments and expenditures related to the expansion of our business; impacts on our cost structure, including, but not limited to, any decrease in our gross margins and operating margins associated with AI-related products and features; 18 Table of Contents the impact of AI on the software creation industry and more generally within the software industry and on the demand for our platform, products, and services; general macroeconomic and political conditions, both domestically and in foreign markets where we operate, including, but not limited to, changes in U.S. federal spending, the imposition of trade barriers, tariffs, and other protectionist measures, global economic slowdowns, actual or perceived global banking and finance related issues, increased risk of inflation, uncertainty with respect to the U.S. federal debt ceiling and budget and potential U.S. federal government shutdowns related thereto, interest rate volatility, supply chain disruptions, labor shortages, and potential global recession;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-637e0f4961","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"In addition, in March 2025, we implemented significant changes to our pricing, packaging, and billing models. In 2025, we introduced AI credits across all Figma seats. Starting in March 2026, we intend to begin enforcing AI credit limits and start rolling out the ability for customers to purchase an additional AI credit subscription or opt into a pay-as-you-go AI credit plan based on their needs. Accordingly, we have a limited operating history at our current scale of business, and with our current product offerings and pricing, packaging, and billing models, which makes it difficult to evaluate our current business, future prospects, and other trends.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-52aee4d587","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"However, we expect our Net Dollar Retention Rate to fluctuate or decline in the future as a result of a number of factors such as the growing level of our revenue base, the level of penetration within our customer base, expansion of products and features, our ability to retain our customers, and any changes to the pricing and packaging of our plans. We expect to continue to make significant expenditures related to the development and expansion of our business, including, but not limited to, expenditures related to acquiring new customers, expanding relationships with existing customers, expanding our global footprint, developing and expanding our platform, growing our sales and marketing investments, expanding our operations both domestically and internationally, and integrating AI, including generative AI, into our platform. We also expect to continue to incur expenditures related to legal, tax, accounting, and other administrative and compliance expenses related to operating as a public company.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228","0001628280-26-035209","0001628280-26-053348"],"forms":{"10-K":1,"10-Q":2},"first":"2026-02-18","last":"2026-08-05","end":null},{"id":"1579878-da60bd6c25","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"We made these changes to keep pace with our expanded offerings and features since our platform’s launch and to provide our customers with more visibility and upfront controls. In 2025, we also introduced AI credits across all Figma seats. Starting in March 2026, we intend to begin enforcing AI credit limits and start rolling out the ability for customers to purchase an additional AI credit subscription or opt into a pay-as-you-go AI credit plan based on their needs. We may become unable to attract new customers and retain existing customers at the same price or based on the same seat-based subscription model that we have used historically. As a result, we may from time to time decide to make further changes to our billing models due to a variety of reasons, including, but not limited to, changes to the markets for our products and services, increased use of AI in the software industry generally, increased implementation and use of AI features in our products, pricing pressures, and the introduction of new products and services by us or by our competitors. If we are unable to implement changes to our billing models in a timely manner or at all, including as a result of delays associated with our billing infrastructure or product development processes, our business, operating results, and financial condition could be negatively impacted. Our new pricing, packaging, and billing models may not accurately reflect the optimal pricing, packaging, and billing models necessary to attract new customers and retain existing customers, which may make it difficult to accurately plan and forecast our operating results. Furthermore, the changes to our pricing and packaging plans introduced in March 2025 have made, and any further changes to components of our pricing, packaging, and billing models that we may introduce in the future, including our planned enforcement of AI credit limits starting in March 2026, may make, forecasting our operating results more difficult and result in comparisons to periods prior to the updates being less meaningful as some of the drivers underlying our business model will have changed. In addition, we may offer, or customers may demand, options that change who bears the cost of AI usage or how AI usage is provisioned, including by allowing customers to use their own third-party AI credentials or accounts (for example, bring-your-own-key arrangements), which may reduce the amount of AI usage that is metered through our AI credit programs. Such arrangements may increase certain costs (including, but not limited to, costs relating to engineering, infrastructure, security, compliance, and support), impact our margins, materially change the amount, mix, and timing of our revenue, and make our operating results harder to forecast. The net impact of any such arrangements on our revenue, margins, and cash flows may be difficult to predict and may vary across customers, products, and periods. Any such arrangements could also reduce our ability to meter, price, and control AI usage, and increase billing complexity, support burdens, and disputes. Customers may also use, or third parties may develop, tools that automate or orchestrate workflows on our platform (including through browser extensions, plugins, scripts, bots, or other third-party tools), which could reduce the number of paid seats required for a given level of output, circumvent or undermine our intended pricing and packaging controls, increase platform load, or create fraud and abuse risk.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-8b95b41810","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Our ability to increase or maintain our prices may be constrained by competitive dynamics, customer expectations or pressure to provide discounts, or economic conditions. Competitive dynamics may result in customers expecting full AI functionality to be included in baseline subscription pricing, which may lead customers to curtail their use of our products and features subject to AI credit pricing, including Figma Make and other AI features, or to stop using those products and features altogether, and may limit our ability to price our AI products and features in a manner that offsets associated costs. In addition, the unit economics of AI products and features may be volatile and difficult to predict, including due to changes in third-party model pricing, infrastructure costs, usage patterns, and the rate at which customers adopt AI-powered workflows. If we are unable to increase prices to offset rising costs, including costs related to AI inference or otherwise related to providing AI features, or if price increases significantly reduce customer demand, our business, operating results, and financial condition could be negatively impacted. Further, as AI and its integration into software becomes more prevalent and its use cases become more sophisticated, including with respect to our products and the products of our competitors, there could be a decrease in the number of designers, developers, and other collaborators that use our platform if such individuals are able to significantly increase their efficiency through the use of AI capabilities alongside or instead of our platform. Such a decrease could reduce the 21 Table of Contents number of seats that customers or potential customers subscribe to, which could lead to a loss of revenue, slower growth, and adversely impact our business, operating results, and financial condition. In response to any industry changes resulting from AI, we may need to make further changes to our billing models. Changes to our pricing, packaging, and billing models, including the changes to our pricing and packaging plans introduced in March 2025 and the planned enforcement of AI credit limits starting in March 2026, and any further changes that we make in the future, may, among other things, result in customer dissatisfaction, lead to a loss of customers, result in customers curtailing or stopping their usage of our products and features subject to AI credit pricing, including Figma Make and other AI features, harm our brand, and negatively impact our business, operating results, and financial condition. Over time, we expect to introduce products, features, and services, or otherwise implement pricing and packaging models, that are billed differently than on a per-seat subscription basis, which could adversely affect our business, operating results, financial condition, and future prospects. Over time, we expect to introduce products, features, and services, or to otherwise implement pricing and packaging models, that are billed differently than on a per-seat subscription basis. For example, in 2025, we introduced AI credits across all Figma seats. Starting in March 2026, we intend to begin enforcing AI credit limits and start rolling out the ability for customers to purchase an additional AI credit subscription or opt into a pay-as-you-go AI credit plan based on their needs. Credit-based, usage-based, or outcome-based billing models increase the complexity of accurately measuring and charging for product usage, and may increase the risk of billing disputes, refunds, chargebacks, and regulatory scrutiny. As we begin enforcing AI credit limits and introducing options for customers to purchase an additional AI credit subscription or opt into to a pay-as-you-go AI credit plan based on their needs, we expect that the mechanisms by which we meter, attribute, and report usage will become more complex. Errors or perceived errors in our usage measurement, billing calculations, invoicing, proration, credits, or refund processes could result in customer dissatisfaction, disputes, non-payment, increased customer support costs, and harm to our reputation.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-484bd0a13f","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Customers have no obligation to renew a subscription after the expiration of the contract term, and customers may not renew their subscriptions with a similar contract period, with the same or greater number of seats, for the same subscription plan, or at all. In addition, starting in March 2026, we intend to begin enforcing AI credit limits and start rolling out the ability for customers to purchase an additional AI credit subscription or opt into a pay-as-you-go AI credit plan based on their needs. Customers are under no obligation to purchase an AI credit subscription or opt into a pay-as-you-go AI credit plan, and they may curtail or stop their usage of our AI-powered products and features at any time. If our customers do not renew their subscriptions or if they renew on terms less favorable to us, or if our customers curtail or stop their usage of our AI-powered products and features in light of our upcoming AI credit billing model, our business, operating results, financial condition, and future prospects may be adversely impacted. Our customer retention may decline or fluctuate as a result of various factors, including, but not limited to, their satisfaction with our platform, products, and services and satisfaction with those offered by competitors, our pricing, packaging, and billing models and changes to such models including our recent and any future pricing changes, and the effects of general economic conditions and uncertainty in financial markets.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-c20f81d832","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"decreased spending on product design solutions and other products and services that we offer; the impact of AI on the markets for our products and services; and general macroeconomic and geopolitical conditions.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228","0001628280-26-035209","0001628280-26-053348"],"forms":{"10-K":1,"10-Q":2},"first":"2026-02-18","last":"2026-08-05","end":null},{"id":"1579878-eb64fd9735","kind":"annual","source":null,"discloses":"ai_harm","mit":["2.1","2.2","6.3"],"primary":"2.1","status":"hypothetical","harm":["Human or fundamental rights","Economic/Property","Reputational"],"layers":["capability"],"whose":["own"],"relation":["within_purpose"],"misuse_by":[],"subjects":[],"text":"There can be no assurance that customer demand for such initiatives will exist or be sustained at the levels that we anticipate, or that any of these initiatives will gain sufficient traction or market adoption to generate sufficient revenue to offset any new expenses or liabilities associated with these new investments. It is also possible that products and services developed by others, including, but not limited to, new technologies integrating AI, or products and services developed by competitors that employ a credit-based, usage-based, or outcome-based pricing model, will render our platform and offerings uncompetitive or obsolete. Further, our development efforts with respect to new technologies, offerings, features, and functionality could distract management from current operations, and would divert capital and other resources from our more established offerings. If we do not realize the expected benefits of our investments, our business, operating results, financial condition, and future prospects could be adversely affected. 24 Table of Contents Competitive developments in AI and our inability to effectively respond to such developments could adversely affect our business, operating results, and financial condition. Developments in AI are already impacting the software industry significantly, and we expect this impact to be even greater in the future. AI has become more prevalent in the markets in which we operate and may result in significant changes in the demand for our platform, including, but not limited to, reducing the difficulty and cost for competitors to build and launch competitive products, altering how consumers and businesses interact with websites and apps and consume content in ways that may result in a reduction in the overall value of interface design, or by otherwise making aspects of our platform obsolete or decreasing the number of designers, developers, and other collaborators that utilize our platform. Any of these changes could, in turn, lead to a loss of revenue and adversely impact our business, operating results, and financial condition. While we have made, and expect to continue to make, significant investments to integrate AI, including generative AI, into our platform, AI technologies are rapidly evolving and there can be no guarantee that our products will remain competitive as new AI technologies are developed, adopted, and integrated into software solutions. We expect that increased investment will be required in the future to continuously improve our use of AI technologies. As with many technological innovations, there are significant risks involved in developing, maintaining, and deploying AI. There can be no assurance that the integration of such technologies will enhance our products or services or be beneficial to our business, including, but not limited to, with respect to our efficiency or profitability. Similarly, we cannot guarantee that our investments in the development and integration of AI will be successful or provide an adequate return, including, without limitation, with respect to the amount of time, focus, and staffing directed towards these efforts. Our announced or perceived AI roadmap and product strategy may create heightened expectations among customers and investors, and if we fail to meet those expectations, our business, operating results, financial condition, and future prospects could be adversely affected. As AI models and tooling improve, customers may increasingly expect higher quality outputs, faster iteration cycles, greater reliability, and more seamless end-to-end workflows from design and development platforms. If we do not keep pace with these rising expectations, customers may reduce usage, delay or forgo purchases, or switch to competing products. In addition, customer expectations regarding the speed, availability, and performance of AI features may increase over time, which could require us to incur higher infrastructure and model costs that we may not be able to recover through pricing. Our ability to keep pace with these expectations may depend on our continued access to advanced third-party AI models and sufficient inference capacity, including from a limited number of foundational model providers. If we are unable to secure or maintain such access on commercially reasonable terms, or if such providers impose usage restrictions, experience outages, or face capacity constraints, our AI features may be delayed, degraded, or unavailable, which could adversely affect our business, operating results, and financial condition. Further, our competitors may incorporate AI into their products more quickly or more successfully than we do, which would impair our ability to compete effectively. Decisions as to if and how to integrate various AI technologies are difficult and we may choose not to adopt certain technologies or take advantage of certain data sets available to us as a result of ethical, legal, regulatory, or reputational concerns, which could put us at a competitive disadvantage and harm our business, operating results, and financial condition. For example, we, or our customers, may choose, or be required, not to use some high-performing or low-cost open-source models due to security, compliance, export control, sanctions, procurement, or reputational considerations. If our competitors use such models and no comparable alternative is available, we could be at a competitive disadvantage and our business, operating results, and financial condition may be harmed as a result. In the future, we may seek to train, fine-tune, co-train, or otherwise customize AI models with third parties or using additional datasets. These efforts may be costly, may not succeed, and could increase risks related to data rights, privacy, security, intellectual property, regulatory compliance, and partner dependency, any of which could adversely affect our business and reputation. AI technologies are rapidly changing how digital products and experiences are being designed, prototyped, and built. These shifts may be unpredictable and could include new interaction paradigms, devices, or form factors (such as through AI agents or assistants, conversational or voice-driven workflows, mixed reality or other new form factors, or experiences delivered through operating systems or a small number of ecosystems). This may 25 Table of Contents change how people access and interact with digital products in ways that reduce reliance on traditional software applications, websites, and graphical user interfaces.","ev":{"mit:2.1":"could increase risks related to data rights, privacy, security, intellectual property, regulatory compliance, and partner dependency","mit:2.2":"could increase risks related to data rights, privacy, security, intellectual property, regulatory compliance, and partner dependency","mit:6.3":"altering how consumers and businesses interact with websites and apps and consume content in ways that may result in a reduction in the overall value of interface design, or by otherwise making aspects of our platform obsolete or decreasing the number of designers, developers, and other collaborators that utilize our platform","harm:Human or fundamental rights":"could increase risks related to data rights, privacy, security, intellectual property, regulatory compliance, and partner dependency","harm:Economic/Property":"Any of these changes could, in turn, lead to a loss of revenue and adversely impact our business, operating results, and financial condition.","harm:Reputational":"any of which could adversely affect our business and reputation","layer:capability":"AI technologies are rapidly evolving and there can be no guarantee that our products will remain competitive","whose:own":"While we have made, and expect to continue to make, significant investments to integrate AI, including generative AI, into our platform","relation:within_purpose":"While we have made, and expect to continue to make, significant investments to integrate AI, including generative AI, into our platform"},"rev":null,"harm_quote":"could increase risks related to data rights, privacy, security, intellectual property, regulatory compliance, and partner dependency","status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-d729d5c6c2","kind":"annual","source":null,"discloses":"ai_harm","mit":["7.2","4.3","4.2","3.1","7.3"],"primary":"7.2","status":"hypothetical","harm":["Public interest","Economic/Property","Reputational"],"layers":["systemic","human_interaction","capability"],"whose":["general"],"relation":["within_purpose","misuse"],"misuse_by":["third_party"],"subjects":[{"name":"companies offering AI-enabled products","type":"Organization"}],"text":"For example: customers may consolidate purchasing decisions around vendors that bundle AI capabilities across broader software suites or purchase from other vendors that provide end-to-end “design-to-code” or “prompt-to-product” experiences; organizations may reduce the number of designers, developers, or collaborators required to deliver products, which may lead to them reducing the number of seats purchased or renewed even if output increases; customers may shift preferences from per-seat subscriptions to credit-based, usage-based, or outcome-based billing models, which may increase pricing pressure, reduce predictability of revenue, and adversely affect our margins; and switching costs may decline as AI tools improve interoperability, automated conversion of files, or automated recreation of design systems across platforms. If these changes reduce demand for our platform or disrupt our monetization model, this could adversely affect our business, operating results, and financial condition. Our failure to successfully develop or commercialize our products or services involving AI technologies could impact the price of our Class A common stock and impair our ability to raise capital, expand our business, improve and diversify our product offerings, efficiently manage our operating expenses, and respond effectively to competitive developments. Moreover, the use of AI technologies and our investments to integrate AI into our platform may adversely impact our business, operating results, and financial condition. For example, in the short term, we expect that our AI investments and use of AI technologies, including as part of Figma Make and our other AI features, will negatively impact our gross margins and operating margins and, given the newness of and rapid development of these technologies, the impacts on our gross margins and operating margins, and on our business, operating results, financial condition, and future prospects over the longer term, are currently unknown. More generally, advances in AI could be transformative and may occur more rapidly than anticipated. The development of highly capable general-purpose or autonomous AI systems, including the potential emergence of artificial general intelligence or superintelligence, could lead to significant economic, societal, political, and geopolitical disruption. Such disruption could reduce demand for our products, change how organizations staff and budget for design and product development, and increase volatility in customer spending. It could also prompt governments to adopt emergency measures or sweeping new regulations, restrictions, or moratoria on the development, deployment, or use of advanced AI systems, or to regulate access to compute, chips, energy, or cloud infrastructure, any of which could increase our costs, delay or limit our ability to offer AI features, or require us to materially modify our products, business model, or operations. In addition, serious harms attributed to advanced AI systems, including widespread fraud, cyberattacks, misinformation, or other safety incidents, could increase litigation risk and reputational harm for companies offering AI-enabled products, even where such harms are caused by third parties or are outside our control. Any of the foregoing could adversely affect our business, operating results, and financial condition.","ev":{"mit:7.2":"The development of highly capable general-purpose or autonomous AI systems, including the potential emergence of artificial general intelligence or superintelligence, could lead to significant economic, societal, political, and geopolitical disruption.","mit:4.3":"serious harms attributed to advanced AI systems, including widespread fraud","mit:4.2":"serious harms attributed to advanced AI systems, including widespread fraud, cyberattacks","mit:3.1":"serious harms attributed to advanced AI systems, including widespread fraud, cyberattacks, misinformation","mit:7.3":"serious harms attributed to advanced AI systems, including widespread fraud, cyberattacks, misinformation, or other safety incidents","harm:Public interest":"could lead to significant economic, societal, political, and geopolitical disruption","harm:Economic/Property":"Such disruption could reduce demand for our products, change how organizations staff and budget for design and product development, and increase volatility in customer spending.","harm:Reputational":"serious harms attributed to advanced AI systems, including widespread fraud, cyberattacks, misinformation, or other safety incidents, could increase litigation risk and reputational harm for companies offering AI-enabled products","layer:systemic":"could lead to significant economic, societal, political, and geopolitical disruption","layer:human_interaction":"widespread fraud, cyberattacks, misinformation","layer:capability":"or other safety incidents","whose:general":"advances in AI could be transformative and may occur more rapidly than anticipated","relation:within_purpose":"The development of highly capable general-purpose or autonomous AI systems","relation:misuse":"even where such harms are caused by third parties or are outside our control","misuse_by:third_party":"even where such harms are caused by third parties or are outside our control"},"rev":null,"harm_quote":"The development of highly capable general-purpose or autonomous AI systems, including the potential emergence of artificial general intelligence or superintelligence, could lead to significant economic, societal, political, and geopolitical disruption.","status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-d8b68d2c9b","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The markets in which we participate are rapidly evolving and highly competitive, and if we do not compete effectively, our business, operating results, and financial condition could be adversely impacted. We face competition from a number of companies, including companies that cater to multiple stages of the design and development process, point tools that address individual parts of the process but can expand to cover more, and design-to-code and AI-driven companies and tools that compress or accelerate steps in the workflow, take 26 Table of Contents a different approach to building digital experiences, or automatically generate and iterate on designs and code through a prompt or with limited human input. We may also face competition from customized or internal solutions used by our customers or potential customers, particularly with AI’s potential to accelerate the ability to develop and deploy new software. Moreover, we expect to continue to face intense competition from current competitors, as well as from new entrants into the market, including as a result of strategic acquisitions and partnerships, increased use of AI, or evolving user and customer requirements and industry standards. If we are unable to anticipate or react to these challenges, our competitive position could weaken, and we may experience a decline in revenue, reduced revenue growth, or a loss of market share, which, individually or collectively, could adversely affect our business, operating results, and financial condition.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-511c699c15","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"the extent of market adoption of our platform, and the timing of such market adoption, which may be influenced by developments and enhancements we introduce to our platform relative to the developments and enhancements made to competitive products available in the market; the impact of AI on the markets for our products and services, including, but not limited to, our ability to successfully incorporate AI technologies into our platform and successfully adapt our billing models to the increased use of AI in the software industry generally; the budgeting cycles, seasonal buying patterns, and purchasing practices of our customers, including, but not limited to, any slowdown in software spending;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228","0001628280-26-035209","0001628280-26-053348"],"forms":{"10-K":1,"10-Q":2},"first":"2026-02-18","last":"2026-08-05","end":null},{"id":"1579878-35844ef645","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Because the markets for our products and services are relatively new and rapidly evolving, it is difficult to predict customer adoption, customer and user demand for our products and services, the size and growth rate of these markets, the entry of competitive products and services, or the success of existing competitive services. It is also difficult to predict the impact of AI on our markets. Any expansion or contraction in our markets depends on a number of factors, including, but not limited to, the cost, performance, and perceived value associated with our platform and the appetite and ability of customers to pay for and subscribe to our platform.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027","0001628280-25-049683","0001628280-26-009228","0001628280-26-035209"],"forms":{"10-K":1,"10-Q":3},"first":"2025-09-03","last":"2026-05-14","end":null},{"id":"1579878-6d78b8521b","kind":"annual","source":null,"discloses":"ai_harm","mit":["7.3","1.2","1.1","3.1","2.1","2.2","6.3"],"primary":"7.3","status":"materialised","harm":["Human or fundamental rights","Economic/Property","Reputational"],"layers":["capability","human_interaction"],"whose":["own","general"],"relation":["within_purpose","misuse"],"misuse_by":["user","third_party"],"subjects":[{"name":"end users","type":"Group of persons"},{"name":"customers","type":"Organization"},{"name":"third-party","type":"Other"}],"text":"If the 28 Table of Contents markets for our platform do not grow to the extent that we anticipate or our platform does not achieve further widespread adoption within the markets in which we operate, our business, operating results, financial condition, and future prospects could be adversely affected. Our use of AI in our products and services may result in reputational harm, legal liability, competitive risks, and regulatory concerns that could adversely affect our business, operating results, and financial condition. We have made, and expect to continue to make, significant investments to integrate AI, including generative AI, and machine learning technology into our platform, including as part of our Figma Make product and Figma AI features. Many AI technologies are relatively new and present ethical, legal, regulatory, and reputational challenges. The use of datasets to develop AI models, the content generated by AI systems, or the application of AI systems may be found to be insufficient, offensive, biased, or harmful, or may violate current or future laws and regulations or contractual commitments. Standards and expectations regarding AI safety, acceptable outputs, and appropriate safeguards are evolving and may differ across our industry, customers, regulators, and the public, including across different geographies, cultures, and political environments, and there may be no consensus on what constitutes safe behavior for a given use case. We may be unable or unwilling to implement controls that satisfy all such expectations, and our decisions about whether and how to restrict or moderate AI outputs could result in customer dissatisfaction, reputational harm, or regulatory scrutiny. Certain AI technologies have come under public scrutiny due to allegations that they generate inaccurate, incomplete, or misleading content, introduce unintended biases, and produce other discriminatory or unexpected results, errors, or inadequacies. Consumer and societal attitudes toward AI are evolving and there is a risk that regulators or the public may perceive AI technologies negatively. Concerns about automation, automated decision-making, privacy, security, transparency, and other ethical considerations could deter AI adoption. The insurance coverage we maintain may not extend to all AI-related risks we may face, and may not cover us for all losses for errors or omissions caused by AI. Further, we generally rely on third-party models for the AI features on our platform. Our ability to continue to use such technologies at scale may be dependent on access to certain limited or specific third-party software and infrastructure providers. We cannot control the availability or pricing of such third-party AI technologies, especially in a highly competitive environment, and we may be unable to negotiate favorable economic terms with the applicable providers. Providers may also experience capacity constraints or prioritize other customers, which could limit the availability or performance of our AI features. If any such third-party AI technologies become incompatible with our platform or unavailable for use, or if the providers of such models unfavorably change the terms on which their AI technologies are offered or terminate their relationship with us, our platform may become less appealing to our customers, and our business, operating results, and financial condition could be adversely impacted. Moreover, the integration of third-party AI models with our platform relies on certain safeguards implemented by the third-party developers of the underlying AI models, including those related to the accuracy, bias, and other variables of the training data used for such models, and these safeguards may be insufficient. If the models underlying our AI technologies, whether developed by a third party or developed by us, are incorrectly designed or implemented; trained or reliant on incomplete, inadequate, inaccurate, biased or otherwise poor quality data, or on data to which we do not have sufficient rights or in relation to which we and/or the providers of such data have not implemented sufficient legal compliance measures; used without sufficient oversight and governance to ensure their responsible use; and/or adversely impacted by unforeseen defects, technical challenges, cybersecurity threats, or material performance issues, the performance of our products, services, and business, as well as our reputation and our customers’ reputations, could suffer, and we could incur liability resulting from the violation of laws, breach of contract claims, or civil claims. For example, we are, and may in the future become, subject to litigation alleging breach of contract and related claims arising from allegations regarding the use of user data in connection with AI training, trade secret misappropriation, and violations of various state and federal statutes. Such claims can be costly to defend, may result in adverse judgments or settlements, may require changes to our products, policies, contracts, or business practices (including limitations on certain AI features or how data may be processed), and could harm our reputation and relationships with users. Further, claims, litigation, or regulatory actions relating to AI data practices may seek remedies beyond monetary damages, including injunctive relief, and could require us to make material changes 29 Table of Contents to our products or business practices. Any such changes could be costly, technically complex, and disruptive to our product roadmap and operations, could reduce the performance or usefulness of our AI features, and could adversely affect customer relationships, revenue, and growth. In addition, the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information. Such leakage or unauthorized exposure of data related to the use of AI applications could result in legal claims or liability or otherwise adversely affect our reputation and operating results. The above risks may be increased by the introduction of our Figma Weave product, which contains many AI models, some of which are entirely independent third-party models that are provided to customers “as is.” AI products and features may introduce additional security vulnerabilities and threat vectors beyond traditional software risks (including prompt injection, data poisoning, model inversion, membership inference, latent or hidden behaviors that are difficult to detect in testing and that may be triggered under certain conditions, and other attacks designed to cause models to disclose sensitive information), behave in unintended ways, or produce harmful or misleading outputs. Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage. Such activity could increase our costs (including AI inference and support costs), result in fraud, billing disputes, or chargebacks, and cause reputational harm or liability. In addition, the use of third-party models and toolchains may increase supply-chain risk, including the risk that model weights, safety layers, or dependencies are compromised, misconfigured, or updated in ways that degrade security or performance. If any of these vulnerabilities result in the unauthorized disclosure of customer content, confidential information, personal data, or proprietary information, or if customers believe our AI features are not sufficiently secure for their use cases, we could face contractual claims, indemnity demands, regulatory scrutiny, reputational harm, and reduced adoption of our AI features or platform. Moreover, our AI technologies could generate output that infringes on third-party intellectual property rights, and we could be subject to claims or lawsuits, including, but not limited to, for infringement of third-party intellectual property rights as a result of the output of such AI technologies. While some providers of AI technologies offer to indemnify their end users for any copyright or other intellectual property infringement claims arising from the output of their AI technologies, such indemnification may be inadequate or we may not be successful in adequately recovering our losses in connection with such claims. Our AI technologies could also generate content that is inaccurate, misleading, or inappropriate, which could harm our reputation, expose us to liability, or cause customers to lose confidence in our platform. The regulatory framework for AI technologies is rapidly evolving as many U.S. federal, state, and foreign government bodies and agencies have introduced or are currently considering additional laws and regulations. Additionally, existing laws and regulations may be interpreted in ways that would affect the operation of our AI technologies or could be rescinded or amended as new administrations take differing approaches to evolving AI technologies. As a result, implementation standards and enforcement practices are likely to remain uncertain for the foreseeable future, and we cannot yet completely determine the impact future laws, regulations, standards, or market perception of their requirements may have on our business and may not always be able to anticipate how to respond to these laws or regulations. Already, certain existing legal regimes, for example, relating to data privacy, regulate certain aspects of AI technologies, and new laws regulating AI technologies have recently entered into force in the United States and the EEA. In the United States, there is an ongoing tension between the states and the federal government over how best to regulate the use of AI. While a number of U.S. states, such as California and Colorado, have proposed or enacted laws regarding automated decision‑making, algorithmic discrimination, and so-called “high‑risk” AI technologies (mandating, among other provisions, requirements for risk management, impact assessments, consumer notices, and human oversight), which may impact our use of AI and AI-powered tools. However, the status of such laws is currently uncertain. Any such additional regulation may impact our ability to develop, use, and commercialize AI technologies in the future. In Europe, the EU Artificial Intelligence Act (the “EU AI Act”) establishes a comprehensive, risk-based governance framework for AI in the EU market. The EU AI Act will have a material impact on the way AI is regulated in the EU, as it applies to companies that develop, use, and/or provide AI in the EU and, depending 30 Table of Contents on the AI use case, includes requirements around transparency, conformity assessments and monitoring, risk assessments, human oversight, security, accuracy, general purpose AI, and foundation models, and imposes substantial fines for breaches. The EU AI Act, together with developing guidance and/or decisions in this area, may affect our use of AI technologies and our ability to provide, improve, or commercialize our services, require additional compliance measures and changes to our operations and processes, result in increased compliance costs and potential increases in civil claims against us, and could adversely affect our business, operating results, and financial condition. It is possible that further new laws and regulations will be adopted in the United States and in other non-U.S. jurisdictions, or that existing laws and regulations, including competition and antitrust laws, may be interpreted in ways that would limit our ability to use AI technologies for our business, or require us to change the way we use AI technologies in a manner that negatively affects the performance of our offerings and the way in which we use AI technologies. We may need to expend resources to adjust our products, services, or operating procedures in certain jurisdictions if the laws, regulations, or decisions regarding AI technologies are not consistent across jurisdictions. Further, the cost to comply with such laws, regulations, or decisions and/or guidance interpreting existing laws, could be significant and would increase our operating expenses (such as by imposing additional reporting and compliance obligations regarding our use of AI technologies). Such an increase in operating expenses, as well as any actual or perceived failure to comply with such laws and regulations, could adversely affect our business, operating results, and financial condition. Moreover, any changes to the above discussed existing legal regimes with respect to data privacy and AI technologies within the United States and abroad could require us to expend significant resources to modify our products, services, or operations to ensure compliance or remain competitive. Existing and future acquisitions, strategic investments, partnerships, or alliances could be difficult to identify and integrate, divert the attention of key management personnel, disrupt our business, dilute stockholder value, and adversely affect our business, operating results, financial condition, and future prospects.","ev":{"status":"we are, and may in the future become, subject to litigation alleging breach of contract and related claims arising from allegations regarding the use of user data in connection with AI training","mit:7.3":"AI products and features may introduce additional security vulnerabilities and threat vectors beyond traditional software risks (including prompt injection, data poisoning, model inversion, membership inference, latent or hidden behaviors that are difficult to detect in testing and that may be triggered under certain conditions, and other attacks designed to cause models to disclose sensitive information), behave in unintended ways, or produce harmful or misleading outputs","mit:1.2":"the content generated by AI systems, or the application of AI systems may be found to be insufficient, offensive, biased, or harmful","mit:1.1":"Certain AI technologies have come under public scrutiny due to allegations that they generate inaccurate, incomplete, or misleading content, introduce unintended biases, and produce other discriminatory or unexpected results, errors, or inadequacies","mit:3.1":"Our AI technologies could also generate content that is inaccurate, misleading, or inappropriate, which could harm our reputation, expose us to liability, or cause customers to lose confidence in our platform","mit:2.1":"the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information","mit:2.2":"Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage","mit:6.3":"our AI technologies could generate output that infringes on third-party intellectual property rights, and we could be subject to claims or lawsuits, including, but not limited to, for infringement of third-party intellectual property rights as a result of the output of such AI technologies","harm:Human or fundamental rights":"the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information","harm:Economic/Property":"we could incur liability resulting from the violation of laws, breach of contract claims, or civil claims","harm:Reputational":"Such leakage or unauthorized exposure of data related to the use of AI applications could result in legal claims or liability or otherwise adversely affect our reputation and operating results","layer:capability":"Our AI technologies could also generate content that is inaccurate, misleading, or inappropriate, which could harm our reputation, expose us to liability, or cause customers to lose confidence in our platform","layer:human_interaction":"Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage","whose:own":"We have made, and expect to continue to make, significant investments to integrate AI, including generative AI, and machine learning technology into our platform, including as part of our Figma Make product and Figma AI features","whose:general":"Many AI technologies are relatively new and present ethical, legal, regulatory, and reputational challenges","relation:within_purpose":"Our AI technologies could also generate content that is inaccurate, misleading, or inappropriate, which could harm our reputation, expose us to liability, or cause customers to lose confidence in our platform","relation:misuse":"Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage","misuse_by:user":"Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage","misuse_by:third_party":"Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage"},"rev":null,"harm_quote":"AI products and features may introduce additional security vulnerabilities and threat vectors beyond traditional software risks (including prompt injection, data poisoning, model inversion, membership inference, latent or hidden behaviors that are difficult to detect in testing and that may be triggered under certain conditions, and other attacks designed to cause models to disclose sensitive information), behave in unintended ways, or produce harmful or misleading outputs","status_quote":"we are, and may in the future become, subject to litigation alleging breach of contract and related claims arising from allegations regarding the use of user data in connection with AI training","reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-bf9ad09c90","kind":"annual","source":null,"discloses":"ai_harm","mit":["4.2","2.2","4.3","2.1"],"primary":"4.2","status":"hypothetical","harm":["Economic/Property","Human or fundamental rights"],"layers":["human_interaction"],"whose":["own","others"],"relation":["misuse"],"misuse_by":["third_party"],"subjects":[{"name":"customers","type":"Organization"}],"text":"Any security breach of our platform, our operational systems, physical facilities, or the systems of our third-party processors, or the perception that a breach has occurred, or other adverse impact to the availability, integrity, or confidentiality of such platform and systems, could result in litigation (including class actions), indemnity obligations, regulatory enforcement actions, investigations, compulsory audits, fines, penalties, mitigation and remediation costs, disputes, reputational harm, diversion of management’s attention, and other liabilities and damage to our business. We face evolving cybersecurity risks that threaten the confidentiality, integrity, and availability of our or our customers’ confidential or personal data and our and our third-party service providers’ information technology systems, which could result from human error, system misconfiguration, or from cyber-attacks, including distributed-denial-of-service attacks, reverse-engineering of AI algorithms, web scraping, ransomware attacks, business email compromises, credential stuffing, computer malware, viruses, and social engineering (including phishing, deepfakes, and voice cloning), software supply-chain compromises, malicious code embedded in open-source software, or misconfigurations, “bugs” or other vulnerabilities in commercial software that is integrated into our and our third-party service providers’ information technology systems, products or services, which are prevalent in our industry. These threats may come from a variety of sources, including nation-state sponsored espionage and hacking activities, corporate espionage, organized crime, sophisticated organizations, hacking groups and individuals, and insider threats.","ev":{"mit:4.2":"cyber-attacks, including distributed-denial-of-service attacks, reverse-engineering of AI algorithms, web scraping, ransomware attacks","layer:human_interaction":"cyber-attacks, including distributed-denial-of-service attacks, reverse-engineering of AI algorithms, web scraping, ransomware attacks","relation:misuse":"cyber-attacks, including distributed-denial-of-service attacks, reverse-engineering of AI algorithms, web scraping, ransomware attacks","misuse_by:third_party":"cyber-attacks, including distributed-denial-of-service attacks, reverse-engineering of AI algorithms, web scraping, ransomware attacks","mit:2.2":"reverse-engineering of AI algorithms","whose:own":"reverse-engineering of AI algorithms","mit:4.3":"social engineering (including phishing, deepfakes, and voice cloning)","whose:others":"social engineering (including phishing, deepfakes, and voice cloning)","mit:2.1":"We face evolving cybersecurity risks that threaten the confidentiality, integrity, and availability of our or our customers","harm:Human or fundamental rights":"We face evolving cybersecurity risks that threaten the confidentiality, integrity, and availability of our or our customers","harm:Economic/Property":"could result in litigation (including class actions), indemnity obligations, regulatory enforcement actions, investigations, compulsory audits, fines, penalties, mitigation and remediation costs"},"rev":null,"harm_quote":"cyber-attacks, including distributed-denial-of-service attacks, reverse-engineering of AI algorithms, web scraping, ransomware attacks","status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-46fb1f28b1","kind":"annual","source":null,"discloses":"ai_harm","mit":["4.2","2.1"],"primary":"4.2","status":"elsewhere","harm":["Economic/Property","Human or fundamental rights"],"layers":["human_interaction"],"whose":["others"],"relation":["misuse"],"misuse_by":["third_party"],"subjects":[],"text":"Further, the incidence of state-supported and geopolitical-related cyberattacks may rise in connection with regional geopolitical conflicts which have increased the risk of cyberattacks on various types of infrastructure and operations. Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges. As a result, we may be unable to detect, investigate, remediate, or recover from future attacks or incidents, or to avoid a material adverse impact to our information technology systems, confidential or personal data, or business.","ev":{"status":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks","mit:4.2":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges","mit:2.1":"we may be unable to detect, investigate, remediate, or recover from future attacks or incidents, or to avoid a material adverse impact to our information technology systems, confidential or personal data, or business","harm:Economic/Property":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges","harm:Human or fundamental rights":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges","layer:human_interaction":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges","whose:others":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges","relation:misuse":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges","misuse_by:third_party":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges"},"rev":null,"harm_quote":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges","status_quote":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks","reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-f649f08b3d","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"We may also encounter service interruptions, outages, or disruptions due to issues interfacing with our customers’ information technology systems, including, but not limited to, stack misconfigurations or improper environment scaling, defective updates or upgrades, our customers’ inability to access the internet, the failure of our network or software systems, security breaches, variability in user traffic for our platform, or due to cybersecurity attacks on our or our customers’ information technology systems. For example, if our cloud hosting provider or the hosting provider of any of our third-party technology partners, including AI partners, were to experience interruptions, delays, outages, or other service interruptions, including as a result of customer demand, that may impact our ability to provide service to our customers. We may be required to issue credits or refunds or otherwise be liable to our customers for damages they may incur resulting from certain of these events.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-25-049683","0001628280-26-009228","0001628280-26-053348"],"forms":{"10-K":1,"10-Q":2},"first":"2025-11-05","last":"2026-08-05","end":null},{"id":"1579878-b814c062b0","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Additionally, with the importance and impact of social media, any negative publicity regarding our policies and practices or organizational decisions or actions by members of our team, including those taken in a personal capacity or unrelated to their roles at our company, may be magnified and reach a large portion of our users, customers, and employees in a very short period of time, which could harm our brand and reputation and adversely affect our business, operating results, and financial condition. Our public statements, marketing materials, customer communications, and disclosures regarding our products (including AI products and features), privacy and security practices, reliability, and pricing, packaging, and billing models may be subject to differing interpretations and may evolve over time, and alleged inconsistencies could expose us to claims or regulatory scrutiny. In particular, as we rapidly develop and introduce new products and AI features, we may update features, controls, defaults, documentation, and policies, and customers, users, regulators, or plaintiffs may assert that certain statements were incomplete, misleading, or inconsistent with their expectations. Such allegations could result in litigation (including class actions), regulatory investigations, enforcement actions, adverse publicity, or reputational harm, any of which could adversely affect our business, operating results, and financial condition.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228","0001628280-26-035209"],"forms":{"10-K":1,"10-Q":1},"first":"2026-02-18","last":"2026-05-14","end":null},{"id":"1579878-43d5c8567b","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"We rely on third-party service providers for critical components of our operations, and disruptions or changes in those services could adversely affect our business. In addition to AWS, we also depend on other third-party providers for services that are critical to the operation of our platform and business, including content delivery, identity and access management, payment processing, analytics and monitoring, and certain AI-related services. These providers may experience outages, capacity constraints, cybersecurity incidents, business interruptions, or financial distress, or may change pricing, service levels, security or compliance requirements, or contractual terms.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-6b967f05e0","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"tariffs, export and import restrictions, restrictions on foreign investments, sanctions, and other trade barriers or protectionist measures; exposure to numerous, increasing, stringent, and potentially inconsistent laws and regulations relating to, among other things, AI, privacy, data protection, online safety, moderation, and information security; difficulties in enforcing contracts, including “click-through” terms that are entered into online, which may be subject to legal uncertainty in some foreign jurisdictions;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228","0001628280-26-035209","0001628280-26-053348"],"forms":{"10-K":1,"10-Q":2},"first":"2026-02-18","last":"2026-08-05","end":null},{"id":"1579878-c0290fb76c","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"There can be no assurance that we will be able to hire sufficient support personnel as and when needed, particularly if our sales exceed our internal forecasts. Additionally, our customer support team uses third-party AI tools to assist them with responding to and resolving customer inquiries. To the extent that we are unsuccessful in hiring, training, and retaining adequate support resources or utilizing AI tools for customer support, our ability to provide high-quality and timely support to our customers will be negatively impacted, and our customers’ satisfaction and their usage of our infrastructure could be adversely affected. Because we primarily recognize subscription revenue over the subscription term, downturns or upturns in new sales and renewals are not immediately reflected in full in our operating results.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228","0001628280-26-035209"],"forms":{"10-K":1,"10-Q":1},"first":"2026-02-18","last":"2026-05-14","end":null},{"id":"1579878-56148f6878","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Our revenue recognition and operating results may be difficult to predict because of the length and unpredictability of the sales cycle for our platform, particularly as we increasingly sell to larger organizations, governmental entities, regulated entities, and organizations outside of the United States or to the technology industry that may have different procurement requirements than our historical customers. For example, we have observed a lengthening of the sales cycle recently for some prospective customers that we attribute to increased sensitivity to information technology security concerns, particularly with respect to products that include AI features or otherwise incorporate AI technologies, such as our platform. In addition, larger customers frequently have rigorous procurement processes and require considerable time to evaluate, test, and qualify our platform prior to entering into or expanding a relationship with us.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228","0001628280-26-035209"],"forms":{"10-K":1,"10-Q":1},"first":"2026-02-18","last":"2026-05-14","end":null},{"id":"1579878-dc16feee5a","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"More generally, the technology industry, and the software industry more specifically, is also subject to substantial and continuous competition for engineers with high levels of experience in designing, developing, and managing software and related services. This is especially true in the market for AI talent, which remains extremely competitive. We have, from time to time, experienced, and we expect to continue to experience, difficulty in hiring and retaining highly skilled employees with appropriate qualifications at a suitable cost, and this risk may be exacerbated by factors related to, among other things, increased recruiting efforts by other companies.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228","0001628280-26-035209"],"forms":{"10-K":1,"10-Q":1},"first":"2026-02-18","last":"2026-05-14","end":null},{"id":"1579878-003e735d0b","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Moreover, we may need to expend additional resources to defend our intellectual property rights in foreign countries, and our inability to do so could impair our business or adversely affect our international expansion. Furthermore, the application of intellectual property law to AI technologies is a new and emerging practice, and there is uncertainty and ongoing litigation in different jurisdictions as to the degree and extent of protection warranted for AI and machine learning systems and relevant system input and outputs. The law is also uncertain across jurisdictions regarding the copyright ownership of content that is produced in whole or in part by AI tools. As a result, our use of AI tools in our product development and engineering processes may make it difficult to assert ownership rights over our technology. If we fail to obtain protection for the intellectual property rights concerning our AI technologies, or later have our intellectual property rights invalidated or otherwise 48 Table of Contents diminished, our competitors may be able to take advantage of our research and development efforts to develop competing products which could adversely affect our business, reputation, and financial condition. In addition, given the long history of development of AI technologies, other parties may have, or in the future may obtain, patents or other proprietary rights that could prevent, limit, or interfere with our ability to make, use, or sell our own AI technologies. Third parties have claimed and may claim that our platform infringes, misappropriates, or otherwise violates their intellectual property rights and such claims could be time-consuming or costly to defend or settle, result in the loss of significant rights, or harm our relationships with our customers or reputation in the industry.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-6290002342","kind":"annual","source":null,"discloses":"ai_harm","mit":["6.3","7.3","2.2"],"primary":"6.3","status":"elsewhere","harm":["Economic/Property"],"layers":["capability","human_interaction"],"whose":["own","general"],"relation":["within_purpose","misuse"],"misuse_by":["third_party"],"subjects":[],"text":"A loss of key personnel or their work product could hamper or prevent our ability to develop, market, and support potential products or enhancements, which could severely harm our business. Further, we may use AI technologies, including tools provided by third parties, to develop or assist in the development of our own software code. While use of such tools makes our development process more efficient, 49 Table of Contents AI technologies have sometimes generated content that is “substantially similar” to proprietary or open source software code on which the AI tool was trained. If the AI technologies we use generate code that is too similar to other proprietary code, or to software processes that are protected by patents, we could be subject to intellectual property infringement claims. AI-generated code or other outputs may also introduce security vulnerabilities, compliance failures (including accessibility), or license obligations (including open source notices or attribution requirements). We may not be able to anticipate and detect security vulnerabilities in AI-generated software code, including those that could be induced by a maliciously trained AI model. If our tools generate code that is too similar to open source code, we risk losing protection of our own proprietary code that is commingled with such code. Finally, to the extent we use third-party AI technologies to develop software code, the terms of use of these tools may state that the third-party provider retains rights in the generated code. We may also face similar risks in using AI technologies to develop or assist in the development of other materials, such as advertising or marketing materials. Any intellectual property claims, whether with or without merit, could be very time-consuming, could be expensive to settle or litigate, and could divert our management’s attention and other resources, even if such claims do not result in litigation or are resolved in our favor.","ev":{"status":"AI technologies have sometimes generated content that is “substantially similar” to proprietary or open source software code on which the AI tool was trained","mit:6.3":"If the AI technologies we use generate code that is too similar to other proprietary code, or to software processes that are protected by patents, we could be subject to intellectual property infringement claims","mit:7.3":"AI-generated code or other outputs may also introduce security vulnerabilities, compliance failures (including accessibility), or license obligations","mit:2.2":"We may not be able to anticipate and detect security vulnerabilities in AI-generated software code, including those that could be induced by a maliciously trained AI model","harm:Economic/Property":"Any intellectual property claims, whether with or without merit, could be very time-consuming, could be expensive to settle or litigate","layer:capability":"AI-generated code or other outputs may also introduce security vulnerabilities, compliance failures (including accessibility), or license obligations","layer:human_interaction":"We may not be able to anticipate and detect security vulnerabilities in AI-generated software code, including those that could be induced by a maliciously trained AI model","whose:own":"we may use AI technologies, including tools provided by third parties, to develop or assist in the development of our own software code","whose:general":"those that could be induced by a maliciously trained AI model","relation:within_purpose":"we may use AI technologies, including tools provided by third parties, to develop or assist in the development of our own software code","relation:misuse":"We may not be able to anticipate and detect security vulnerabilities in AI-generated software code, including those that could be induced by a maliciously trained AI model","misuse_by:third_party":"We may not be able to anticipate and detect security vulnerabilities in AI-generated software code, including those that could be induced by a maliciously trained AI model"},"rev":null,"harm_quote":"If the AI technologies we use generate code that is too similar to other proprietary code, or to software processes that are protected by patents, we could be subject to intellectual property infringement claims","status_quote":"AI technologies have sometimes generated content that is “substantially similar” to proprietary or open source software code on which the AI tool was trained","reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-2059a794c4","kind":"annual","source":null,"discloses":"ai_harm","mit":["7.3"],"primary":"7.3","status":"hypothetical","harm":["Other"],"layers":["capability"],"whose":["own"],"relation":["within_purpose"],"misuse_by":[],"subjects":[],"text":"We license technology from third parties for the development of our products, and our inability to maintain those licenses could harm our business. We currently rely on or incorporate, and will in the future rely on or incorporate, technology that we license from third parties, including software and large language models, into our products. For example, Figma’s AI-powered products and features, including our Figma Make product, rely on off-the-shelf foundational AI models. If we are unable to continue to use or license these technologies on reasonable terms, or if these technologies become unreliable, unavailable, or fail to operate properly, we may not be able to secure adequate alternatives in a timely or cost-effective manner, or at all, and our ability to offer our products and remain competitive in our market would be harmed.","ev":{"mit:7.3":"if these technologies become unreliable, unavailable, or fail to operate properly","harm:Other":"if these technologies become unreliable, unavailable, or fail to operate properly","layer:capability":"if these technologies become unreliable, unavailable, or fail to operate properly","whose:own":"Figma’s AI-powered products and features, including our Figma Make product, rely on off-the-shelf foundational AI models","relation:within_purpose":"if these technologies become unreliable, unavailable, or fail to operate properly"},"rev":null,"harm_quote":"if these technologies become unreliable, unavailable, or fail to operate properly","status_quote":null,"reports":["0001579878-25-000027","0001628280-25-049683","0001628280-26-009228","0001628280-26-035209","0001628280-26-053348"],"forms":{"10-K":1,"10-Q":4},"first":"2025-09-03","last":"2026-08-05","end":null},{"id":"1579878-c578254d4b","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Risks Related to Legal and Regulatory Matters Our business is subject to complex and evolving U.S. and foreign laws, regulations, and industry standards, many of which are subject to change and uncertain interpretations, which uncertainty could harm our business, operating results, and financial condition. We are subject to many U.S. and foreign federal, state, and local laws, regulations, and industry standards that involve matters central to our business, including laws and regulations that involve data privacy, data security, intellectual property, including copyright and patent laws, AI technologies, antitrust and competition, online safety and moderation, employment, labor, immigration, consumer protection, public health, workplace safety, and taxation. These laws and regulations are constantly evolving and may be interpreted, applied, created, or amended, in a manner that could harm our business.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228","0001628280-26-053348"],"forms":{"10-K":1,"10-Q":1},"first":"2026-02-18","last":"2026-08-05","end":null},{"id":"1579878-25be82f3e0","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"In particular, we face challenges inherent in effectively and efficiently managing a workforce across a large number of jurisdictions, many of which have differing labor law requirements, including the need to implement appropriate systems, policies, benefits, and compliance programs. These challenges are accentuated by the use and proliferation of emerging technologies within our business, including AI-related technologies, the regulation of which is becoming increasingly complex, including with respect to labor laws and hiring practices. Compliance with such laws, regulations, and policies may require significant investment and expense.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-48d52ed653","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The adoption of European laws relating to the internet or other areas of our business could affect the manner in which we currently conduct our business. The EU Digital Services Act (the “DSA”) governs, among other things, our potential liability for illegal services or content on our platform, and requires enhanced transparency measures, including in relation to any recommendation systems (including the main parameters used by such systems and any available options for recipients to modify or influence them). The DSA may increase our compliance costs, require changes to our user interface, processes, operations, and business practices which may adversely affect our ability to attract, retain and provide our services to users, and may otherwise adversely affect our business, operating results, and financial condition.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228","0001628280-26-035209","0001628280-26-053348"],"forms":{"10-K":1,"10-Q":2},"first":"2026-02-18","last":"2026-08-05","end":null},{"id":"1579878-9d6771b05b","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"For example, our Class A common stock traded as high as approximately $124.63 per share on the first day of trading following our IPO and, as of February 17, 2026, traded as low as approximately $19.85 per share. The trading price of our Class A common stock may continue to be volatile and decline further, including for reasons unrelated to our operating performance, such as valuation compression due to investor sentiment regarding software, AI, or obsolescence risk. You may not be able to resell your shares at or above the price you paid for them, and could lose all or part of your investment in our Class A common stock.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228"],"forms":{"10-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-1145f00c38","kind":"annual","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"In addition, the stock market in general, and the market for technology companies in particular, has experienced price and volume fluctuations that have often been unrelated or disproportionate to the operating performance of those companies, particularly during the current period of global macroeconomic uncertainty. In particular, market sentiment regarding software-as-a-service business models, the pace of AI adoption, and the perceived risk that AI could reduce demand for, or change monetization of, design, development, and collaboration tools may contribute to valuation compression for our company and other software companies, even if our historical operating results and near-term financial performance remain relatively stable. These economic, political, regulatory, and market conditions may negatively impact the market price of our Class A common stock, regardless of our actual operating results.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009228","0001628280-26-035209","0001628280-26-053348"],"forms":{"10-K":1,"10-Q":2},"first":"2026-02-18","last":"2026-08-05","end":null},{"id":"1579878-dcb429ae15","kind":"annual","source":null,"discloses":"ai_harm","mit":["4.2","6.2","7.3"],"primary":"4.2","status":"hypothetical","harm":["Economic/Property","Physical (injury)","Physical (death)"],"layers":["human_interaction","systemic","capability"],"whose":["general"],"relation":["within_purpose","misuse"],"misuse_by":["third_party"],"subjects":[],"text":"Further, acts of war, armed conflict, terrorism, and other geopolitical instability or uncertainty could cause disruptions in our business, the businesses of our partners or customers, or the economy as a whole. Moreover, the risks associated with AI technology are still unknown and advances in AI could pose risks, including, but not limited to, cyberattacks, terrorism, disruption to labor markets, criminal misuse, autonomous warfare, and catastrophic accidents. In the event of a natural disaster, including, but not limited to, a major earthquake, blizzard, or hurricane, or a catastrophic event such as a fire, power loss, cyberattack, or telecommunications failure, we may be unable to continue our operations and may endure system interruptions, reputational harm, delays in development of our platform, lengthy interruptions in service, breaches of data security, and loss of critical data, all of which could have an adverse effect on our future operating results.","ev":{"mit:4.2":"advances in AI could pose risks, including, but not limited to, cyberattacks, terrorism, disruption to labor markets, criminal misuse, autonomous warfare, and catastrophic accidents","mit:6.2":"disruption to labor markets","mit:7.3":"catastrophic accidents","harm:Economic/Property":"advances in AI could pose risks, including, but not limited to, cyberattacks, terrorism, disruption to labor markets, criminal misuse, autonomous warfare, and catastrophic accidents","harm:Physical (injury)":"advances in AI could pose risks, including, but not limited to, cyberattacks, terrorism, disruption to labor markets, criminal misuse, autonomous warfare, and catastrophic accidents","harm:Physical (death)":"advances in AI could pose risks, including, but not limited to, cyberattacks, terrorism, disruption to labor markets, criminal misuse, autonomous warfare, and catastrophic accidents","layer:human_interaction":"criminal misuse","layer:systemic":"disruption to labor markets","layer:capability":"catastrophic accidents","whose:general":"advances in AI could pose risks, including, but not limited to, cyberattacks, terrorism, disruption to labor markets, criminal misuse, autonomous warfare, and catastrophic accidents","relation:within_purpose":"catastrophic accidents","relation:misuse":"criminal misuse","misuse_by:third_party":"criminal misuse"},"rev":null,"harm_quote":"advances in AI could pose risks, including, but not limited to, cyberattacks, terrorism, disruption to labor markets, criminal misuse, autonomous warfare, and catastrophic accidents","status_quote":null,"reports":["0001628280-26-009228","0001628280-26-035209","0001628280-26-053348"],"forms":{"10-K":1,"10-Q":2},"first":"2026-02-18","last":"2026-08-05","end":null},{"id":"1579878-3f425a753a","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"retain and increase adoption of our products and services by existing customers, as well as attract new customers and grow our customer base; develop new offerings and functionality for our platform and successfully optimize our existing products and services, including through integration of artificial intelligence (“AI”) into our platform; successfully expand our business domestically and internationally;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027","0001628280-25-049683"],"forms":{"10-Q":2},"first":"2025-09-03","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-a5464b4de1","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"protect against security incidents; successfully price and package our platform in a rapidly changing software industry, including due to advancements and increasing use of AI; and successfully identify and acquire or invest in businesses, products, offerings, or technologies that we believe could complement or expand our platform and successfully integrate such businesses, products, offerings, or technologies into our business.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027","0001628280-25-049683","0001628280-26-035209","0001628280-26-053348"],"forms":{"10-Q":4},"first":"2025-09-03","last":"2026-08-05","end":null},{"id":"1579878-cd7d741de3","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"If we fail to properly manage technical debt, our platform performance may suffer, we may face increased downtime, and our business, operating results, and financial condition could be harmed. Additionally, as 62 we integrate AI capabilities and expand our product offerings, technical complexity may increase, potentially exacerbating these challenges. To manage any future growth effectively, we must continue to improve and expand our infrastructure, including information technology and financial infrastructure, our operating and administrative systems and controls, and our ability to manage headcount, capital, and processes in an efficient manner.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027"],"forms":{"10-Q":1},"first":"2025-09-03","last":"2025-09-03","end":"2026-02-18"},{"id":"1579878-c3f74a8bea","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"the amount and timing of investments and expenditures related to the expansion of our business; the impacts on our cost structure, including, but not limited to, a decrease in our gross margins and operating margins associated with AI-related products and features; the impact of AI on the software creation industry and more generally within the software industry and on the demand for our platform, products, and services; general macroeconomic and political conditions, both domestically and in foreign markets where we operate, including, but not limited to, changes in U.S. federal spending, changes in tariffs or trade restrictions, global economic slowdowns, actual or perceived global banking and finance related issues, increased risk of inflation, potential uncertainty with respect to the federal debt ceiling and budget and potential government shutdowns related thereto, interest rate volatility, supply chain disruptions, labor shortages, and potential global recession;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027"],"forms":{"10-Q":1},"first":"2025-09-03","last":"2025-09-03","end":"2026-02-18"},{"id":"1579878-0fdb675646","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"We expect our Net Dollar Retention Rate to fluctuate or decline in the future as a result of a number of factors such as the growing level of our revenue base, the level of penetration within our customer base, expansion of products and features, our ability to retain our customers, and any changes to the pricing and packaging of our plans. We expect to continue to make significant expenditures related to the development and expansion of our business, including, but not limited to, expenditures related to acquiring new customers, expanding relationships with existing customers, expanding our global footprint, developing and expanding our platform, growing our sales and marketing investments, expanding our operations both domestically and internationally, and integrating AI, including generative AI, into our platform. We also expect to incur expenditures related to legal, tax, accounting, and other administrative and compliance expenses related to operating as a public company.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027","0001628280-25-049683"],"forms":{"10-Q":2},"first":"2025-09-03","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-fe74901187","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The changes to our pricing and packaging plans introduced in March 2025 have made, and any further changes to components of our billing models that we may introduce in the future may make, forecasting our operating results more difficult and result in comparisons to periods prior to the updates being less meaningful as some of the drivers underlying our business model will have changed. Further, as AI and its integration into software becomes more prevalent and its use cases become more sophisticated, including with respect to our products and the products of our competitors, there could be a decrease in the number of designers, developers, and other collaborators that use our platform if such individuals are able to significantly increase their efficiency through the use of AI capabilities alongside or instead of our platform. Such a decrease could reduce the number of seats that customers or potential customers subscribe to, which could lead to a loss of revenue, slower growth, and adversely impact our business, operating results, and financial condition. In response to any industry changes resulting from AI, we may need to make further changes to our billing model. Moreover, as the markets for our products and services mature, as we continue to add additional offerings to our platform, and as competitors introduce new products and services that compete with ours, we may be unable to attract new customers and retain existing customers at the same price or based on the same billing models as we have used historically. We may from time to time decide to make further changes to our billing models due to a variety of reasons, including, but not limited to, changes to the markets for our products and services, increased use of AI in the software industry generally, pricing pressures, and the introduction of new products and services by competitors. Changes to the components of our billing models, including the changes to our pricing and packaging plans introduced in March 2025 and any further changes that we may make in the future, may, among other things, result in customer dissatisfaction, lead to a loss of customers, and negatively impact our business, operating results, and financial condition.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027"],"forms":{"10-Q":1},"first":"2025-09-03","last":"2025-09-03","end":"2026-02-18"},{"id":"1579878-86c60074da","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"decreased spending on product design solutions and other products and services that we offer; the impact of AI on the markets for our products and services; and general macroeconomic and geopolitical conditions. 67 If we are not able to effectively introduce enhancements to our platform, including new offerings, features, and functionality, that achieve widespread market adoption, or keep pace with technological developments, our business, operating results, and financial condition could be adversely affected.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027"],"forms":{"10-Q":1},"first":"2025-09-03","last":"2025-09-03","end":"2026-02-18"},{"id":"1579878-6c913e8ae1","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"There can be no assurance that customer demand for such initiatives will exist or be sustained at the levels that we anticipate, or that any of these initiatives will gain sufficient traction or market adoption to generate sufficient revenue to offset any new expenses or liabilities associated with these new investments. It is also possible that products and services developed by others, including, but not limited to, new technologies integrating AI, or products and services developed by competitors that employ a consumption-based subscription model, will render our platform and offerings uncompetitive or obsolete. Further, our development efforts with respect to new technologies, offerings, features, and functionality could distract management from current operations, and would divert capital and other resources from our more established offerings. If we do not realize the expected benefits of our investments, our business, operating results, financial condition, and future prospects could be adversely affected. Competitive developments in AI and our inability to effectively respond to such developments could adversely affect our business, operating results, and financial condition. Developments in AI are already impacting the software industry significantly, and we expect this impact to be even greater in the future. AI has become more prevalent in the markets in which we operate and may result in significant changes in the demand for our platform, including, but not limited to, reducing the difficulty and cost for competitors to build and launch competitive products, altering how consumers and businesses interact with websites and apps and consume content in ways that may result in a reduction in the overall value of interface design, or by otherwise making aspects of our platform obsolete or decreasing the number of designers, developers, and other collaborators that utilize our platform. Any of these changes could, in turn, lead to a loss of revenue and adversely impact our business, operating results, and financial condition. 68 While we have made, and expect to continue to make, significant investments to integrate AI, including generative AI, into our platform, AI technologies are rapidly evolving and there can be no guarantee that our products will remain competitive as new AI technologies are developed, adopted, and integrated into software solutions. We expect that increased investment will be required in the future to continuously improve our use of AI technologies. As with many technological innovations, there are significant risks involved in developing, maintaining, and deploying AI. There can be no assurance that the integration of such technologies will enhance our products or services or be beneficial to our business, including, but not limited to, with respect to our efficiency or profitability. Similarly, we cannot guarantee that our investments in the development and integration of AI will be successful or provide an adequate return, including, without limitation, with respect to the amount of time, focus, and staffing directed towards these efforts, Further, our competitors may incorporate AI into their products more quickly or more successfully than we do, which would impair our ability to compete effectively. Decisions as to if and how to integrate various AI technologies are difficult and we may choose not to adopt certain technologies or take advantage of certain data sets available to us as a result of ethical, legal, regulatory, or reputational concerns, which could put us at a competitive disadvantage and harm our business, operating results, and financial condition. Our failure to successfully develop or commercialize our products or services involving AI technologies could impact the price of our Class A common stock and impair our ability to raise capital, expand our business, improve and diversify our product offerings, efficiently manage our operating expenses, and respond effectively to competitive developments. Moreover, the use of AI technologies and our investments to integrate AI into our platform may adversely impact our business, operating results, and financial condition. For example, in the short term, we expect that our AI investments and use of AI technologies, including as part of Figma Make and our Figma AI features, will negatively impact our gross margins and operating margins and, given the newness of and rapid development of these technologies, the impacts on our gross margins and operating margins, and on our business, operating results, financial condition, and future prospects over the longer term, are currently unknown. We face intense competition and could lose market share to our competitors, which would adversely affect our business, operating results, financial condition, and future prospects. The markets in which we participate are rapidly evolving and highly competitive, and if we do not compete effectively, our business, operating results, and financial condition could be adversely impacted. We face competition from a number of companies, including companies that cater to multiple stages of the design and development process, point tools that address individual parts of the process but can expand to cover more, and design-to-code and AI-driven companies and tools that compress or accelerate steps in the workflow or take a different approach to building digital experiences. We may also face competition from customized or internal solutions used by our customers or potential customers, particularly with AI’s potential to accelerate the ability to develop and deploy new software. Moreover, we expect to continue to face intense competition from current competitors, as well as from new entrants into the market, including as a result of strategic acquisitions and partnerships, increased use of AI, or evolving user and customer requirements and industry standards. If we are unable to anticipate or react to these challenges, our competitive position could weaken, and we may experience a decline in revenue, reduced revenue growth, or a loss of market share, which, individually or collectively, could adversely affect our business, operating results, and financial condition. 69 Our ability to compete effectively depends upon numerous factors, many of which are beyond our control, including, but not limited to:","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027"],"forms":{"10-Q":1},"first":"2025-09-03","last":"2025-09-03","end":"2026-02-18"},{"id":"1579878-ca3d67ee79","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"the extent of market adoption of our platform, and the timing of such market adoption, which may be influenced by developments and enhancements we introduce to our platform relative to the developments and enhancements made to competitive products available in the market; the impact of AI on the markets for our products and services, including, but not limited to, our ability to successfully incorporate AI technologies into our platform and successfully adapt our billing models to the increased use of AI in the software industry generally; the budgeting cycles, seasonal buying patterns, and purchasing practices of our customers, including, but not limited to, any slowdown in technology spending due to U.S. and global macroeconomic conditions;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027","0001628280-25-049683"],"forms":{"10-Q":2},"first":"2025-09-03","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-f6141acfe7","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["1.2","1.1","2.1","3.1","6.3","7.3","2.2"],"primary":"1.2","status":"hypothetical","harm":["Human or fundamental rights","Economic/Property","Reputational"],"layers":["capability","human_interaction"],"whose":["own"],"relation":["within_purpose","misuse"],"misuse_by":["third_party"],"subjects":[{"name":"end users","type":"Group of persons"},{"name":"customers","type":"Organization"},{"name":"third-party","type":"Other"}],"text":"If the markets for our platform do not grow to the extent that we anticipate or our platform does not achieve widespread adoption within the markets in which we operate, our business, operating results, financial condition, and future prospects could be adversely affected. Our use of AI in our products and services may result in reputational harm, legal liability, competitive risks, and regulatory concerns that could adversely affect our business, operating results, and financial condition. We have made, and expect to continue to make, significant investments to integrate AI, including generative AI, and machine learning technology into our platform, including as part of our Figma Make product and Figma AI features. Many AI technologies are relatively new and present ethical, legal, regulatory, and reputational challenges. The use of datasets to develop AI models, the content generated by AI systems, or the application of AI systems may be found to be insufficient, offensive, biased, or harmful, or may violate current or future laws and regulations. Further, we generally rely on third-party models for the AI features on our platform. Our ability to continue to use such technologies at scale may be dependent on access to specific third-party software and infrastructure. We cannot control the availability or pricing of such third-party AI technologies, especially in a highly competitive environment, and we may be unable to negotiate favorable economic terms with the applicable providers. If any such third-party AI technologies become incompatible with our platform or unavailable for use, or if the providers of such models unfavorably change the terms on which their AI technologies are offered or terminate their relationship with us, our platform may become less appealing to our customers and our business, operating results, and financial condition could be adversely impacted. Moreover, the integration of third-party AI models with our platform relies on certain safeguards implemented by the third-party developers of the underlying AI models, including those related to the accuracy, bias, and other variables of the training data used for such models, and these safeguards may be insufficient. If the models underlying our AI technologies are incorrectly designed or implemented; trained or reliant on incomplete, inadequate, inaccurate, biased or otherwise poor quality data, or on data to which we do not have sufficient rights or in relation to which we and/or the providers of such data have not implemented sufficient legal compliance measures; used without sufficient oversight and governance to ensure their responsible use; and/or adversely impacted by unforeseen defects, technical challenges, cybersecurity threats, or material performance issues, the performance of our products, services, and business, as well as our reputation and the reputations of our customers, could suffer, and we could incur liability resulting from the violation of laws, breach of contract claims, or civil claims. In addition, the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information. Such leakage or unauthorized exposure of data related to the use of AI applications could result in legal claims or liability or otherwise adversely affect our reputation and operating results. Moreover, our generative AI technologies could generate output that infringes on third-party intellectual property rights, and we could be subject to claims or lawsuits, including, but not limited to, for infringement of third-party intellectual property rights as a result of the output of such generative AI technologies. While some providers of AI technologies offer to indemnify their end users for any copyright or other intellectual property infringement claims arising from the output of their AI technologies, such indemnification may be inadequate or we may not be successful in adequately recovering our losses in connection with such claims. Our generative AI technologies could also generate content that is inaccurate, misleading, or inappropriate, which could harm our reputation, expose us to liability, or cause customers to lose confidence in our platform. 72 The regulatory framework for AI technologies is rapidly evolving as many U.S. federal, state, and foreign government bodies and agencies have introduced or are currently considering additional laws and regulations. Additionally, existing laws and regulations may be interpreted in ways that would affect the operation of our AI technologies, or could be rescinded or amended as new administrations take differing approaches to evolving AI technologies. As a result, implementation standards and enforcement practices are likely to remain uncertain for the foreseeable future, and we cannot yet completely determine the impact future laws, regulations, standards, or market perception of their requirements may have on our business and may not always be able to anticipate how to respond to these laws or regulations. Already, certain existing legal regimes, for example, relating to data privacy, regulate certain aspects of AI technologies, and new laws regulating AI technologies either entered into force in the United States and the European Economic Area (the “EEA”) in 2024 or are expected to enter into force in 2025. U.S. legislation related to AI technologies has been introduced at the federal level and has passed at the state level. For example, California enacted seventeen new laws in 2024 that regulate use of AI technologies and provide consumers with additional protections around companies’ use of AI technologies, such as requiring companies to disclose certain uses of generative AI. Other states have also passed AI-focused legislation, such as Colorado’s Artificial Intelligence Act, which will require developers and deployers of “high-risk” AI systems to implement certain safeguards against algorithmic discrimination, and Utah’s Artificial Intelligence Policy Act, which establishes disclosure requirements and accountability measures for the use of generative AI in certain consumer interactions. Such additional regulations may impact our ability to develop, use, and commercialize AI technologies in the future. In Europe, the EU Artificial Intelligence Act (the “EU AI Act”), which entered into force in August 2024, establishes a comprehensive, risk-based governance framework for AI in the EU market. The majority of the substantive requirements of the EU AI Act are not enforceable yet and will apply from August 2, 2026. The EU AI Act will have a material impact on the way AI is regulated in the EU, as it applies to companies that develop, use, and/or provide AI in the EU and, depending on the AI use case, includes requirements around transparency, conformity assessments and monitoring, risk assessments, human oversight, security, accuracy, general purpose AI, and foundation models, and imposes fines for breaches of up to 7% of worldwide annual revenues. The EU AI Act, together with developing guidance and/or decisions in this area, may affect our use of AI technologies and our ability to provide, improve, or commercialize our services, require additional compliance measures and changes to our operations and processes, result in increased compliance costs and potential increases in civil claims against us, and could adversely affect our business, operating results, and financial condition. It is possible that further new laws and regulations will be adopted in the United States and in other non-U.S. jurisdictions, or that existing laws and regulations, including competition and antitrust laws, may be interpreted in ways that would limit our ability to use AI technologies for our business, or require us to change the way we use AI technologies in a manner that negatively affects the performance of our offerings and the way in which we use AI technologies. We may need to expend resources to adjust our products or services in certain jurisdictions if the laws, regulations, or decisions are not consistent across jurisdictions. Further, the cost to comply with such laws, regulations, or decisions and/or guidance interpreting existing laws, could be significant and would increase our operating expenses (such as by imposing additional reporting obligations regarding our use of AI technologies). Such an increase in operating expenses, as well as any actual or perceived failure to comply with such laws and regulations, could adversely affect our business, operating results, and financial condition. Moreover, any changes to the above discussed existing legal regimes with respect to data privacy and AI technologies within the United States and abroad could require us to expend significant resources to modify our products, services, or operations to ensure compliance or remain competitive. 73 Existing and future acquisitions, strategic investments, partnerships, or alliances could be difficult to identify and integrate, divert the attention of key management personnel, disrupt our business, dilute stockholder value, and adversely affect our business, operating results, financial condition, and future prospects. As part of our business strategy, we have in the past and expect to continue to make investments in or acquire complementary companies, services, products, technologies, or talent.","ev":{"mit:1.2":"content generated by AI systems, or the application of AI systems may be found to be insufficient, offensive, biased, or harmful","mit:1.1":"trained or reliant on incomplete, inadequate, inaccurate, biased or otherwise poor quality data","mit:2.1":"the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information","mit:3.1":"Our generative AI technologies could also generate content that is inaccurate, misleading, or inappropriate","mit:6.3":"our generative AI technologies could generate output that infringes on third-party intellectual property rights","mit:7.3":"If the models underlying our AI technologies are incorrectly designed or implemented","mit:2.2":"adversely impacted by unforeseen defects, technical challenges, cybersecurity threats, or material performance issues","harm:Human or fundamental rights":"the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information","harm:Economic/Property":"we could be subject to claims or lawsuits, including, but not limited to, for infringement of third-party intellectual property rights as a result of the output of such generative AI technologies","harm:Reputational":"which could harm our reputation, expose us to liability, or cause customers to lose confidence in our platform","layer:capability":"Our generative AI technologies could also generate content that is inaccurate, misleading, or inappropriate","layer:human_interaction":"the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information","whose:own":"we generally rely on third-party models for the AI features on our platform","relation:within_purpose":"Our generative AI technologies could also generate content that is inaccurate, misleading, or inappropriate","relation:misuse":"the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information","misuse_by:third_party":"the integration of third-party AI models with our platform relies on certain safeguards implemented by the third-party developers of the underlying AI models"},"rev":null,"harm_quote":"content generated by AI systems, or the application of AI systems may be found to be insufficient, offensive, biased, or harmful","status_quote":null,"reports":["0001579878-25-000027"],"forms":{"10-Q":1},"first":"2025-09-03","last":"2025-09-03","end":"2026-02-18"},{"id":"1579878-d4a1fc78cd","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["2.2","2.1"],"primary":"2.2","status":"hypothetical","harm":["Economic/Property","Human or fundamental rights","Reputational"],"layers":["human_interaction"],"whose":["own"],"relation":["misuse"],"misuse_by":["third_party"],"subjects":[{"name":"customers","type":"Organization"}],"text":"Any security breach of our platform, our operational systems, physical facilities, or the systems of our third-party processors, or the perception that a breach has occurred, or other adverse impact to the availability, integrity or confidentiality of such platform and systems, could result in litigation (including class actions), indemnity obligations, regulatory enforcement actions, investigations, compulsory audits, fines, penalties, mitigation and remediation costs, disputes, reputational harm, diversion of management’s attention, and other liabilities and damage to our business. We face evolving cybersecurity risks that threaten the confidentiality, integrity, and availability of our or our customers’ confidential or personal data and our and our third-party service providers’ information technology systems, which could result from human error, system misconfiguration, or from cyber-attacks, including distributed-denial-of-service attacks, reverse-engineering of AI algorithms, web scraping, ransomware attacks, business email compromises, computer malware, viruses, and social engineering (including phishing), malicious code embedded in open-source software, or misconfigurations, “bugs” or other vulnerabilities in commercial software that is integrated into our and our third-party service providers’ information technology systems, products or services, which are prevalent in our industry. These threats may come from a variety of sources including nation-state sponsored espionage and hacking activities, corporate espionage, organized crime, sophisticated organizations, hacking groups and individuals, and insider threats.","ev":{"mit:2.2":"reverse-engineering of AI algorithms","mit:2.1":"We face evolving cybersecurity risks that threaten the confidentiality, integrity, and availability of our or our customers","harm:Economic/Property":"litigation (including class actions), indemnity obligations, regulatory enforcement actions, investigations, compulsory audits, fines, penalties, mitigation and remediation costs","harm:Human or fundamental rights":"We face evolving cybersecurity risks that threaten the confidentiality, integrity, and availability of our or our customers","harm:Reputational":"reputational harm","layer:human_interaction":"cyber-attacks, including distributed-denial-of-service attacks, reverse-engineering of AI algorithms, web scraping","whose:own":"Any security breach of our platform","relation:misuse":"cyber-attacks, including distributed-denial-of-service attacks, reverse-engineering of AI algorithms, web scraping","misuse_by:third_party":"These threats may come from a variety of sources including nation-state sponsored espionage and hacking activities, corporate espionage, organized crime"},"rev":null,"harm_quote":"reverse-engineering of AI algorithms","status_quote":null,"reports":["0001579878-25-000027","0001628280-25-049683"],"forms":{"10-Q":2},"first":"2025-09-03","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-394388df02","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["4.2","2.1"],"primary":"4.2","status":"elsewhere","harm":["Economic/Property","Human or fundamental rights"],"layers":["human_interaction"],"whose":["others"],"relation":["misuse"],"misuse_by":["third_party"],"subjects":[],"text":"Further, state-supported and geopolitical-related cyberattacks may rise in connection with regional geopolitical conflicts which have increased the risk of cyberattacks on various types of infrastructure and 77 operations. Bad actors are also beginning to utilize AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges. As a result, we may be unable to detect, investigate, remediate, or recover from future attacks or incidents, or to avoid a material adverse impact to our information technology systems, confidential or personal data, or business.","ev":{"status":"Bad actors are also beginning to utilize AI-based tools","mit:4.2":"Bad actors are also beginning to utilize AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","mit:2.1":"we may be unable to detect, investigate, remediate, or recover from future attacks or incidents, or to avoid a material adverse impact to our information technology systems, confidential or personal data, or business","harm:Economic/Property":"we may be unable to detect, investigate, remediate, or recover from future attacks or incidents, or to avoid a material adverse impact to our information technology systems, confidential or personal data, or business","harm:Human or fundamental rights":"we may be unable to detect, investigate, remediate, or recover from future attacks or incidents, or to avoid a material adverse impact to our information technology systems, confidential or personal data, or business","layer:human_interaction":"Bad actors are also beginning to utilize AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","whose:others":"Bad actors are also beginning to utilize AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","relation:misuse":"Bad actors are also beginning to utilize AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","misuse_by:third_party":"Bad actors are also beginning to utilize AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence"},"rev":null,"harm_quote":"Bad actors are also beginning to utilize AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","status_quote":"Bad actors are also beginning to utilize AI-based tools","reports":["0001579878-25-000027"],"forms":{"10-Q":1},"first":"2025-09-03","last":"2025-09-03","end":"2026-02-18"},{"id":"1579878-e35c475c9f","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"We may also encounter service interruptions, outages, or disruptions due to issues interfacing with our customers’ information technology systems, including, but not limited to, stack misconfigurations or improper environment scaling, defective updates or upgrades, our customers’ inability to access the internet, the failure of our network or software systems, security breaches, variability in user traffic for our platform or due to cybersecurity attacks on our or our customers’ information technology systems. For example, if our cloud hosting provider or the hosting provider of any of our third-party technology partners, including AI partners, were to experience interruptions, delays, outages, or other service interruptions, including as a result of customer demand, that may impact our ability to provide service to our customers. We may be required to issue credits or refunds or otherwise be liable to our customers for damages they may incur resulting from certain of these events.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027"],"forms":{"10-Q":1},"first":"2025-09-03","last":"2025-09-03","end":"2026-02-18"},{"id":"1579878-9680b5f5be","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"tariffs, export and import restrictions, restrictions on foreign investments, sanctions, and other trade barriers or protectionist measures; 83 exposure to numerous, increasing, stringent, and potentially inconsistent laws and regulations relating to, among other things, AI, privacy, data protection, online safety, moderation, and information security; costs of, and challenges with, localizing our platform including, but not limited to, data localization and other data privacy requirements;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027"],"forms":{"10-Q":1},"first":"2025-09-03","last":"2025-09-03","end":"2026-02-18"},{"id":"1579878-1ec74b2c17","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"There can be no assurance that we will be able to hire sufficient support personnel as and when needed, particularly if our sales exceed our internal forecasts. Additionally, our customer support team uses third-party AI tools to assist them with responding to and resolving customer inquiries. To the extent that we are unsuccessful in hiring, training, and retaining adequate support resources or utilizing AI tools for customer support, our ability to provide high-quality and timely support to our customers will be negatively impacted, and our customers’ satisfaction and their usage of our infrastructure could be adversely affected. Because we recognize subscription revenue over the subscription term, downturns or upturns in new sales and renewals are not immediately reflected in full in our operating results.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027","0001628280-25-049683"],"forms":{"10-Q":2},"first":"2025-09-03","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-fc04cf4762","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Our revenue recognition and operating results may be difficult to predict because of the length and unpredictability of the sales cycle for our platform, particularly as we increasingly sell to larger organizations, governmental organizations, regulated entities, and organizations outside of the United States or to the technology industry that may have different procurement requirements than our historical customers. For example, we have observed a lengthening of the sales cycle recently for some 85 prospective customers that we attribute to increased sensitivity to information technology security concerns, particularly with respect to products that include AI features or otherwise incorporate AI technologies, such as our platform. In addition, larger customers frequently have rigorous procurement processes and require considerable time to evaluate, test, and qualify our platform prior to entering into or expanding a relationship with us.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027"],"forms":{"10-Q":1},"first":"2025-09-03","last":"2025-09-03","end":"2026-02-18"},{"id":"1579878-365c4f1e67","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"More generally, the technology industry, and the software industry more specifically, is also subject to substantial and continuous competition for engineers with high levels of experience in designing, developing, and managing software and related services. This is especially true in the market for AI talent, which remains extremely competitive. We have, from time to time, experienced, and we expect to continue to experience, difficulty in hiring and retaining highly skilled employees with 87 appropriate qualifications at a suitable cost, and this risk may be exacerbated by factors related to, among other things, increased recruiting efforts by other companies.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027"],"forms":{"10-Q":1},"first":"2025-09-03","last":"2025-09-03","end":"2026-02-18"},{"id":"1579878-12d15c35c1","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Moreover, we may need to expend additional resources to defend our intellectual property rights in foreign countries, and our inability to do so could impair our business or adversely affect our international expansion. Furthermore, the application of intellectual property law to AI technologies is a new and emerging practice, and there is uncertainty and ongoing litigation in different jurisdictions as to the degree and extent of protection warranted for AI and machine learning systems and relevant system input and outputs. The law is also uncertain across jurisdictions regarding the copyright ownership of content that is produced in whole or in part by generative AI tools. As a result, our use of AI tools in our product development and engineering processes may make it difficult to assert ownership rights over our technology. If we fail to obtain protection for the intellectual property rights concerning our AI technologies, or later have our intellectual property rights invalidated or otherwise diminished, our competitors may be able to take advantage of our research and development efforts to develop competing products which could adversely affect our business, reputation, and financial condition. In addition, given the long history of development of AI technologies, other parties may have, or in the future may obtain, patents or other proprietary rights that could prevent, limit, or interfere with our ability to make, use, or sell our own AI technologies. Third parties have claimed and may claim that our platform infringes, misappropriates, or otherwise violates their intellectual property rights and such claims could be time-consuming or costly to defend or settle, result in the loss of significant rights, or harm our relationships with our customers or reputation in the industry.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027","0001628280-25-049683"],"forms":{"10-Q":2},"first":"2025-09-03","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-1eb28ee30e","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["6.3","7.3","2.2"],"primary":"6.3","status":"elsewhere","harm":["Economic/Property"],"layers":["capability","human_interaction"],"whose":["own","general"],"relation":["within_purpose","misuse"],"misuse_by":["third_party"],"subjects":[],"text":"A loss of key personnel or their work product could hamper or prevent our ability to develop, market, and support potential products or enhancements, which could severely harm our business. Further, we may use AI technologies, including tools provided by third parties, to develop or assist in the development of our own software code. While use of such tools makes our development process more efficient, AI technologies have sometimes generated content that is “substantially similar” to proprietary or open source software code on which the AI tool was trained. If the AI technologies we use generate code that is too similar to other proprietary code, or to software processes that are protected by patents, we could be subject to intellectual property infringement claims. We may also not be able to anticipate and detect security vulnerabilities in such AI-generated software code, including those that could be induced by a maliciously trained AI model. If our tools generate code that is too similar to open source code, we risk losing protection of our own proprietary code that is commingled with such code. Finally, to the extent we use third-party AI technologies to develop software code, the terms of use of these tools may state that the third-party provider retains rights in the generated code. Any intellectual property claims, whether with or without merit, could be very time-consuming, could be expensive to settle or litigate, and could divert our management’s attention and other resources, even if such claims do not result in litigation or are resolved in our favor.","ev":{"status":"AI technologies have sometimes generated content that is “substantially similar” to proprietary or open source software code","mit:6.3":"If the AI technologies we use generate code that is too similar to other proprietary code, or to software processes that are protected by patents, we could be subject to intellectual property infringement claims.","mit:7.3":"We may also not be able to anticipate and detect security vulnerabilities in such AI-generated software code, including those that could be induced by a maliciously trained AI model.","mit:2.2":"We may also not be able to anticipate and detect security vulnerabilities in such AI-generated software code, including those that could be induced by a maliciously trained AI model.","harm:Economic/Property":"Any intellectual property claims, whether with or without merit, could be very time-consuming, could be expensive to settle or litigate","layer:capability":"We may also not be able to anticipate and detect security vulnerabilities in such AI-generated software code, including those that could be induced by a maliciously trained AI model.","layer:human_interaction":"we may use AI technologies, including tools provided by third parties, to develop or assist in the development of our own software code","whose:own":"we may use AI technologies, including tools provided by third parties, to develop or assist in the development of our own software code","whose:general":"Finally, to the extent we use third-party AI technologies to develop software code, the terms of use of these tools may state that the third-party provider retains rights in the generated code.","relation:within_purpose":"we may use AI technologies, including tools provided by third parties, to develop or assist in the development of our own software code","relation:misuse":"including those that could be induced by a maliciously trained AI model","misuse_by:third_party":"including those that could be induced by a maliciously trained AI model"},"rev":null,"harm_quote":"If the AI technologies we use generate code that is too similar to other proprietary code, or to software processes that are protected by patents, we could be subject to intellectual property infringement claims.","status_quote":"AI technologies have sometimes generated content that is “substantially similar” to proprietary or open source software code","reports":["0001579878-25-000027","0001628280-25-049683"],"forms":{"10-Q":2},"first":"2025-09-03","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-8e89847950","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Any impairment of the technologies of or our relationship with these third parties could harm our business, operating results, and financial condition. 95 Risks Related to Legal and Regulatory Matters Our business is subject to complex and evolving U.S. and foreign laws, regulations, and industry standards, many of which are subject to change and uncertain interpretations, which uncertainty could harm our business, operating results, and financial condition. We are subject to many U.S. and foreign federal, state, and local laws, regulations, and industry standards that involve matters central to our business, including laws and regulations that involve data privacy, data security, intellectual property, including copyright and patent laws, AI technologies, antitrust and competition, online safety and moderation, employment, labor, immigration, consumer protection, public health, workplace safety, and taxation. These laws and regulations are constantly evolving and may be interpreted, applied, created, or amended, in a manner that could harm our business.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027"],"forms":{"10-Q":1},"first":"2025-09-03","last":"2025-09-03","end":"2026-02-18"},{"id":"1579878-5954c6cb4e","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"On November 16, 2022, the EU Digital Services Act (“DSA”), came into force in the European Union. The DSA governs, among other things, our potential liability for illegal services or content on our platform, and requires enhanced transparency measures, including in relation to any recommendation systems (including the main parameters used by such systems and any available options for recipients to modify or influence them). The DSA may increase our compliance costs, require changes to our user interface, processes, operations, and business practices which may adversely affect our ability to attract, retain and provide our services to users, and may otherwise adversely affect our business, operating results, and financial condition.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000027","0001628280-25-049683"],"forms":{"10-Q":2},"first":"2025-09-03","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-847732e149","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["4.2","6.2","7.3"],"primary":"4.2","status":"hypothetical","harm":["Economic/Property","Physical (injury)","Physical (death)"],"layers":["human_interaction","systemic","capability"],"whose":["general"],"relation":["misuse","within_purpose"],"misuse_by":["third_party"],"subjects":[],"text":"Further, acts of war, armed conflict, terrorism, and other geopolitical unrest, such as the conflicts in the Middle East, and Ukraine and tensions between China and Taiwan, could cause disruptions in our business, the businesses of our partners or customers, or the economy as a whole. Moreover, the risks associated with AI technology are still unknown and advances in AI could pose risks, including, but not limited to, cyberattacks, terrorism, disruption to labor markets, criminal misuse, autonomous warfare, and catastrophic accidents. In the event of a natural disaster, including, but not limited to, a major earthquake, blizzard, or hurricane, or a catastrophic event such as a fire, power loss, cyberattack, or telecommunications failure, we may be unable to continue our operations and may endure system interruptions, reputational harm, delays in development of our platform, lengthy interruptions in service, breaches of data security, and loss of critical data, all of which could have an adverse effect on our future operating results.","ev":{"mit:4.2":"advances in AI could pose risks, including, but not limited to, cyberattacks, terrorism, disruption to labor markets, criminal misuse, autonomous warfare, and catastrophic accidents","mit:6.2":"disruption to labor markets","mit:7.3":"catastrophic accidents","harm:Economic/Property":"we may be unable to continue our operations and may endure system interruptions, reputational harm, delays in development of our platform, lengthy interruptions in service","harm:Physical (injury)":"autonomous warfare, and catastrophic accidents","harm:Physical (death)":"autonomous warfare, and catastrophic accidents","layer:human_interaction":"criminal misuse","layer:systemic":"disruption to labor markets","layer:capability":"catastrophic accidents","whose:general":"advances in AI could pose risks, including, but not limited to, cyberattacks, terrorism, disruption to labor markets, criminal misuse, autonomous warfare, and catastrophic accidents","relation:misuse":"criminal misuse","relation:within_purpose":"catastrophic accidents","misuse_by:third_party":"criminal misuse"},"rev":null,"harm_quote":"advances in AI could pose risks, including, but not limited to, cyberattacks, terrorism, disruption to labor markets, criminal misuse, autonomous warfare, and catastrophic accidents","status_quote":null,"reports":["0001579878-25-000027","0001628280-25-049683"],"forms":{"10-Q":2},"first":"2025-09-03","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-6d25c045de","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"If we fail to properly manage technical debt, our platform performance may suffer, we may face increased downtime, and our business, operating results, and financial condition could be harmed. Additionally, as 66 we further integrate AI capabilities and expand our product offerings, technical complexity may increase, potentially exacerbating these challenges. To manage any future growth effectively, we must continue to improve and expand our infrastructure, including information technology and financial infrastructure, our operating and administrative systems and controls, and our ability to manage headcount, capital, and processes in an efficient manner.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-25-049683"],"forms":{"10-Q":1},"first":"2025-11-05","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-e953bc2016","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"the amount and timing of investments and expenditures related to the expansion of our business; the impacts on our cost structure, including, but not limited to, any decrease in our gross margins and operating margins associated with AI-related products and features; the impact of AI on the software creation industry and more generally within the software industry and on the demand for our platform, products, and services; general macroeconomic and political conditions, both domestically and in foreign markets where we operate, including, but not limited to, changes in U.S. federal spending, changes in tariffs or trade restrictions, global economic slowdowns, actual or perceived global banking and finance related issues, increased risk of inflation, uncertainty with respect to the U.S. federal debt ceiling and budget and the ongoing U.S. federal government shutdown related thereto, interest rate volatility, supply chain disruptions, labor shortages, and potential global recession;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-25-049683"],"forms":{"10-Q":1},"first":"2025-11-05","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-33c7fec56d","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The changes to our pricing and packaging plans introduced in March 2025 have made, and any further changes to components of our pricing, packaging, and billing models that we may introduce in the future, may make, forecasting our operating results more difficult and result in comparisons to periods prior to the updates being less meaningful as some of the drivers underlying our business model will have changed. Further, as AI and its integration into software becomes more prevalent and its use cases become more sophisticated, including with respect to our products and the products of our competitors, there could be a decrease in the number of designers, developers, and other collaborators that use our platform if such individuals are able to significantly increase their efficiency through the use of AI capabilities alongside or instead of our platform. Such a decrease could reduce the number of seats that customers or potential customers subscribe to, which could lead to a loss of revenue, slower growth, and adversely impact our business, operating results, and financial condition. In response to any industry changes resulting from AI, we may need to make further changes to our billing models. Moreover, as the markets for our products and services mature, as we continue to add additional offerings to our platform, and as competitors introduce new products and services that compete with ours, we may be unable to attract new customers and retain existing customers at the same price or based on the same billing models as we have used historically. We may from time to time decide to make further changes to our billing models due to a variety of reasons, including, but not limited to, changes to the markets for our products and services, increased use of AI in the software industry generally, increased implementation and use of AI features in our products, pricing pressures, and the introduction of new products and services by competitors. Changes to the components of our billing models, including the changes to our pricing and packaging plans introduced in March 2025 and any further changes that we make in the future, may, among other things, result in customer dissatisfaction, lead to a loss of customers, and negatively impact our business, operating results, and financial condition.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-25-049683"],"forms":{"10-Q":1},"first":"2025-11-05","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-4ae681d6d7","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"decreased spending on product design solutions and other products and services that we offer; the impact of AI on the markets for our products and services; and general macroeconomic and geopolitical conditions. 71 If we are not able to effectively introduce enhancements to our platform, including new offerings, features, and functionality, that achieve widespread market adoption, or keep pace with technological developments, our business, operating results, and financial condition could be adversely affected.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-25-049683"],"forms":{"10-Q":1},"first":"2025-11-05","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-1d91106fc7","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"There can be no assurance that customer demand for such initiatives will exist or be sustained at the levels that we anticipate, or that any of these initiatives will gain sufficient traction or market adoption to generate sufficient revenue to offset any new expenses or liabilities associated with these new investments. It is also possible that products and services developed by others, including, but not limited to, new technologies integrating AI, or products and services developed by competitors that employ a consumption-based subscription model, will render our platform and offerings uncompetitive or obsolete. Further, our development efforts with respect to new technologies, offerings, features, and functionality could distract management from current operations, and would divert capital and other resources from our more established offerings. If we do not realize the expected benefits of our investments, our business, operating results, financial condition, and future prospects could be adversely affected. Competitive developments in AI and our inability to effectively respond to such developments could adversely affect our business, operating results, and financial condition. Developments in AI are already impacting the software industry significantly, and we expect this impact to be even greater in the future. AI has become more prevalent in the markets in which we operate and may result in significant changes in the demand for our platform, including, but not limited to, reducing the difficulty and cost for competitors to build and launch competitive products, altering how consumers and businesses interact with websites and apps and consume content in ways that may result in a reduction in the overall value of interface design, or by otherwise making aspects of our platform obsolete or decreasing the number of designers, developers, and other collaborators that utilize our platform. Any of these changes could, in turn, lead to a loss of revenue and adversely impact our business, operating results, and financial condition. 72 While we have made, and expect to continue to make, significant investments to integrate AI, including generative AI, into our platform, AI technologies are rapidly evolving and there can be no guarantee that our products will remain competitive as new AI technologies are developed, adopted, and integrated into software solutions. We expect that increased investment will be required in the future to continuously improve our use of AI technologies. As with many technological innovations, there are significant risks involved in developing, maintaining, and deploying AI. There can be no assurance that the integration of such technologies will enhance our products or services or be beneficial to our business, including, but not limited to, with respect to our efficiency or profitability. Similarly, we cannot guarantee that our investments in the development and integration of AI will be successful or provide an adequate return, including, without limitation, with respect to the amount of time, focus, and staffing directed towards these efforts, Further, our competitors may incorporate AI into their products more quickly or more successfully than we do, which would impair our ability to compete effectively. Decisions as to if and how to integrate various AI technologies are difficult and we may choose not to adopt certain technologies or take advantage of certain data sets available to us as a result of ethical, legal, regulatory, or reputational concerns, which could put us at a competitive disadvantage and harm our business, operating results, and financial condition. Our failure to successfully develop or commercialize our products or services involving AI technologies could impact the price of our Class A common stock and impair our ability to raise capital, expand our business, improve and diversify our product offerings, efficiently manage our operating expenses, and respond effectively to competitive developments. Moreover, the use of AI technologies and our investments to integrate AI into our platform may adversely impact our business, operating results, and financial condition. For example, in the short term, we expect that our AI investments and use of AI technologies, including as part of Figma Make and our Figma AI features, will negatively impact our gross margins and operating margins and, given the newness of and rapid development of these technologies, the impacts on our gross margins and operating margins, and on our business, operating results, financial condition, and future prospects over the longer term, are currently unknown. We face intense competition and could lose market share to our competitors, which would adversely affect our business, operating results, financial condition, and future prospects. The markets in which we participate are rapidly evolving and highly competitive, and if we do not compete effectively, our business, operating results, and financial condition could be adversely impacted. We face competition from a number of companies, including companies that cater to multiple stages of the design and development process, point tools that address individual parts of the process but can expand to cover more, and design-to-code and AI-driven companies and tools that compress or accelerate steps in the workflow or take a different approach to building digital experiences. We may also face competition from customized or internal solutions used by our customers or potential customers, particularly with AI’s potential to accelerate the ability to develop and deploy new software. Moreover, we expect to continue to face intense competition from current competitors, as well as from new entrants into the market, including as a result of strategic acquisitions and partnerships, increased use of AI, or evolving user and customer requirements and industry standards. If we are unable to anticipate or react to these challenges, our competitive position could weaken, and we may experience a decline in revenue, reduced revenue growth, or a loss of market share, which, individually or collectively, could adversely affect our business, operating results, and financial condition. 73 Our ability to compete effectively depends upon numerous factors, many of which are beyond our control, including, but not limited to:","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-25-049683"],"forms":{"10-Q":1},"first":"2025-11-05","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-eef665ad1f","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["1.2","1.1","7.3","2.1","6.3","3.1"],"primary":"1.2","status":"hypothetical","harm":["Human or fundamental rights","Economic/Property","Reputational"],"layers":["capability"],"whose":["own"],"relation":["within_purpose"],"misuse_by":[],"subjects":[{"name":"end users","type":"Group of persons"},{"name":"our customers","type":"Organization"}],"text":"If the markets for our platform do not grow to the extent that we anticipate or our platform does not achieve widespread adoption within the markets in which we operate, our business, operating results, financial condition, and future prospects could be adversely affected. Our use of AI in our products and services may result in reputational harm, legal liability, competitive risks, and regulatory concerns that could adversely affect our business, operating results, and financial condition. We have made, and expect to continue to make, significant investments to integrate AI, including generative AI, and machine learning technology into our platform, including as part of our Figma Make product and Figma AI features. Many AI technologies are relatively new and present ethical, legal, regulatory, and reputational challenges. The use of datasets to develop AI models, the content generated by AI systems, or the application of AI systems may be found to be insufficient, offensive, biased, or harmful, or may violate current or future laws and regulations. Further, we generally rely on third-party models for the AI features on our platform. Our ability to continue to use such technologies at scale may be dependent on access to specific third-party software and infrastructure. We cannot control the availability or pricing of such third-party AI technologies, especially in a highly competitive environment, and we may be unable to negotiate favorable economic terms with the applicable providers. If any such third-party AI technologies become incompatible with our platform or unavailable for use, or if the providers of such models unfavorably change the terms on which their AI technologies are offered or terminate their relationship with us, our platform may become less appealing to our customers and our business, operating results, and financial condition could be adversely impacted. Moreover, the integration of third-party AI models with our platform relies on certain safeguards implemented by the third-party developers of the underlying AI models, including those related to the accuracy, bias, and other variables of the training data used for such models, and these safeguards may be insufficient. If the models underlying our AI technologies are incorrectly designed or implemented; trained or reliant on incomplete, inadequate, inaccurate, biased or otherwise poor quality data, or on data to which we do not have sufficient rights or in relation to which we and/or the providers of such data have not implemented sufficient legal compliance measures; used without sufficient oversight and governance to ensure their responsible use; and/or adversely impacted by unforeseen defects, technical challenges, cybersecurity threats, or material performance issues, the performance of our products, services, and business, as well as our reputation and the reputations of our customers, could suffer, and we could incur liability resulting from the violation of laws, breach of contract claims, or civil claims. In addition, the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information. Such leakage or unauthorized exposure of data related to the use of AI applications could result in legal claims or liability or otherwise adversely affect our reputation and operating results. Moreover, our generative AI technologies could generate output that infringes on third-party intellectual property rights, and we could be subject to claims or lawsuits, including, but not limited to, for infringement of third-party intellectual property rights as a result of the output of such generative AI technologies. While some providers of AI technologies offer to indemnify their end users for any copyright or other intellectual property infringement claims arising from the output of their AI technologies, such indemnification may be inadequate or we may not be successful in adequately recovering our losses in connection with such claims. Our generative AI technologies could also generate content that is inaccurate, misleading, or inappropriate, which could harm our reputation, expose us to liability, or cause customers to lose confidence in our platform. 76 The regulatory framework for AI technologies is rapidly evolving as many U.S. federal, state, and foreign government bodies and agencies have introduced or are currently considering additional laws and regulations. Additionally, existing laws and regulations may be interpreted in ways that would affect the operation of our AI technologies, or could be rescinded or amended as new administrations take differing approaches to evolving AI technologies. As a result, implementation standards and enforcement practices are likely to remain uncertain for the foreseeable future, and we cannot yet completely determine the impact future laws, regulations, standards, or market perception of their requirements may have on our business and may not always be able to anticipate how to respond to these laws or regulations. Already, certain existing legal regimes, for example, relating to data privacy, regulate certain aspects of AI technologies, and new laws regulating AI technologies have recently entered into force in the United States and the European Economic Area (the “EEA”). U.S. legislation related to AI technologies has been introduced at the federal level and has passed at the state level. For example, California enacted seventeen new laws in 2024 that regulate use of AI technologies and provide consumers with additional protections around companies’ use of AI technologies, such as requiring companies to disclose certain uses of generative AI. Other states have also passed AI-focused legislation, such as Colorado’s Artificial Intelligence Act, which will require developers and deployers of “high-risk” AI systems to implement certain safeguards against algorithmic discrimination, and Utah’s Artificial Intelligence Policy Act, which establishes disclosure requirements and accountability measures for the use of generative AI in certain consumer interactions. Such additional regulations may impact our ability to develop, use, and commercialize AI technologies in the future. In Europe, the EU Artificial Intelligence Act (the “EU AI Act”), which entered into force in August 2024, establishes a comprehensive, risk-based governance framework for AI in the EU market. The majority of the substantive requirements of the EU AI Act are not enforceable yet and will apply from August 2, 2026. The EU AI Act will have a material impact on the way AI is regulated in the EU, as it applies to companies that develop, use, and/or provide AI in the EU and, depending on the AI use case, includes requirements around transparency, conformity assessments and monitoring, risk assessments, human oversight, security, accuracy, general purpose AI, and foundation models, and imposes fines for breaches of up to 7% of worldwide annual revenues. The EU AI Act, together with developing guidance and/or decisions in this area, may affect our use of AI technologies and our ability to provide, improve, or commercialize our services, require additional compliance measures and changes to our operations and processes, result in increased compliance costs and potential increases in civil claims against us, and could adversely affect our business, operating results, and financial condition. It is possible that further new laws and regulations will be adopted in the United States and in other non-U.S. jurisdictions, or that existing laws and regulations, including competition and antitrust laws, may be interpreted in ways that would limit our ability to use AI technologies for our business, or require us to change the way we use AI technologies in a manner that negatively affects the performance of our offerings and the way in which we use AI technologies. We may need to expend resources to adjust our products or services in certain jurisdictions if the laws, regulations, or decisions are not consistent across jurisdictions. Further, the cost to comply with such laws, regulations, or decisions and/or guidance interpreting existing laws, could be significant and would increase our operating expenses (such as by imposing additional reporting obligations regarding our use of AI technologies). Such an increase in operating expenses, as well as any actual or perceived failure to comply with such laws and regulations, could adversely affect our business, operating results, and financial condition. Moreover, any changes to the above discussed existing legal regimes with respect to data privacy and AI technologies within the United States and abroad could require us to expend significant resources to modify our products, services, or operations to ensure compliance or remain competitive. 77 Existing and future acquisitions, strategic investments, partnerships, or alliances could be difficult to identify and integrate, divert the attention of key management personnel, disrupt our business, dilute stockholder value, and adversely affect our business, operating results, financial condition, and future prospects. As part of our business strategy, we have in the past and expect to continue to make investments in or acquire complementary companies, services, products, technologies, or talent.","ev":{"mit:1.2":"The use of datasets to develop AI models, the content generated by AI systems, or the application of AI systems may be found to be insufficient, offensive, biased, or harmful, or may violate current or future laws and regulations","mit:1.1":"The use of datasets to develop AI models, the content generated by AI systems, or the application of AI systems may be found to be insufficient, offensive, biased, or harmful, or may violate current or future laws and regulations","mit:7.3":"adversely impacted by unforeseen defects, technical challenges, cybersecurity threats, or material performance issues","mit:2.1":"the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information","mit:6.3":"our generative AI technologies could generate output that infringes on third-party intellectual property rights","mit:3.1":"Our generative AI technologies could also generate content that is inaccurate, misleading, or inappropriate","harm:Human or fundamental rights":"the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information","harm:Economic/Property":"we could be subject to claims or lawsuits, including, but not limited to, for infringement of third-party intellectual property rights","harm:Reputational":"Our generative AI technologies could also generate content that is inaccurate, misleading, or inappropriate, which could harm our reputation, expose us to liability, or cause customers to lose confidence in our platform","layer:capability":"The use of datasets to develop AI models, the content generated by AI systems, or the application of AI systems may be found to be insufficient, offensive, biased, or harmful, or may violate current or future laws and regulations","whose:own":"We have made, and expect to continue to make, significant investments to integrate AI, including generative AI, and machine learning technology into our platform","relation:within_purpose":"We have made, and expect to continue to make, significant investments to integrate AI, including generative AI, and machine learning technology into our platform"},"rev":null,"harm_quote":"The use of datasets to develop AI models, the content generated by AI systems, or the application of AI systems may be found to be insufficient, offensive, biased, or harmful, or may violate current or future laws and regulations","status_quote":null,"reports":["0001628280-25-049683"],"forms":{"10-Q":1},"first":"2025-11-05","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-754e43f9d7","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["4.2","2.1"],"primary":"4.2","status":"elsewhere","harm":["Economic/Property","Human or fundamental rights"],"layers":["human_interaction"],"whose":["others"],"relation":["misuse"],"misuse_by":["third_party"],"subjects":[],"text":"Further, state-supported and geopolitical-related cyberattacks may rise in connection with regional geopolitical conflicts which have increased the risk of cyberattacks on various types of infrastructure and 81 operations. Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges. As a result, we may be unable to detect, investigate, remediate, or recover from future attacks or incidents, or to avoid a material adverse impact to our information technology systems, confidential or personal data, or business.","ev":{"status":"Bad actors are also utilizing AI-based tools","mit:4.2":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","mit:2.1":"we may be unable to detect, investigate, remediate, or recover from future attacks or incidents, or to avoid a material adverse impact to our information technology systems, confidential or personal data, or business","harm:Economic/Property":"a material adverse impact to our information technology systems, confidential or personal data, or business","harm:Human or fundamental rights":"confidential or personal data","layer:human_interaction":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","whose:others":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","relation:misuse":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","misuse_by:third_party":"Bad actors are also utilizing AI-based tools"},"rev":null,"harm_quote":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","status_quote":"Bad actors are also utilizing AI-based tools","reports":["0001628280-25-049683"],"forms":{"10-Q":1},"first":"2025-11-05","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-152fac169d","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"tariffs, export and import restrictions, restrictions on foreign investments, sanctions, and other trade barriers or protectionist measures; 87 exposure to numerous, increasing, stringent, and potentially inconsistent laws and regulations relating to, among other things, AI, privacy, data protection, online safety, moderation, and information security; costs of, and challenges with, localizing our platform including, but not limited to, data localization and other data privacy requirements;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-25-049683"],"forms":{"10-Q":1},"first":"2025-11-05","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-6dfab3ad9f","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Our revenue recognition and operating results may be difficult to predict because of the length and unpredictability of the sales cycle for our platform, particularly as we increasingly sell to larger organizations, governmental organizations, regulated entities, and organizations outside of the United States or to the technology industry that may have different procurement requirements than our historical customers. For example, we have observed a lengthening of the sales cycle recently for some 89 prospective customers that we attribute to increased sensitivity to information technology security concerns, particularly with respect to products that include AI features or otherwise incorporate AI technologies, such as our platform. In addition, larger customers frequently have rigorous procurement processes and require considerable time to evaluate, test, and qualify our platform prior to entering into or expanding a relationship with us.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-25-049683"],"forms":{"10-Q":1},"first":"2025-11-05","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-b5ade581b5","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"More generally, the technology industry, and the software industry more specifically, is also subject to substantial and continuous competition for engineers with high levels of experience in designing, developing, and managing software and related services. This is especially true in the market 91 for AI talent, which remains extremely competitive. We have, from time to time, experienced, and we expect to continue to experience, difficulty in hiring and retaining highly skilled employees with appropriate qualifications at a suitable cost, and this risk may be exacerbated by factors related to, among other things, increased recruiting efforts by other companies.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-25-049683"],"forms":{"10-Q":1},"first":"2025-11-05","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-30c718a37d","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Any impairment of the technologies of or our relationship with these third parties could harm our business, operating results, and financial condition. 99 Risks Related to Legal and Regulatory Matters Our business is subject to complex and evolving U.S. and foreign laws, regulations, and industry standards, many of which are subject to change and uncertain interpretations, which uncertainty could harm our business, operating results, and financial condition. We are subject to many U.S. and foreign federal, state, and local laws, regulations, and industry standards that involve matters central to our business, including laws and regulations that involve data privacy, data security, intellectual property, including copyright and patent laws, AI technologies, antitrust and competition, online safety and moderation, employment, labor, immigration, consumer protection, public health, workplace safety, and taxation. These laws and regulations are constantly evolving and may be interpreted, applied, created, or amended, in a manner that could harm our business.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-25-049683"],"forms":{"10-Q":1},"first":"2025-11-05","last":"2025-11-05","end":"2026-02-18"},{"id":"1579878-0327aa8ac2","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"If we fail to properly manage technical debt, our platform performance may suffer, we may face increased downtime, and our business, operating results, and financial condition could be harmed. Additionally, as we further integrate AI capabilities and expand our product offerings, technical complexity has and may 51 continue to increase, potentially exacerbating these challenges. To manage any future growth effectively, we must continue to improve and expand our infrastructure, including information technology and financial infrastructure, our operating and administrative systems and controls, and our ability to manage headcount, capital, and processes in an efficient manner.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-e0acdcf6c8","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"the amount and timing of investments and expenditures related to the expansion of our business; impacts on our cost structure, including, but not limited to, any decrease in our gross margins and operating margins associated with AI-related products and features; the impact of AI on the software creation industry and more generally within the software industry, and on the demand for our platform, products, and services; general macroeconomic and political conditions, both domestically and in foreign markets where we operate, including, but not limited to, changes in U.S. federal spending, the imposition of trade barriers, tariffs, and other protectionist measures, global economic slowdowns, actual or perceived global banking and finance related issues, increased risk of inflation, uncertainty with respect to the U.S. federal debt ceiling and budget and potential U.S. federal government shutdowns related thereto, interest rate volatility, supply chain disruptions, labor shortages, and potential global recession;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209","0001628280-26-053348"],"forms":{"10-Q":2},"first":"2026-05-14","last":"2026-08-05","end":null},{"id":"1579878-42e90d3f9b","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"In addition, in March 2025, we implemented significant changes to our pricing, packaging, and billing models. In 2025, we introduced AI credits across all Figma seats. Starting in March 2026, we began enforcing AI credit limits and introduced flexible options for incremental usage, including monthly AI credit add‑ons to existing subscriptions or usage billed under a pay‑as‑you‑go model. Accordingly, we have a limited operating history at our current scale of business, and with our current product offerings and pricing, packaging, and billing models, which makes it difficult to evaluate our current business, future prospects, and other trends.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-a14d2ccaa0","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["4.3"],"primary":"4.3","status":"hypothetical","harm":["Economic/Property"],"layers":["human_interaction"],"whose":["others"],"relation":["misuse"],"misuse_by":["user","third_party"],"subjects":[],"text":"We made these changes to keep pace with our expanded offerings and features since our platform’s launch and to 54 provide our customers with more visibility and upfront controls. In 2025, we also introduced AI credits across all Figma seats. Starting in March 2026, we began enforcing AI credit limits and introduced flexible options for incremental usage, including monthly AI credit add‑ons to existing subscriptions or usage billed under a pay‑as‑you‑go model. We may become unable to attract new customers and retain existing customers at the same price or based on the same seat-based subscription model that we have used historically. We may from time to time decide to make further changes to our billing models due to a variety of reasons, including, but not limited to, changes to the markets for our products and services, increased use of AI in the software industry generally, increased implementation and use of AI features in our products, pricing pressures, and the introduction of new products and services by us or by our competitors. If we are unable to implement changes to our billing models in a timely manner or at all, including as a result of delays associated with our billing infrastructure or product development processes, our business, operating results, and financial condition could be negatively impacted. Our new pricing, packaging, and billing models may not accurately reflect the optimal pricing, packaging, and billing models necessary to attract new customers and retain existing customers, which may make it difficult to accurately plan and forecast our operating results. Furthermore, the changes to our pricing and packaging plans introduced in March 2025 and the enforcement of AI credit limits beginning in March 2026 have made, and any further changes to components of our pricing, packaging, and billing models that we may introduce in the future may make, forecasting our operating results more difficult and result in comparisons to periods prior to the updates being less meaningful as some of the drivers underlying our business model will have changed. In addition, we may offer, or customers may demand, options that change who bears the cost of AI usage or how AI usage is provisioned, including by allowing customers to use their own third-party AI credentials or accounts (for example, bring-your-own-key arrangements), which may reduce the amount of AI usage that is metered through our AI credit programs. Such arrangements may increase certain costs (including, but not limited to, costs relating to engineering, infrastructure, security, compliance, and support), impact our margins, materially change the amount, mix, and timing of our revenue, and make our operating results harder to forecast. The net impact of any such arrangements on our revenue, margins, and cash flows may be difficult to predict and may vary across customers, products, and periods. Any such arrangements could also reduce our ability to meter, price, and control AI usage, and increase billing complexity, support burdens, and disputes. Our ability to increase or maintain our prices may be constrained by competitive dynamics, customer expectations or pressure to provide discounts, or economic conditions. Pricing pressure may require us to reduce the price we charge our customers for usage of our AI products and features, absorb additional costs, or operate certain AI features at lower or negative gross margins for extended periods in order to remain competitive. Moreover, competitive dynamics may result in customers expecting full AI functionality to be included in baseline subscription pricing, which may lead customers to curtail their use of our products and features subject to AI credit pricing, including Figma Make and other AI features, or to stop using those products and features altogether, and may limit our ability to monetize the usage of our AI products and features in a manner that offsets associated costs. In addition, the unit economics of AI products and features may be volatile and difficult to predict, including due to changes in third-party model pricing, infrastructure costs, usage patterns, and the rate at which customers adopt AI-powered workflows. If we are unable to increase prices to offset rising costs, including costs related to AI inference or otherwise related to providing AI features, or to otherwise update our pricing model, including to better align it with the increased integration of AI into our platform, or if price increases or other changes to our pricing model significantly reduce customer demand, our business, operating results, and financial condition could be negatively impacted. Further, as AI and its integration into software becomes more prevalent and its use cases become more sophisticated, including with respect to our products and the products of our competitors, there could be a 55 decrease in the number of designers, developers, and other collaborators that use our platform if such individuals are able to significantly increase their efficiency through the use of AI capabilities alongside or instead of our platform. Such a decrease could reduce the number of seats that customers or potential customers subscribe to, which could lead to a loss of revenue, slower growth, and adversely impact our business, operating results, and financial condition. Our seat-based subscription model may become less aligned with customer value creation as AI automates or consolidates work that historically required multiple users. In response to any industry changes resulting from AI, we may need to make further changes to our billing practices, including potential changes to our seat-based subscription model. If we are unable to adapt our pricing and packaging models quickly and effectively, our revenue growth, margins, business, operating results, and financial condition could be negatively impacted. Changes to our pricing, packaging, and billing models, including the changes to our pricing and packaging plans introduced in March 2025 and the enforcement of AI credit limits starting in March 2026, and any further changes that we make in the future, may, among other things, result in customer dissatisfaction, lead to a loss of customers, result in customers curtailing or stopping their usage of our products and features subject to AI credit pricing, including Figma Make and other AI features, harm our brand, and negatively impact our business, operating results, and financial condition. For example, following our enforcement of AI credit limits starting in March 2026, we observed elevated customer support volume, instances of customer dissatisfaction expressed through public and social channels, and reduced usage by certain customers. While we are continuing to evaluate the longer-term impact, we may experience further dissatisfaction, dispute resolution costs, or customer churn in the future. Third-party AI agents and tools that operate on or through our platform may circumvent our pricing and packaging models, increase our costs, and adversely affect our business, operating results, financial condition, and future prospects. In March 2026, we introduced the ability for third-party AI agents to create and modify real design assets directly in Figma files through our MCP server. Customers may also use, or third parties may develop, tools that automate or orchestrate workflows on our platform (including through browser extensions, plugins, scripts, bots, or other third-party tools). The introduction of AI agents or other third-party tools on our platform could reduce the number of paid seats required for a given level of output, circumvent or undermine our intended pricing and packaging controls, increase platform load, or create fraud and abuse risk. If we are unable to detect and effectively monetize such activity, or if we restrict or limit such tools and customers react negatively, our revenue, margins, growth, and reputation could be adversely affected.","ev":{"mit:4.3":"The introduction of AI agents or other third-party tools on our platform could reduce the number of paid seats required for a given level of output, circumvent or undermine our intended pricing and packaging controls, increase platform load, or create fraud and abuse risk.","harm:Economic/Property":"Third-party AI agents and tools that operate on or through our platform may circumvent our pricing and packaging models, increase our costs, and adversely affect our business, operating results, financial condition, and future prospects.","layer:human_interaction":"Third-party AI agents and tools that operate on or through our platform may circumvent our pricing and packaging models, increase our costs, and adversely affect our business, operating results, financial condition, and future prospects.","whose:others":"In March 2026, we introduced the ability for third-party AI agents to create and modify real design assets directly in Figma files through our MCP server.","relation:misuse":"Third-party AI agents and tools that operate on or through our platform may circumvent our pricing and packaging models, increase our costs, and adversely affect our business, operating results, financial condition, and future prospects.","misuse_by:user":"Customers may also use, or third parties may develop, tools that automate or orchestrate workflows on our platform","misuse_by:third_party":"Customers may also use, or third parties may develop, tools that automate or orchestrate workflows on our platform"},"rev":null,"harm_quote":"The introduction of AI agents or other third-party tools on our platform could reduce the number of paid seats required for a given level of output, circumvent or undermine our intended pricing and packaging controls, increase platform load, or create fraud and abuse risk.","status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-ed2f498c02","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Any such approach may also increase complexity for our customers and our sales, finance, and support teams, may create disagreement over whether such usage should be charged to a customer, a third-party agent provider, or a third-party model provider, may not align with customer expectations, and may not generate the revenue or margins we expect. In addition, third parties have introduced, and we expect they will continue to develop, browser-based, operating-system-based, and other autonomous AI agents that operate software platforms, including ours, on a user’s behalf, including agents offered by providers whose models we license or with which we otherwise integrate. Because these external agents typically interact with our platform using a single user’s authenticated session, our seat-based pricing, billing, administrative controls, monitoring, and terms of service may be less effective at identifying agent activity, attributing usage to the appropriate party, detecting automation, or determining when additional seats, credits, or charges should apply. As external AI agents become more capable, customers may use them to perform tasks that would otherwise 56 require additional users, seats, or activity on our platform, which could reduce demand for paid seats, accelerate seat-replacement dynamics, or shift workflows away from our user interface and toward third-party agent interfaces, any of which could erode the perceived value or differentiation of our platform. We may need to invest in new identification, attribution, authentication, governance, and pricing mechanisms, and we may face conflicting demands from customers, including enterprise customers seeking to restrict agent activity for governance, security, or compliance reasons and other customers seeking to permit or expand agent activity. We may not be able to address these demands in a timely or commercially reasonable manner, and our decisions to permit, restrict, monetize, or otherwise govern external agent activity, or any technical or contractual measures we adopt or fail to adopt, could result in customer dissatisfaction, contractual or regulatory disputes (including with the operators of such agents), reduced adoption of our platform, or reputational harm. The legal and regulatory framework applicable to external AI agents, including with respect to terms-of-service enforceability, liability for content generated through agent activity, and competition and platform-access requirements, is unsettled and evolving, and adverse developments could increase our costs, limit our ability to control agent activity on our platform, or otherwise adversely affect our business, operating results, and financial condition. Over time, we expect to introduce products, features, and services, or otherwise implement pricing and packaging models, that are billed differently than on a per-seat subscription basis, which could adversely affect our business, operating results, financial condition, and future prospects. Over time, we expect to introduce products, features, and services, or to otherwise implement pricing and packaging models, that are billed differently than on a per-seat subscription basis. For example, in 2025, we introduced AI credits across all Figma seats. Starting in March 2026, we began enforcing AI credit limits and introduced flexible options for incremental usage, including monthly AI credit add‑ons to existing subscriptions or usage billed under a pay‑as‑you‑go model. Credit-based, usage-based, or outcome-based billing models increase the complexity of accurately measuring and charging for product usage, and may increase the risk of billing disputes, reduced collectibility, refunds, chargebacks, and regulatory scrutiny. As we begin enforcing AI credit limits and have introduced flexible options for incremental usage, including monthly AI credit add‑ons to existing subscriptions or usage billed under a pay‑as‑you‑go model, we expect that the mechanisms by which we meter, attribute, and report usage will become more complex. Customer trust in these models may depend in part on our ability to provide clear, accurate, and timely visibility into usage, balances, limits, overages, and applicable charges.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-0bbc4232a6","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["7.3"],"primary":"7.3","status":"hypothetical","harm":["Economic/Property"],"layers":["capability"],"whose":["own"],"relation":["within_purpose"],"misuse_by":[],"subjects":[{"name":"customers","type":"Organization"}],"text":"Any of the foregoing could adversely affect our business, operating results, financial condition, and future prospects. In particular, customers may react negatively if AI credits are consumed in connection with failed, unstable, or interrupted outputs or if administrators cannot readily determine what users, files, prompts, models, or workflows are driving usage. If we are unable to provide sufficient visibility, controls, alerts, or remediation in such circumstances, customers may perceive our billing as unfair, reduce usage, seek 57 credits or refunds, delay deployments, or consider alternative products, any of which could adversely affect our business, operating results, financial condition, and future prospects. Further, adoption of AI products and features by larger organizations may depend on our ability to provide enterprise-grade administrative controls, permissioning, governance, transparency, and policy management. Enterprise customers may require the ability to control which users, groups, teams, or business units can access AI features, which models can be used, how usage is allocated or pooled, how spending is capped or approved, and how outputs and prompts are governed for compliance or security purposes. If we do not provide such controls in a timely manner, or if customers determine that our controls are inadequate for their governance, compliance, procurement, or budgeting requirements, they may delay deployment, limit purchases, reduce usage, or choose competitive offerings, which could adversely affect our business, operating results, financial condition, and future prospects.","ev":{"mit:7.3":"customers may react negatively if AI credits are consumed in connection with failed, unstable, or interrupted outputs","harm:Economic/Property":"customers may perceive our billing as unfair, reduce usage, seek 57 credits or refunds, delay deployments, or consider alternative products, any of which could adversely affect our business, operating results, financial condition, and future prospects","layer:capability":"customers may react negatively if AI credits are consumed in connection with failed, unstable, or interrupted outputs","whose:own":"customers may react negatively if AI credits are consumed in connection with failed, unstable, or interrupted outputs","relation:within_purpose":"customers may react negatively if AI credits are consumed in connection with failed, unstable, or interrupted outputs"},"rev":null,"harm_quote":"customers may react negatively if AI credits are consumed in connection with failed, unstable, or interrupted outputs","status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-e670d6ade8","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Customers have no obligation to renew a subscription after the expiration of the contract term, and customers may not renew their subscriptions with a similar contract period, with the same or greater number of seats, for the same subscription plan, or at all. In addition, starting in March 2026, we began enforcing AI credit limits and introduced flexible options for incremental usage, including monthly AI credit add‑ons to existing subscriptions or usage billed under a pay‑as‑you‑go model. Customers are under no obligation to purchase monthly AI credit add‑ons to their existing subscriptions or AI usage under the pay‑as‑you‑go billing model, and they may curtail or stop their usage of our AI-powered products and features at any time. If our customers do not renew their subscriptions or if they renew on terms less favorable to us, or if our customers curtail or stop their usage of our AI-powered products and features in light of our AI credit billing model, our business, operating results, financial condition, and future prospects may be adversely impacted. Our customer retention may decline or fluctuate as a result of various factors, including, but not limited to, their satisfaction with our platform, products, and services and satisfaction with those offered by 58 competitors, our pricing, packaging, and billing models and changes to such models including our recent and any future pricing changes, and the effects of general economic conditions and uncertainty in financial markets. Further, our future success depends, in part, on our ability to convert users of our free plan into paying customers on a paid pricing plan and selling additional offerings, including monthly AI credit add‑ons to customers’ existing subscriptions or AI usage under the pay‑as‑you‑go billing model, to existing paying customers. This may require us to incur increased sales and marketing expenses, but it may not result in additional sales.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-b45c2f82fa","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["4.3","4.2","3.1","7.3","2.1"],"primary":"4.3","status":"hypothetical","harm":["Economic/Property","Public interest","Human or fundamental rights","Reputational"],"layers":["human_interaction","systemic"],"whose":["general","others","own"],"relation":["misuse","within_purpose"],"misuse_by":["third_party"],"subjects":[],"text":"There can be no assurance that customer demand for such initiatives will exist or be sustained at the levels that we anticipate, or that any of these initiatives will gain sufficient traction or market adoption to generate sufficient revenue to offset any new expenses or liabilities associated with these new investments. It is also possible that products and services developed by others, including, but not limited to, new technologies integrating AI, or products and services developed by competitors that employ a credit-based, usage-based, or outcome-based pricing model, will render our platform and offerings uncompetitive or obsolete. Further, our development efforts with respect to new technologies, offerings, features, and functionality could distract management from current operations, and would divert capital and other resources from our more established offerings. If we do not realize the expected benefits of our investments, our business, operating results, financial condition, and future prospects could be adversely affected. Competitive developments in AI and our inability to effectively respond to such developments could adversely affect our business, operating results, and financial condition. Developments in AI are already impacting the software industry significantly, and we expect this impact to be even greater in the future. AI has become more prevalent in the markets in which we operate and may 60 result in significant changes in the demand for our platform, including, but not limited to, reducing the difficulty and cost for competitors to build and launch competitive products, altering how consumers and businesses interact with websites and apps and consume content in ways that may result in a reduction in the overall value of interface design, or by otherwise making aspects of our platform obsolete or decreasing the number of designers, developers, and other collaborators that utilize our platform. Any of these changes could, in turn, lead to a loss of revenue and adversely impact our business, operating results, and financial condition. While we have made, and expect to continue to make, significant investments to integrate AI, including generative AI, into our platform, AI technologies are rapidly evolving and there can be no guarantee that our products will remain competitive as new AI technologies are developed, adopted, and integrated into software solutions. We expect that increased investment will be required in the future to continuously improve our use of AI technologies. As with many technological innovations, there are significant risks involved in developing, maintaining, and deploying AI. There can be no assurance that the integration of such technologies will enhance our products or services or be beneficial to our business, including, but not limited to, with respect to our efficiency or profitability. Similarly, we cannot guarantee that our investments in the development and integration of AI will be successful or provide an adequate return, including, without limitation, with respect to the amount of time, focus, and staffing directed towards these efforts. Our announced or perceived AI roadmap and product strategy may create heightened expectations among customers and investors, and if we fail to meet those expectations, our business, operating results, financial condition, and future prospects could be adversely affected. As AI models and tooling improve, customers may increasingly expect higher quality outputs, faster iteration cycles, greater reliability, and more seamless end-to-end workflows from design and development platforms. More capable general-purpose AI models released by major providers are or may soon become widely accessible, and if we do not keep pace with rising expectations, customers may reduce usage, delay or forgo purchases, or switch to competing products. In addition, customer expectations regarding the speed, availability, and performance of AI features may increase over time, which could require us to incur higher infrastructure and model costs that we may not be able to recover through pricing. Our ability to keep pace with these expectations may depend on our continued access to advanced third-party AI models and sufficient inference capacity, including from a limited number of foundational model providers. If we are unable to secure or maintain such access on commercially reasonable terms, or if such providers impose usage restrictions, experience outages, or face capacity constraints, our AI features may be delayed, degraded, or unavailable, which could adversely affect our business, operating results, and financial condition. Our AI products and features may depend on a limited number of third-party model providers or other AI technology partners that may at the same time offer competing products, seek to intermediate end-user relationships directly, influence customer preferences through their own platforms or marketplaces, or otherwise reduce the differentiated value of software companies that build on top of their models. If such providers limit our access, change economic terms, prioritize their own products or strategic partners, or otherwise reduce our ability to differentiate or monetize our offerings, our business, operating results, and financial condition could be adversely affected. Certain third-party model providers, AI platforms, and agent ecosystems may increasingly control user identity, authentication, tool selection, billing relationships, discovery, or workflow routing for activities that incorporate our products or services. If users are encouraged or enabled to access our products or services through such providers’ subscriptions, token systems, marketplaces, or agent frameworks, our ability to control distribution, customer relationships, pricing, and monetization may be reduced. Such providers may also influence which tools agents use, how usage is attributed, and which party bears the cost of inference or other activity, which could increase pricing pressure, reduce our margins, or otherwise adversely affect our business, operating results, and financial condition. 61 Competition in AI-enabled products and workflows may be especially intense with respect to pricing and margins. Certain competitors, including larger platform providers, model providers, AI-native companies, or well-capitalized startups, may offer competing AI-powered functionality at very low prices, bundle such functionality into broader offerings, subsidize usage for extended periods, or operate at margins that are lower than those historically associated with our core software products. Such practices may condition customers to expect AI functionality to be included at low or no incremental cost and may make it difficult for us to price our AI products and features, including more AI-native or media-intensive offerings, in a manner that offsets inference, model access, hosting, support, safety, and other associated costs. These risks may be more pronounced for certain newer offerings or workflows that rely more heavily on third-party model usage or that have materially different cost structures than our more established products. If we are unable to compete effectively in this environment or if the economics of our AI products and features are less favorable than those of our historical offerings, our revenue growth, gross margins, operating margins, and financial condition could be adversely affected. Further, our competitors may incorporate AI into their products more quickly or more successfully than we do, which would impair our ability to compete effectively. Decisions as to if and how to integrate various AI technologies are difficult and we may choose not to adopt certain technologies or take advantage of certain data sets available to us as a result of ethical, legal, regulatory, or reputational concerns, which could put us at a competitive disadvantage and harm our business, operating results, and financial condition. For example, we, or our customers, may choose, or be required, not to use some high-performing or low-cost open-source models due to security, compliance, export control, sanctions, procurement, or reputational considerations. If our competitors use such models and no comparable alternative is available, we could be at a competitive disadvantage and our business, operating results, and financial condition may be harmed as a result. In the future, we may seek to co-train or otherwise customize AI models with third parties or using additional datasets. Efforts to co-train, fine-tune, or otherwise customize AI models may also require significant expenditures on compute, data preparation, evaluation, experimentation, infrastructure, and personnel, and such efforts may need to be repeated as base models, model providers, customer expectations, or legal and regulatory requirements evolve. These efforts may be costly, may not result in durable performance improvements, may become obsolete more quickly than anticipated, may require us to share or process additional data with third parties or in new environments, and could increase risks related to data rights, privacy, security, confidentiality, intellectual property, regulatory compliance, and partner dependency, any of which could adversely affect our business and reputation. AI technologies are rapidly changing how digital products and experiences are being designed, prototyped, and built. These shifts may be unpredictable and could include new interaction paradigms, devices, or form factors (such as through AI agents or assistants, conversational or voice-driven workflows, mixed reality or other new form factors, AI agent collaboration, or experiences delivered through operating systems or a small number of ecosystems). This may change how people access and interact with digital products in ways that reduce reliance on traditional software applications, websites, and graphical user interfaces. For example, in an interaction paradigm in which AI agents collaborate with other agents or transact directly with digital services on behalf of users, customers may shift workflows away from traditional user interfaces and toward alternative agent-mediated environments. This could also reduce the amount of traditional interface design, prototyping, and front-end development work that organizations choose to perform or maintain, or cause our customers to shift the performance of certain tasks or workflows into other environments or toolchains outside our platform. For example: customers may consolidate purchasing decisions around vendors that bundle AI capabilities across broader software suites or purchase from other vendors that provide end-to-end “design-to-code” or “prompt-to-product” experiences; 62 organizations may reduce the number of designers, developers, or collaborators required to deliver products, which may lead to them reducing the number of seats purchased or renewed even if output increases; customers may shift preferences from per-seat subscriptions to credit-based, usage-based, or outcome-based billing models, which may increase pricing pressure, reduce predictability of revenue, and adversely affect our margins; and switching costs may decline as AI tools improve interoperability, automated conversion of files, or automated recreation of design systems across platforms. If these changes reduce demand for our platform or disrupt our monetization model, this could adversely affect our business, operating results, and financial condition. Our failure to successfully develop, commercialize, or effectively monetize our products or services involving AI technologies could impact the price of our Class A common stock and impair our ability to raise capital, expand our business, improve and diversify our product offerings, efficiently manage our operating expenses, and respond effectively to competitive developments. Moreover, the use of AI technologies and our investments to integrate AI into our platform may adversely impact our business, operating results, and financial condition. For example, in the short term, we expect that our AI investments and use of AI technologies, including as part of Figma Make and our other AI features, will negatively impact our gross margins and operating margins and, given the newness of and rapid development of these technologies, the impacts on our gross margins and operating margins, and on our business, operating results, financial condition, and future prospects over the longer term, are currently unknown. More generally, advances in AI could be transformative and may occur more rapidly than anticipated. The development of highly capable general-purpose or autonomous AI systems, including the potential emergence of artificial general intelligence or superintelligence, could lead to significant economic, societal, political, and geopolitical disruption. Such disruption could reduce demand for our products, change how organizations staff and budget for design and product development, and increase volatility in customer spending. It could also prompt governments to adopt emergency measures or sweeping new regulations, restrictions, or moratoria on the development, deployment, or use of advanced AI systems, or to regulate access to compute, chips, energy, or cloud infrastructure, any of which could increase our costs, delay or limit our ability to offer AI features, or require us to materially modify our products, business model, or operations. In addition, serious harms attributed to advanced AI systems, including widespread fraud, cyberattacks, misinformation, automated reconnaissance, or other safety incidents, could increase litigation risk and reputational harm for companies offering AI-enabled products, even where such harms are caused by third parties or are outside our control. Any of the foregoing could adversely affect our business, operating results, and financial condition.","ev":{"mit:4.3":"widespread fraud","mit:4.2":"cyberattacks","mit:3.1":"misinformation","mit:7.3":"our AI features may be delayed, degraded, or unavailable","mit:2.1":"increase risks related to data rights, privacy, security, confidentiality","harm:Economic/Property":"could increase litigation risk and reputational harm for companies offering AI-enabled products","harm:Public interest":"could lead to significant economic, societal, political, and geopolitical disruption","harm:Human or fundamental rights":"increase risks related to data rights, privacy","harm:Reputational":"reputational harm for companies offering AI-enabled products","layer:human_interaction":"serious harms attributed to advanced AI systems, including widespread fraud, cyberattacks, misinformation, automated reconnaissance, or other safety incidents","layer:systemic":"could lead to significant economic, societal, political, and geopolitical disruption","whose:general":"The development of highly capable general-purpose or autonomous AI systems","whose:others":"More capable general-purpose AI models released by major providers","whose:own":"we expect that our AI investments and use of AI technologies, including as part of Figma Make and our other AI features","relation:misuse":"even where such harms are caused by third parties or are outside our control","relation:within_purpose":"our AI features may be delayed, degraded, or unavailable","misuse_by:third_party":"even where such harms are caused by third parties or are outside our control"},"rev":null,"harm_quote":"widespread fraud","status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-82a812dc39","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The markets in which we participate are rapidly evolving and highly competitive, and if we do not compete effectively, our business, operating results, and financial condition could be adversely impacted. We face competition from a number of companies, including companies that cater to multiple stages of the design and development process, point tools that address individual parts of the process but can expand to cover more, and design-to-code and AI-driven companies and tools that compress or accelerate steps in the workflow, take a different approach to building digital experiences, or automatically generate and iterate on designs and code through a prompt or with limited human input. We may also face competition from customized or internal solutions used by our customers or potential customers, particularly with AI’s potential to accelerate the ability to develop and deploy new software. Moreover, we expect to continue to 63 face intense competition from current competitors, as well as from new entrants into the market, including as a result of strategic acquisitions and partnerships, increased use of AI, or evolving user and customer requirements and industry standards. If we are unable to anticipate or react to these challenges, our competitive position could weaken, and we may experience a decline in revenue, reduced revenue growth, or a loss of market share, which, individually or collectively, could adversely affect our business, operating results, and financial condition.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-7813433798","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Our competitors may be able to devote greater resources to the development, promotion, and sale of their products and services than we can, and they may offer lower pricing than we do or bundle certain competing products and services at lower prices or for free. For example, AI-enabled offerings by large platform companies, AI model providers and other technology providers, whether standalone or embedded in broader platforms, could reduce the perceived value of our standalone offerings and pressure our pricing and market position. Our competitors may also have greater resources for research and development of new technologies, customer support, and to pursue acquisitions, or they may have other financial, technical, or other resource advantages.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-c558ffdbeb","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["2.1","1.2","1.1","3.1","7.3","2.2","4.3","6.3"],"primary":"2.1","status":"materialised","harm":["Human or fundamental rights","Economic/Property","Reputational"],"layers":["capability","human_interaction"],"whose":["own","general"],"relation":["within_purpose","misuse"],"misuse_by":["user","third_party"],"subjects":[{"name":"end users","type":"Group of persons"},{"name":"customers","type":"Organization"}],"text":"If the markets for our platform do not grow to the extent that we anticipate or our platform does not achieve further widespread adoption within the markets in which we operate, our business, operating results, financial condition, and future prospects could be adversely affected. Our use of AI in our products and services may result in reputational harm, legal liability, competitive risks, and regulatory concerns that could adversely affect our business, operating results, and financial condition. We have made, and expect to continue to make, significant investments to integrate AI, including generative AI, and machine learning technology into our platform, including as part of our Figma Make product and Figma AI features. Many AI technologies are relatively new and present ethical, legal, regulatory, and reputational challenges. The use of datasets to develop AI models, the content generated by AI systems, or the application of AI systems may be found to be insufficient, offensive, biased, or harmful, or may violate current or future laws and regulations or contractual commitments. Standards and expectations regarding AI safety, acceptable outputs, and appropriate safeguards are evolving and may differ across our industry, customers, regulators, and the public, including across different geographies, cultures, and political environments, and there may be no consensus on what constitutes safe behavior for a given use case. We may be unable or unwilling to implement controls that satisfy all such expectations, and our decisions about whether and how to restrict or moderate AI outputs could result in customer dissatisfaction, reputational harm, or regulatory scrutiny. Certain AI technologies have come under public scrutiny due to allegations that they generate inaccurate, incomplete, or misleading content, introduce unintended biases, and produce other discriminatory or unexpected results, errors, or inadequacies. Consumer and societal attitudes toward AI are evolving and there is a risk that regulators or the public may perceive AI technologies negatively. Concerns about automation, automated decision-making, privacy, security, transparency, and other ethical considerations could deter AI adoption. The insurance coverage we maintain may not extend to all AI-related risks we may face, and may not cover us for all losses for errors or omissions caused by AI. Further, we generally rely on third-party models for the AI features on our platform. Our ability to continue to use such technologies at scale may be dependent on access to certain limited or specific third-party software and infrastructure providers. We cannot control the availability or pricing of such third-party AI technologies, especially in a highly competitive environment, and we may be unable to negotiate favorable economic terms with the applicable providers. Providers may also experience capacity constraints or prioritize other customers, which could limit the availability or performance of our AI features. If any such third-party AI technologies become incompatible with our platform or unavailable for 66 use, or if the providers of such models unfavorably change the terms on which their AI technologies are offered or terminate their relationship with us, our platform may become less appealing to our customers, and our business, operating results, and financial condition could be adversely impacted. Moreover, the integration of third-party AI models with our platform relies on certain safeguards implemented by the third-party developers of the underlying AI models, including those related to the accuracy, bias, and other variables of the training data used for such models, and these safeguards may be insufficient. In addition, if our AI features do not provide customers with sufficient administrative controls, transparency, documentation, or governance capabilities, customers may determine that such products and features are not suitable for regulated, security-sensitive, or enterprise use cases, which could reduce adoption, increase contractual disputes, or heighten scrutiny by regulators. If the models underlying our AI technologies, whether developed by a third party or developed by us, are incorrectly designed or implemented; trained or reliant on incomplete, inadequate, inaccurate, biased or otherwise poor quality data, or on data to which we do not have sufficient rights or in relation to which we and/or the providers of such data have not implemented sufficient legal compliance measures; used without sufficient oversight and governance to ensure their responsible use; and/or adversely impacted by unforeseen defects, technical challenges, cybersecurity threats, or material performance issues, the performance of our products, services, and business, as well as our reputation and our customers’ reputations, could suffer, and we could incur liability resulting from the violation of laws, breach of contract claims, or civil claims. For example, we are, and may in the future become, subject to litigation alleging breach of contract and related claims arising from allegations regarding the use of user data in connection with AI training, trade secret misappropriation, and violations of various state and federal statutes. Such claims can be costly to defend, may result in adverse judgments or settlements, may require changes to our products, policies, contracts, or business practices (including limitations on certain AI features or how data may be processed), and could harm our reputation and relationships with users. Further, claims, litigation, or regulatory actions relating to AI data practices may seek remedies beyond monetary damages, including injunctive relief, and could require us to make material changes to our products or business practices. Any such changes could be costly, technically complex, and disruptive to our product roadmap and operations, could reduce the performance or usefulness of our AI features, and could adversely affect customer relationships, revenue, and growth. In addition, the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information. Such leakage or unauthorized exposure of data related to the use of AI applications could result in legal claims or liability or otherwise adversely affect our reputation and operating results. The above risks may be increased by the introduction of our Figma Weave product, which contains many AI models, some of which are entirely independent third-party models that are provided to customers “as is.” AI products and features may introduce additional security vulnerabilities and threat vectors beyond traditional software risks (including prompt injection, data poisoning, model inversion, membership inference, latent or hidden behaviors that are difficult to detect in testing and that may be triggered under certain conditions, and other attacks designed to cause models to disclose sensitive information), behave in unintended ways, or produce harmful or misleading outputs. Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage. Such activity could increase our costs (including AI inference and support costs), result in fraud, billing disputes, or chargebacks, and cause reputational harm or liability. In addition, the use of third-party models and toolchains may increase supply-chain risk, including the risk that model weights, safety layers, or dependencies are compromised, misconfigured, or updated in ways that degrade security or performance. If any of these vulnerabilities result in the unauthorized disclosure of customer content, confidential information, personal data, or proprietary information, or if customers believe our AI features are not sufficiently secure for their use cases, we could face contractual claims, indemnity demands, regulatory scrutiny, reputational harm, and reduced adoption of our AI features or platform. 67 Moreover, our AI technologies could generate output that infringes on third-party intellectual property rights, and we could be subject to claims or lawsuits, including, but not limited to, for infringement of third-party intellectual property rights as a result of the output of such AI technologies. While some providers of AI technologies offer to indemnify their end users for any copyright or other intellectual property infringement claims arising from the output of their AI technologies, such indemnification may be inadequate or we may not be successful in adequately recovering our losses in connection with such claims. Our AI technologies could also generate content that is inaccurate, misleading, or inappropriate, which could harm our reputation, expose us to liability, or cause customers to lose confidence in our platform. The regulatory framework for AI technologies is rapidly evolving as many U.S. federal, state, and foreign government bodies and agencies have introduced or are currently considering additional laws and regulations. Additionally, existing laws and regulations may be interpreted in ways that would affect the operation of our AI technologies or could be rescinded or amended as new administrations take differing approaches to evolving AI technologies. As a result, implementation standards and enforcement practices are likely to remain uncertain for the foreseeable future, and we cannot yet completely determine the impact future laws, regulations, standards, or market perception of their requirements may have on our business and may not always be able to anticipate how to respond to these laws or regulations. Already, certain existing legal regimes, for example, relating to data privacy, regulate certain aspects of AI technologies, and new laws regulating AI technologies have recently entered into force in the United States and the EEA. In the United States, there is an ongoing tension between the states and the federal government over how best to regulate the use of AI. A number of U.S. states, such as California and Colorado, have proposed or enacted laws regarding automated decision‑making, algorithmic discrimination, and so-called “high‑risk” AI technologies (mandating, among other provisions, requirements for risk management, impact assessments, consumer notices, and human oversight), which may impact our use of AI and AI-powered tools. However, the status of such laws is currently uncertain as the federal government takes steps towards establishing broad federal AI regulation that could preempt all or some state law. Any such additional regulation may impact our ability to develop, use, and commercialize AI technologies in the future. In Europe, the EU Artificial Intelligence Act (the “EU AI Act”) establishes a comprehensive, risk-based governance framework for AI in the EU market. The EU AI Act will have a material impact on the way AI is regulated in the EU, as it applies to companies that develop, use, and/or provide AI in the EU and, depending on the AI use case, includes requirements around transparency, conformity assessments and monitoring, risk assessments, human oversight, security, accuracy, general purpose AI, and foundation models, and imposes substantial fines for breaches. The EU AI Act, together with developing guidance and/or decisions in this area, may affect our use of AI technologies and our ability to provide, improve, or commercialize our services, require additional compliance measures and changes to our operations and processes, result in increased compliance costs and potential increases in civil claims against us, and could adversely affect our business, operating results, and financial condition. It is possible that further new laws and regulations will be adopted in the United States and in other non-U.S. jurisdictions, or that existing laws and regulations, including competition and antitrust laws, may be interpreted in ways that would limit our ability to use AI technologies for our business, or require us to change the way we use AI technologies in a manner that negatively affects the performance of our offerings and the way in which we use AI technologies. We may need to expend resources to adjust our products, services, or operating procedures in certain jurisdictions if the laws, regulations, or decisions regarding AI technologies are not consistent across jurisdictions. Further, the cost to comply with such laws, regulations, or decisions and/or guidance interpreting existing laws, could be significant and would increase our operating expenses (such as by imposing additional reporting and compliance obligations regarding our use of AI technologies). Such an increase in operating expenses, as well as any actual or perceived failure to comply with such laws and regulations, could adversely affect our business, operating results, and financial condition. 68 Moreover, any changes to the above discussed existing legal regimes with respect to data privacy and AI technologies within the United States and abroad could require us to expend significant resources to modify our products, services, or operations to ensure compliance or remain competitive. Existing and future acquisitions, strategic investments, partnerships, or alliances could be difficult to identify and integrate, divert the attention of key management personnel, disrupt our business, dilute stockholder value, and adversely affect our business, operating results, financial condition, and future prospects.","ev":{"status":"we are, and may in the future become, subject to litigation alleging breach of contract and related claims arising from allegations regarding the use of user data in connection with AI training","mit:2.1":"the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information","mit:1.2":"The use of datasets to develop AI models, the content generated by AI systems, or the application of AI systems may be found to be insufficient, offensive, biased, or harmful","mit:1.1":"introduce unintended biases, and produce other discriminatory or unexpected results, errors, or inadequacies","mit:3.1":"Our AI technologies could also generate content that is inaccurate, misleading, or inappropriate","mit:7.3":"behave in unintended ways, or produce harmful or misleading outputs","mit:2.2":"AI products and features may introduce additional security vulnerabilities and threat vectors beyond traditional software risks (including prompt injection, data poisoning, model inversion, membership inference, latent or hidden behaviors that are difficult to detect in testing and that may be triggered under certain conditions, and other attacks designed to cause models to disclose sensitive information)","mit:4.3":"Such activity could increase our costs (including AI inference and support costs), result in fraud, billing disputes, or chargebacks, and cause reputational harm or liability","mit:6.3":"our AI technologies could generate output that infringes on third-party intellectual property rights","harm:Human or fundamental rights":"the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information","harm:Economic/Property":"Such activity could increase our costs (including AI inference and support costs), result in fraud, billing disputes, or chargebacks, and cause reputational harm or liability","harm:Reputational":"Our AI technologies could also generate content that is inaccurate, misleading, or inappropriate, which could harm our reputation, expose us to liability, or cause customers to lose confidence in our platform","layer:capability":"Our AI technologies could also generate content that is inaccurate, misleading, or inappropriate","layer:human_interaction":"Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage","whose:own":"Our use of AI in our products and services may result in reputational harm, legal liability, competitive risks, and regulatory concerns","whose:general":"Many AI technologies are relatively new and present ethical, legal, regulatory, and reputational challenges","relation:within_purpose":"behave in unintended ways, or produce harmful or misleading outputs","relation:misuse":"Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage","misuse_by:user":"Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage","misuse_by:third_party":"Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage"},"rev":null,"harm_quote":"the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information","status_quote":"we are, and may in the future become, subject to litigation alleging breach of contract and related claims arising from allegations regarding the use of user data in connection with AI training","reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-a60ac8ab58","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["4.2","2.2","4.3","7.2","2.1"],"primary":"4.2","status":"elsewhere","harm":["Economic/Property","Human or fundamental rights","Reputational"],"layers":["human_interaction"],"whose":["others","own","general"],"relation":["misuse"],"misuse_by":["third_party"],"subjects":[{"name":"customers","type":"Organization"}],"text":"Any security breach of our platform, our operational systems, physical facilities, or the systems of our third-party processors, or the perception that a breach has occurred, or other adverse impact to the availability, integrity, or confidentiality of such platform and systems, could result in litigation (including class actions), indemnity obligations, regulatory enforcement actions, investigations, compulsory audits, fines, penalties, mitigation and remediation costs, disputes, reputational harm, diversion of management’s attention, and other liabilities and damage to our business. We face evolving cybersecurity risks that threaten the confidentiality, integrity, and availability of our or our customers’ confidential or personal data and our and our third-party service providers’ information technology systems, which could result from human error, system misconfiguration, or from cyber-attacks, including distributed-denial-of-service attacks, reverse-engineering of AI algorithms, prompt injection attacks, automated reconnaissance, web scraping, ransomware attacks, business email compromises, credential stuffing, computer malware, viruses, and social engineering (including phishing, deepfakes, and voice cloning), software supply-chain compromises, including but not limited to via AI agents, templates, designs, icons, widgets, plugins, or other third party software or content, malicious code embedded in open-source software, or misconfigurations, “bugs” or other vulnerabilities in commercial software that is integrated into our and our third-party service providers’ information technology systems, products or services, which are prevalent in our industry. Recent advancements in AI have demonstrated the potential for AI systems to autonomously discover and exploit software vulnerabilities, including zero-day vulnerabilities, at speeds and scales that exceed previous human capability, which may materially accelerate the timeline and severity of potential attacks. These threats may come from a variety of sources, including nation-state sponsored espionage and hacking activities, corporate espionage, organized crime, sophisticated organizations, hacking groups and individuals, and insider threats. Any security breach or disruption could result in the loss or destruction of, or unauthorized access to, or use, alteration, disclosure, or acquisition of confidential or personal data, which may result in damage to our reputation, termination of customer contracts, litigation, regulatory investigations, or other liabilities. More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors. Any circumvention or failure of our cybersecurity defenses or measures could compromise the confidentiality or integrity of our customers’ data or other sensitive information.","ev":{"status":"More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors.","mit:4.2":"More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors.","mit:2.2":"reverse-engineering of AI algorithms, prompt injection attacks","mit:4.3":"social engineering (including phishing, deepfakes, and voice cloning)","mit:7.2":"Recent advancements in AI have demonstrated the potential for AI systems to autonomously discover and exploit software vulnerabilities, including zero-day vulnerabilities, at speeds and scales that exceed previous human capability","mit:2.1":"Any security breach or disruption could result in the loss or destruction of, or unauthorized access to, or use, alteration, disclosure, or acquisition of confidential or personal data","harm:Economic/Property":"litigation (including class actions), indemnity obligations, regulatory enforcement actions, investigations, compulsory audits, fines, penalties, mitigation and remediation costs","harm:Human or fundamental rights":"Any security breach or disruption could result in the loss or destruction of, or unauthorized access to, or use, alteration, disclosure, or acquisition of confidential or personal data","harm:Reputational":"damage to our reputation","layer:human_interaction":"More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors.","whose:others":"threaten the confidentiality, integrity, and availability of our or our customers’ confidential or personal data","whose:own":"threaten the confidentiality, integrity, and availability of our or our customers’ confidential or personal data","whose:general":"More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors.","relation:misuse":"More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors.","misuse_by:third_party":"More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors."},"rev":null,"harm_quote":"More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors.","status_quote":"More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors.","reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-7b2ad8a863","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["4.2","7.2","2.1"],"primary":"4.2","status":"elsewhere","harm":["Economic/Property","Human or fundamental rights"],"layers":["human_interaction"],"whose":["others","general"],"relation":["misuse"],"misuse_by":["third_party"],"subjects":[{"name":"customers","type":"Organization"}],"text":"Any of these outcomes could materially and adversely impact our business and financial condition. Techniques used to obtain unauthorized access or to sabotage systems change frequently, and the emergence of AI-driven offensive cyber capabilities may further compress the time between vulnerability discovery and exploitation. As a result, we may be unable to fully anticipate these techniques or to implement adequate preventative measures before they are exploited. Further, the incidence of state-supported and geopolitical-related cyberattacks may rise in connection with regional geopolitical conflicts which have increased the risk of cyberattacks on various types of infrastructure and operations. Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges. In addition, AI systems have demonstrated the capacity to discover and potentially exploit previously unknown software vulnerabilities across widely deployed operating systems, browsers, and other software on which our platform and infrastructure depend, which could expose us or our customers to attacks before patches or mitigations become available. As a result, we may be unable to detect, investigate, remediate, or recover from future attacks or incidents, or to avoid a material adverse impact to our information technology systems, confidential or personal data, or business.","ev":{"status":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","mit:4.2":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges.","mit:7.2":"AI systems have demonstrated the capacity to discover and potentially exploit previously unknown software vulnerabilities across widely deployed operating systems, browsers, and other software on which our platform and infrastructure depend","mit:2.1":"we may be unable to detect, investigate, remediate, or recover from future attacks or incidents, or to avoid a material adverse impact to our information technology systems, confidential or personal data, or business","harm:Economic/Property":"Any of these outcomes could materially and adversely impact our business and financial condition.","harm:Human or fundamental rights":"we may be unable to detect, investigate, remediate, or recover from future attacks or incidents, or to avoid a material adverse impact to our information technology systems, confidential or personal data, or business","layer:human_interaction":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges.","whose:others":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges.","whose:general":"which could expose us or our customers to attacks before patches or mitigations become available","relation:misuse":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges.","misuse_by:third_party":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges."},"rev":null,"harm_quote":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented cybersecurity challenges.","status_quote":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-63ba9ffe89","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Introduction of new technology, or upgrades and maintenance to our existing systems, could result in increased costs or unforeseen problems which may disrupt or reduce our operating efficacy. 75 We may also encounter service interruptions, outages, or disruptions due to issues interfacing with our customers’ information technology systems, including, but not limited to, stack misconfigurations or improper environment scaling, defective updates or upgrades, our customers’ inability to access the internet, the failure of our network or software systems, security breaches, variability in user traffic for our platform, or due to cybersecurity attacks on our or our customers’ information technology systems. For example, if our cloud hosting provider or the hosting provider of any of our third-party technology partners, including AI partners, were to experience interruptions, delays, outages, or other service interruptions, including as a result of customer demand, that may impact our ability to provide service to our customers. We may be required to issue credits or refunds or otherwise be liable to our customers for damages they may incur resulting from certain of these events.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-11d38d8bc7","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Our business, operating results, and financial condition would be adversely affected if we suffer performance issues or downtime that fails to meet the service level commitments under our agreements with our customers. Our AI credit, usage-based, and rate-limiting systems may also contain defects, errors, or ambiguities, including with respect to usage attribution, balance calculations, limit enforcement, refresh timing, pooled allocations, invoices, or customer-facing reporting. If these systems fail to operate as intended, customers may be overcharged or undercharged, unexpectedly lose access, consume credits in connection with failed or interrupted outputs, or be unable to understand or verify usage, which could result in credits, refunds, disputes, litigation, regulatory scrutiny, and reputational harm.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-d04c0e88bb","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"We rely on third-party service providers for critical components of our operations, and disruptions or changes in those services could adversely affect our business. In addition to AWS, we also depend on other third-party providers for services that are critical to the operation of our platform and business, including content delivery, identity and access management, payment processing, analytics and monitoring, and certain AI-related services. In particular, we have significant purchase commitments with a limited number of foundational AI model providers and a material portion of our AI features currently depend on models from them. Any of these third-party providers may experience outages, capacity constraints, cybersecurity incidents, business interruptions, or financial distress, or may change pricing, service levels, security or compliance requirements, or contractual terms. If any such provider fails to perform as expected, if our access is limited or terminated, or if we are required to transition to alternative providers on short notice, we could experience service degradation or outages, delayed product development, increased costs, billing and collections disruption, and customer dissatisfaction, any of which could adversely affect our business, operating results, and financial condition. Additionally, certain customers may require us to restrict or replace the use of specific third-party AI models in order to continue using our platform, which could increase our costs, delay product rollouts, or reduce our ability to serve such customers. Customer requirements to substitute or exclude specific third- 78 party AI models may arise from regulatory or contractual obligations applicable to our customers, government supply-chain or sanctions actions affecting model providers, or evolving customer policies, and may require us to develop, maintain, and operate redundant model integrations or alternative routing arrangements. We may not be able to implement such substitutions on terms that are commercially reasonable, on the timelines our customers require, or while maintaining feature parity, and any inability to do so could result in lost or curtailed sales, customer dissatisfaction, increased costs, or reputational harm.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-88206bfe56","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"selling to governmental entities and highly regulated organizations can be highly competitive, expensive, and time consuming, often requiring significant upfront time and expense without any assurance that such efforts will generate a sale; government certification, software supply chain or cybersecurity requirements applicable to us or our platform may change and, in doing so, restrict our ability to sell into the governmental sector and to highly regulated organizations until we have attained the revised certification or meet other new requirements (for example, although we are currently FedRAMP authorized, such authorization is costly to maintain and subject to rigorous compliance and if we lose our authorization, it will restrict our ability to sell to government entities; further, the U.S. federal government recently identified Anthropic PBC (“Anthropic”) as a supply chain risk and directed all federal agencies to cease use of Anthropic’s products, including Claude, the large language model on which we have built the AI features embedded in our governmental offerings, and, although the implementation of this directive has been the subject of ongoing litigation and may be modified, stayed, or invalidated, if a government-wide ban of Anthropic is upheld and we are unable to find a suitable replacement on a timely basis, on competitive terms, or at all, our sales to governmental entities and highly regulated organizations could suffer); government entity demand and payment for our platform may be impacted by public sector budgetary cycles and funding authorizations, with funding reductions or delays adversely affecting public sector demand for our platform, including, but not limited to, as a result of sudden, unforeseen, and disruptive events such as geopolitical instability, warfare, and uncertainty, incidents of terrorism, natural disasters, public health concerns or epidemics, governmental defaults on indebtedness, governmental shutdowns, inflation, changes in interest rates, changes in investment and spending environments, and reductions in the government workforce, which may limit or delay governmental entity spending on our platform and adversely affect our revenue;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-feed97ac76","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Our competitors also may be successful in recruiting and hiring members of our management team, sales team, research and development team, or other key employees, and it may be difficult for us to find suitable replacements on a timely basis, on competitive terms, or at all. For example, we have experienced, and may continue to experience, attrition of product, design, engineering, and other key personnel to companies developing foundational AI models and AI-native products, including companies that are also our commercial partners or third-party model providers, and any prolonged attrition of key product, design, engineering, or other key talent could delay our AI roadmap and impair our competitive position. We have in the past, and may in the future, be subject to allegations that employees we hire have been improperly solicited, or that they have divulged proprietary or other confidential information, or that their former employers own such employees’ inventions or other work product, or that they have been hired in violation of non-compete provisions or non-solicitation provisions.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209","0001628280-26-053348"],"forms":{"10-Q":2},"first":"2026-05-14","last":"2026-08-05","end":null},{"id":"1579878-672132ffaf","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Moreover, we may need to expend additional resources to defend our intellectual property rights in foreign countries, and our inability to do so could impair our business or adversely affect our international expansion. Furthermore, the application of intellectual property law to AI technologies is a new and emerging practice, and there is uncertainty and ongoing litigation in different jurisdictions as to the degree and extent of protection warranted for AI and machine learning systems and relevant system input and outputs. The law is also uncertain across jurisdictions regarding the copyright ownership of content that is produced in whole or in part by AI tools. As a result, our use of AI tools in our product development and engineering processes may make it difficult to assert ownership rights over our technology. If we fail to obtain protection for the intellectual property rights concerning our AI technologies, or later have our intellectual property rights invalidated or otherwise diminished, our competitors may be able to take advantage of our research and development efforts to develop competing products which could adversely affect our business, reputation, and financial condition. In addition, given the long history of development of AI technologies, other parties may have, or in the future may obtain, patents or other proprietary rights that could prevent, limit, or interfere with our ability to make, use, or sell our own AI technologies. Third parties have claimed and may claim that our platform infringes, misappropriates, or otherwise violates their intellectual property rights and such claims could be time-consuming or costly to defend or settle, result in the loss of significant rights, or harm our relationships with our customers or reputation in the industry.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209","0001628280-26-053348"],"forms":{"10-Q":2},"first":"2026-05-14","last":"2026-08-05","end":null},{"id":"1579878-5eb87a367b","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["6.3","7.3","2.2"],"primary":"6.3","status":"elsewhere","harm":["Economic/Property"],"layers":["capability"],"whose":["own","general"],"relation":["within_purpose","misuse"],"misuse_by":["third_party"],"subjects":[],"text":"A loss of key personnel or their work product could hamper or prevent our ability to develop, market, and support potential products or enhancements, which could severely harm our business. Further, we may use AI technologies, including tools provided by third parties, to develop or assist in the development of our own software code. While use of such tools makes our development process more efficient, AI technologies have sometimes generated content that is “substantially similar” to proprietary or open source software code on which the AI tool was trained. If the AI technologies we use generate code that is too similar to other proprietary code, or to software processes that are protected by patents, we could be subject to intellectual property infringement claims. AI-generated code or other outputs may also introduce security vulnerabilities, compliance failures (including accessibility), or license obligations (including open source notices or attribution requirements). We may not be able to anticipate and detect security vulnerabilities in AI-generated software code, including those that could be induced by a maliciously trained AI model. If our tools generate code that is too similar to open source code, we risk losing protection of our own proprietary code that is commingled with such code. Finally, to the extent we use third-party AI technologies to develop software code, the terms of use of these tools may state that the third-party provider retains rights in the generated code. We may also face similar risks in using AI technologies to develop or assist in the development of other materials, such as advertising or marketing materials. Any intellectual property claims, whether with or without merit, could be very time-consuming, could be expensive to settle or litigate, and could divert our management’s attention and other resources, even if such claims do not result in litigation or are resolved in our favor.","ev":{"status":"AI technologies have sometimes generated content that is “substantially similar” to proprietary or open source software code on which the AI tool was trained.","mit:6.3":"If the AI technologies we use generate code that is too similar to other proprietary code, or to software processes that are protected by patents, we could be subject to intellectual property infringement claims.","harm:Economic/Property":"If the AI technologies we use generate code that is too similar to other proprietary code, or to software processes that are protected by patents, we could be subject to intellectual property infringement claims.","layer:capability":"If the AI technologies we use generate code that is too similar to other proprietary code, or to software processes that are protected by patents, we could be subject to intellectual property infringement claims.","mit:7.3":"AI-generated code or other outputs may also introduce security vulnerabilities, compliance failures (including accessibility), or license obligations","mit:2.2":"security vulnerabilities in AI-generated software code, including those that could be induced by a maliciously trained AI model","relation:misuse":"security vulnerabilities in AI-generated software code, including those that could be induced by a maliciously trained AI model","misuse_by:third_party":"security vulnerabilities in AI-generated software code, including those that could be induced by a maliciously trained AI model","whose:own":"we may use AI technologies, including tools provided by third parties, to develop or assist in the development of our own software code","relation:within_purpose":"we may use AI technologies, including tools provided by third parties, to develop or assist in the development of our own software code","whose:general":"AI technologies have sometimes generated content that is “substantially similar” to proprietary or open source software code on which the AI tool was trained"},"rev":null,"harm_quote":"If the AI technologies we use generate code that is too similar to other proprietary code, or to software processes that are protected by patents, we could be subject to intellectual property infringement claims.","status_quote":"AI technologies have sometimes generated content that is “substantially similar” to proprietary or open source software code on which the AI tool was trained.","reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-52e4f4dde6","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Any impairment of the technologies of or our relationship with these third parties could harm our business, operating results, and financial condition. 93 Risks Related to Legal and Regulatory Matters Our business is subject to complex and evolving U.S. and foreign laws, regulations, and industry standards, many of which are subject to change and uncertain interpretations, which uncertainty could harm our business, operating results, and financial condition. We are subject to many U.S. and foreign federal, state, and local laws, regulations, and industry standards that involve matters central to our business, including laws and regulations that involve data privacy, data security, intellectual property, including copyright and patent laws, AI technologies, antitrust and competition, online safety and moderation, employment, labor, immigration, consumer protection, public health, workplace safety, and taxation. These laws and regulations are constantly evolving and may be interpreted, applied, created, or amended, in a manner that could harm our business.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-7070a494ec","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Certain of our employees outside of the United States are, and an increasing number may in the future be, subject to mandatory works council, employee representation, or collective bargaining arrangements in accordance with local laws or sector-wide collective agreements, including in jurisdictions where we have established or are establishing direct employment relationships in place of professional employer organization arrangements. These challenges are accentuated by the use and proliferation of emerging technologies within our business, including AI-related technologies, the regulation of which is becoming increasingly complex, including with respect to labor laws and hiring 94 practices. Compliance with such laws, regulations, and policies may require significant investment and expense.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-be9113a7ea","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"We do not currently have any specific plans to issue shares of our capital stock in the form of blockchain tokens. The trading prices of the common stock of technology companies have been highly volatile in recent years as a result of factors including inflation, interest rate volatility, actual or perceived global banking and finance related issues, geopolitical instability, warfare, macroeconomic uncertainty, including uncertainty regarding the impact of AI on software-as-a-service business models, and market downturns, which may reduce our ability to access capital on favorable terms or at all. In addition, a recession, depression, or other sustained adverse market event could adversely affect our business and the value of our Class A common stock.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209","0001628280-26-053348"],"forms":{"10-Q":2},"first":"2026-05-14","last":"2026-08-05","end":null},{"id":"1579878-3758fc502f","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"For example, our Class A common stock has traded as high as $124.63 104 per share on the first day of trading following our IPO and, during the three months ended March 31, 2026, traded as low as $20.16 per share. The trading price of our Class A common stock may continue to be volatile and decline further, including for reasons unrelated to our operating performance, such as valuation compression due to investor sentiment regarding software, AI, or obsolescence risk. You may not be able to resell your shares at or above the price you paid for them, and could lose all or part of your investment in our Class A common stock.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035209"],"forms":{"10-Q":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-607fc5528f","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"retain and increase adoption of our products and services by existing customers, as well as attract new customers and grow our customer base; develop new offerings and functionality for our platform and successfully optimize our existing products and services, including through the integration of AI into our platform; successfully expand our business domestically and internationally;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-6eed918b9d","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"If we fail to properly manage technical debt, our platform performance may suffer, we may face increased downtime, and our business, operating results, and financial condition could be harmed. Additionally, as we further integrate AI capabilities and expand our product offerings, technical complexity has and may 55 continue to increase, potentially exacerbating these challenges. To manage any future growth effectively, we must continue to improve and expand our infrastructure, including information technology and financial infrastructure, our operating and administrative systems and controls, and our ability to manage headcount, capital, and processes in an efficient manner.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-1372b4b758","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"For example, we introduced FigJam in 2021, Dev Mode in 2023, Figma Slides in 2024, Figma Sites, Figma Make, Figma Buzz, Figma Draw, and Figma Weave in 2025. Over the last few years we have integrated generative AI and code-related capabilities across our platform, including through AI-powered design generation, agentic workflows, and native code layers. In addition, in March 2025, we implemented significant changes to our pricing, packaging, and billing models. In 2025, we introduced AI credits across all Figma seats. Starting in March 2026, we began enforcing AI credit limits and introduced flexible options for incremental usage, including monthly AI credit add‑ons to existing subscriptions or usage billed under a pay‑as‑you‑go model. Accordingly, we have a limited operating history at our current scale of business, and with our current product offerings and pricing, packaging, and billing models, which makes it difficult to evaluate our current business, future prospects, and other trends.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-a16f4e5397","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["4.3"],"primary":"4.3","status":"hypothetical","harm":["Economic/Property"],"layers":["human_interaction"],"whose":["others"],"relation":["misuse"],"misuse_by":["user","third_party"],"subjects":[],"text":"We made these 58 changes to keep pace with our expanded offerings and features since our platform’s launch and to provide our customers with more visibility and upfront controls. In 2025, we also introduced AI credits across all Figma seats. Starting in March 2026, we began enforcing AI credit limits and introduced flexible options for incremental usage, including monthly AI credit add‑ons to existing subscriptions or usage billed under a pay‑as‑you‑go model. We may become unable to attract new customers and retain existing customers at the same price or based on the same seat-based subscription model that we have used historically. We may from time to time decide to make further changes to our billing models due to a variety of reasons, including, but not limited to, changes to the markets for our products and services, increased use of AI in the software industry generally, increased implementation and use of AI features in our products, pricing pressures, and the introduction of new products and services by us or by our competitors. If we are unable to implement changes to our billing models in a timely manner or at all, including as a result of delays associated with our billing infrastructure or product development processes, our business, operating results, and financial condition could be negatively impacted. Our new pricing, packaging, and billing models may not accurately reflect the optimal pricing, packaging, and billing models necessary to attract new customers and retain existing customers, which may make it difficult to accurately plan and forecast our operating results. Furthermore, the changes to our pricing and packaging plans introduced in March 2025 and the enforcement of AI credit limits beginning in March 2026 have made, and any further changes to components of our pricing, packaging, and billing models that we may introduce in the future may make, forecasting our operating results more difficult and result in comparisons to periods prior to the updates being less meaningful as some of the drivers underlying our business model will have changed. In addition, we may offer, or customers may demand, options that change who bears the cost of AI usage or how AI usage is provisioned, including by allowing customers to use their own third-party AI credentials or accounts (for example, bring-your-own-key arrangements), which may reduce the amount of AI usage that is metered through our AI credit programs. Such arrangements may increase certain costs (including, but not limited to, costs relating to engineering, infrastructure, security, compliance, and support), impact our margins, materially change the amount, mix, and timing of our revenue, and make our operating results harder to forecast. The net impact of any such arrangements on our revenue, margins, and cash flows may be difficult to predict and may vary across customers, products, and periods. Any such arrangements could also reduce our ability to meter, price, and control AI usage, and increase billing complexity, support burdens, and disputes. Our ability to increase or maintain our prices may be constrained by competitive dynamics, customer expectations or pressure to provide discounts, or economic conditions. Pricing pressure may require us to reduce the price we charge our customers for usage of our AI products and features, absorb additional costs, or operate certain AI features at lower or negative gross margins for extended periods in order to remain competitive. Moreover, competitive dynamics may result in customers expecting full AI functionality to be included in baseline subscription pricing, which may lead customers to curtail their use of our products and features subject to AI credit pricing, including Figma Make and other AI features, or to stop using those products and features altogether, and may limit our ability to monetize the usage of our AI products and features in a manner that offsets associated costs. In addition, the unit economics of AI products and features may be volatile and difficult to predict, including due to changes in third-party model pricing, infrastructure costs, usage patterns, and the rate at which customers adopt AI-powered workflows. If we are unable to increase prices to offset rising costs, including costs related to AI inference or otherwise related to providing AI features, or to otherwise update our pricing model, including to better align it with the increased integration of AI into our platform, or if price increases or other changes to our pricing model significantly reduce customer demand, our business, operating results, and financial condition could be negatively impacted. 59 Further, as AI and its integration into software becomes more prevalent and its use cases become more sophisticated, including with respect to our products and the products of our competitors, there could be a decrease in the number of designers, developers, and other collaborators that use our platform if such individuals are able to significantly increase their efficiency through the use of AI capabilities alongside or instead of our platform or if our customers or potential customers reduce the size of their product development, design, and engineering workforces in response to the perceived or actual capabilities of AI to perform work previously completed by human designers, developers, and other collaborators. Such a decrease could reduce the number of seats that customers or potential customers subscribe to, which could lead to a loss of revenue, slower growth, and adversely impact our business, operating results, and financial condition. Our seat-based subscription model may become less aligned with customer value creation as AI automates or consolidates work that historically required multiple users. In response to any industry changes resulting from AI, we may need to make further changes to our pricing, packaging, and billing practices, including potential changes to our seat-based subscription model or to the way we offer and charge for our AI products and features. If we are unable to adapt our pricing and packaging models quickly and effectively, our revenue growth, margins, business, operating results, and financial condition could be negatively impacted. Changes to our pricing, packaging, and billing models, including the changes to our pricing and packaging plans introduced in March 2025 and the enforcement of AI credit limits starting in March 2026, and any further changes that we make in the future, may, among other things, result in customer dissatisfaction, lead to a loss of customers, result in customers curtailing or stopping their usage of our products and features subject to AI credit pricing, including Figma Make and other AI features, harm our brand, and negatively impact our business, operating results, and financial condition. For example, following our enforcement of AI credit limits starting in March 2026, we observed elevated customer support volume, instances of customer dissatisfaction expressed through public and social channels, and reduced usage by certain customers. While we are continuing to evaluate the longer-term impact, we may experience further dissatisfaction, dispute resolution costs, or customer churn in the future. Third-party AI agents and tools that operate on or through our platform may circumvent our pricing and packaging models, increase our costs, and adversely affect our business, operating results, financial condition, and future prospects. In March 2026, we introduced the ability for third-party AI agents to create and modify real design assets directly in Figma files through our MCP server. Customers may also use, or third parties may develop, tools that automate or orchestrate workflows on our platform (including through browser extensions, plugins, scripts, bots, or other third-party tools). The introduction of AI agents or other third-party tools on our platform could reduce the number of paid seats required for a given level of output, circumvent or undermine our intended pricing and packaging controls, increase platform load, or create fraud and abuse risk. If we are unable to detect and effectively monetize such activity, or if we restrict or limit such tools and customers react negatively, our revenue, margins, growth, and reputation could be adversely affected.","ev":{"mit:4.3":"create fraud and abuse risk","harm:Economic/Property":"circumvent or undermine our intended pricing and packaging controls, increase platform load, or create fraud and abuse risk","layer:human_interaction":"Third-party AI agents and tools that operate on or through our platform may circumvent our pricing and packaging models","whose:others":"Third-party AI agents and tools that operate on or through our platform","relation:misuse":"Third-party AI agents and tools that operate on or through our platform may circumvent our pricing and packaging models","misuse_by:user":"Customers may also use, or third parties may develop, tools that automate or orchestrate workflows on our platform","misuse_by:third_party":"Customers may also use, or third parties may develop, tools that automate or orchestrate workflows on our platform"},"rev":null,"harm_quote":"create fraud and abuse risk","status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-fc31f4dca5","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Any such approach may also increase complexity for our customers and our sales, finance, and support teams, may create disagreement over whether such usage should be charged to a customer, a third-party agent provider, or a third-party model provider, may not align with customer expectations, and may not generate the revenue or margins we expect. In addition, third parties have introduced, and we expect they will continue to develop, browser-based, operating-system-based, and other autonomous AI agents that operate software platforms, including 60 ours, on a user’s behalf, including agents offered by providers whose models we license or with which we otherwise integrate. Because these external agents typically interact with our platform using a single user’s authenticated session, our seat-based pricing, billing, administrative controls, monitoring, and terms of service may be less effective at identifying agent activity, attributing usage to the appropriate party, detecting automation, or determining when additional seats, credits, or charges should apply. As external AI agents become more capable, customers may use them to perform tasks that would otherwise require additional users, seats, or activity on our platform, which could reduce demand for paid seats, accelerate seat-replacement dynamics, or shift workflows away from our user interface and toward third-party agent interfaces, any of which could erode the perceived value or differentiation of our platform. We may need to invest in new identification, attribution, authentication, governance, and pricing mechanisms, and we may face conflicting demands from customers, including enterprise customers seeking to restrict agent activity for governance, security, or compliance reasons and other customers seeking to permit or expand agent activity. We may not be able to address these demands in a timely or commercially reasonable manner, and our decisions to permit, restrict, monetize, or otherwise govern external agent activity, or any technical or contractual measures we adopt or fail to adopt, could result in customer dissatisfaction, contractual or regulatory disputes (including with the operators of such agents), reduced adoption of our platform, or reputational harm. The legal and regulatory framework applicable to external AI agents, including with respect to terms-of-service enforceability, liability for content generated through agent activity, and competition and platform-access requirements, is unsettled and evolving, and adverse developments could increase our costs, limit our ability to control agent activity on our platform, or otherwise adversely affect our business, operating results, and financial condition. If we are unable to accurately measure, attribute, and bill for usage under credit-based, usage-based, or outcome-based billing models, or to provide sufficient transparency and controls over such usage, our business, operating results, financial condition, and future prospects could be adversely affected. Over time, we expect to introduce products, features, and services, or to otherwise implement pricing and packaging models, that are billed differently than on a per-seat subscription basis. For example, in 2025, we introduced AI credits across all Figma seats. Starting in March 2026, we began enforcing AI credit limits and introduced flexible options for incremental usage, including monthly AI credit add‑ons to existing subscriptions or usage billed under a pay‑as‑you‑go model. Credit-based, usage-based, or outcome-based billing models increase the complexity of accurately measuring and charging for product usage, and may increase the risk of billing disputes, reduced collectibility, refunds, chargebacks, and regulatory scrutiny. As we begin enforcing AI credit limits and have introduced flexible options for incremental usage, including monthly AI credit add‑ons to existing subscriptions or usage billed under a pay‑as‑you‑go model, we expect that the mechanisms by which we meter, attribute, and report usage will become more complex. Customer trust in these models may depend in part on our ability to provide clear, accurate, and timely visibility into usage, balances, limits, overages, and applicable charges.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-d5dad8d359","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Any of the foregoing could adversely affect our business, operating results, financial condition, and future prospects. In particular, customers may react negatively if AI credits are consumed in connection with failed, unstable, or interrupted outputs or if administrators cannot readily determine what users, files, prompts, models, or workflows are driving usage. If we are unable to provide sufficient visibility, controls, alerts, or remediation in such circumstances, customers may perceive our billing as unfair, reduce usage, seek credits or refunds, delay deployments, or consider alternative products, any of which could adversely affect our business, operating results, financial condition, and future prospects. Further, adoption of AI products and features by larger organizations may depend on our ability to provide enterprise-grade administrative controls, permissioning, governance, transparency, and policy management. Some of our enterprise customers and prospective enterprise customers require the ability to control which users, groups, teams, or business units can access AI features, which models can be used, how usage is allocated or pooled, how spending is capped or approved, and how outputs and prompts are governed for compliance or security purposes. If we do not provide such controls in a timely manner, or if customers or prospective customers determine that our controls are inadequate for their governance, compliance, procurement, or budgeting requirements, they may delay deployment, limit purchases, reduce usage, or choose competitive offerings, which could adversely affect our business, operating results, financial condition, and future prospects.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-eac92a7385","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["6.2"],"primary":"6.2","status":"elsewhere","harm":["Economic/Property"],"layers":["systemic"],"whose":["general"],"relation":["within_purpose"],"misuse_by":[],"subjects":[{"name":"human designers, developers, and other collaborators","type":"Group of persons"}],"text":"Customers have no obligation to renew a subscription after the expiration of the contract term, and customers may not renew their subscriptions with a similar contract period, with the same or greater number of seats, for the same subscription plan, or at all. In addition, starting in March 2026, we began enforcing AI credit limits and introduced flexible options for incremental usage, including monthly AI credit add‑ons to existing subscriptions or usage billed under a pay‑as‑you‑go model. Customers are under no obligation to purchase monthly AI credit add‑ons to their existing subscriptions or 62 AI usage under the pay‑as‑you‑go billing model, and they may curtail or stop their usage of our AI-powered products and features at any time. If our customers do not renew their subscriptions or if they renew on terms less favorable to us, or if our customers curtail or stop their usage of our AI-powered products and features in light of our AI credit billing model, our business, operating results, financial condition, and future prospects may be adversely impacted. Our customer retention may decline or fluctuate as a result of various factors, including, but not limited to, their satisfaction with our platform, products, and services and satisfaction with those offered by competitors, our pricing, packaging, and billing models and changes to such models, including our recent and any future pricing changes, broader industry trends, including reductions in the size of product development, design, and engineering workforces driven in response to the perceived or actual capabilities of AI to perform work previously completed by human designers, developers, and other collaborators, and the effects of general economic conditions and uncertainty in financial markets. Further, our future success depends, in part, on our ability to convert users of our free plan into paying customers on a paid pricing plan and selling additional offerings, including monthly AI credit add‑ons to customers’ existing subscriptions or AI usage under the pay‑as‑you‑go billing model, to existing paying customers. This may require us to incur increased sales and marketing expenses, but it may not result in additional sales.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-eabb65f0bd","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"If we are unable to successfully develop new products, enhance our existing products to meet customer requirements, or otherwise achieve market adoption, our business, operating results, and financial condition would be harmed. We have made significant investments to develop, launch, and enhance new products and services, such as FigJam in 2021, Dev Mode in 2023, Figma Slides in 2024, and Figma Sites, Figma Make, Figma Buzz, Figma Draw, and Figma Weave in 2025, and to integrate generative AI and code-related capabilities across our platform, including through AI-powered design generation, agentic workflows, and native code layers. We intend to continue investing significant resources to develop and launch new products, services, features, and functionality, including enhancements to our platform’s accessibility.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-4de7d8059f","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["4.3","2.1","6.3","4.2","3.1"],"primary":"4.3","status":"hypothetical","harm":["Economic/Property","Human or fundamental rights","Public interest","Reputational"],"layers":["human_interaction","systemic"],"whose":["own","general"],"relation":["within_purpose","misuse"],"misuse_by":["third_party"],"subjects":[],"text":"For example, we have offered, and expect to continue offering, certain new products and features in beta form, in some cases at no charge to our customers. We may incur substantial costs, including in connection with AI inference and AI-inference 64 related fraud and abuse, infrastructure, and support, in connection with our offerings before, or without ever, generating offsetting revenue from them. It is also possible that products and services developed by others, including, but not limited to, new technologies integrating AI, or products and services developed by competitors that employ a credit-based, usage-based, or outcome-based pricing model, will render our platform and offerings uncompetitive or obsolete. Further, our development efforts with respect to new technologies, offerings, features, and functionality could distract management from current operations, and would divert capital and other resources from our more established offerings. If we do not realize the expected benefits of our investments, our business, operating results, financial condition, and future prospects could be adversely affected. Competitive developments in AI and our inability to effectively respond to such developments could adversely affect our business, operating results, and financial condition. Developments in AI are already impacting the software industry significantly, and we expect this impact to be even greater in the future. AI has become more prevalent in the markets in which we operate and may result in significant changes in the demand for our platform, including, but not limited to, reducing the difficulty and cost for competitors to build and launch competitive products, altering how consumers and businesses interact with websites and apps and consume content in ways that may result in a reduction in the overall value of interface design, or by otherwise making aspects of our platform obsolete or decreasing the number of designers, developers, and other collaborators that utilize our platform. Any of these changes could, in turn, lead to a loss of revenue and adversely impact our business, operating results, and financial condition. While we have made, and expect to continue to make, significant investments to integrate AI, including generative AI, into our platform, AI technologies are rapidly evolving and there can be no guarantee that our products will remain competitive as new AI technologies are developed, adopted, and integrated into software solutions. We expect that ongoing, and likely increasing, investment will be required over time to continuously improve our use of AI technologies. As with many technological innovations, there are significant risks involved in developing, maintaining, and deploying AI. There can be no assurance that the integration of such technologies will enhance our products or services or be beneficial to our business, including, but not limited to, with respect to our efficiency or profitability. Similarly, we cannot guarantee that our investments in the development and integration of AI will be successful or provide an adequate return, including, without limitation, with respect to the amount of time, focus, and staffing directed towards these efforts. Our announced or perceived AI roadmap and product strategy may create heightened expectations among customers and investors, and if we fail to meet those expectations, our business, operating results, financial condition, and future prospects could be adversely affected. As AI models and tooling improve, customers may increasingly expect higher quality outputs, faster iteration cycles, greater reliability, and more seamless end-to-end workflows from design and development platforms. More capable general-purpose AI models released by major providers are or may soon become widely accessible, and if we do not keep pace with rising expectations, customers may reduce usage, delay or forgo purchases, or switch to competing products. In addition, customer expectations regarding the speed, availability, and performance of AI features may increase over time, which could require us to incur higher infrastructure and model costs that we may not be able to recover through pricing. Our ability to keep pace with these expectations may depend on our continued access to advanced third-party AI models and sufficient inference capacity, including from a limited number of foundational model providers. If we are unable to secure or maintain such access on commercially reasonable terms, or if such providers impose usage restrictions, experience outages, or face capacity constraints, our AI features may be delayed, degraded, or unavailable, which could adversely affect our business, operating results, and financial condition. 65 Our AI products and features depend on a limited number of third-party model providers or other AI technology partners that may at the same time offer competing products, seek to intermediate end-user relationships directly, influence customer preferences through their own platforms or marketplaces, or otherwise reduce the differentiated value of software companies that build on top of their models. If such providers limit our access, change economic terms, prioritize their own products or strategic partners, or otherwise reduce our ability to differentiate or monetize our offerings, our business, operating results, and financial condition could be adversely affected. Certain third-party model providers, AI platforms, and agent ecosystems may increasingly control user identity, authentication, tool selection, billing relationships, discovery, or workflow routing for activities that incorporate our products or services. If users are encouraged or enabled to access our products or services through such providers’ subscriptions, token systems, marketplaces, or agent frameworks, our ability to control distribution, customer relationships, pricing, and monetization may be reduced. Such providers may also influence which tools agents use, how usage is attributed, and which party bears the cost of inference or other activity, which could increase pricing pressure, reduce our margins, or otherwise adversely affect our business, operating results, and financial condition. Competition in AI-enabled products and workflows may be especially intense with respect to pricing and margins. Certain competitors, including larger platform providers, model providers, AI-native companies, or well-capitalized startups, offer competing AI-powered functionality at very low prices, bundle such functionality into broader offerings, subsidize usage for extended periods, or operate at margins that are lower than those historically associated with our core software products. Such practices may condition customers to expect AI functionality to be included at low or no incremental cost and may make it difficult for us to price our AI products and features, including more AI-native or media-intensive offerings, in a manner that offsets inference, model access, hosting, support, safety, and other associated costs. These risks may be more pronounced for certain newer offerings or workflows that rely more heavily on third-party model usage or that have materially different cost structures than our more established products. If we are unable to compete effectively in this environment or if the economics of our AI products and features are less favorable than those of our historical offerings, our revenue growth, gross margins, operating margins, and financial condition could be adversely affected. Further, our competitors may incorporate AI into their products more quickly or more successfully than we do, which would impair our ability to compete effectively. Decisions as to whether and how to integrate various AI technologies are difficult and we may choose not to adopt certain technologies or take advantage of certain data sets available to us as a result of ethical, legal, regulatory, or reputational concerns, which could put us at a competitive disadvantage and harm our business, operating results, and financial condition. For example, we, or our customers, may choose, or be required, not to use some high-performing or low-cost open-source models due to security, compliance, export control, sanctions, procurement, or reputational considerations. If our competitors use such models and no comparable alternative is available, we could be at a competitive disadvantage and our business, operating results, and financial condition may be harmed as a result. In the future, we may seek to co-train or otherwise customize AI models with third parties or using additional datasets. Efforts to co-train, fine-tune, or otherwise customize AI models may also require significant expenditures on compute, data preparation, evaluation, experimentation, infrastructure, and personnel, and such efforts may need to be repeated as base models, model providers, customer expectations, or legal and regulatory requirements evolve. These efforts may be costly, may not result in durable performance improvements, may become obsolete more quickly than anticipated, may require us to share or process additional data with third parties or in new environments, and could increase risks related to data rights, privacy, security, confidentiality, intellectual property, regulatory compliance, and partner dependency, any of which could adversely affect our business and reputation. 66 AI technologies are rapidly changing how digital products and experiences are being designed, prototyped, and built. These shifts may be unpredictable and could include new interaction paradigms, devices, or form factors (such as through AI agents or assistants, conversational or voice-driven workflows, mixed reality or other new form factors, AI agent collaboration, or experiences delivered through operating systems or a small number of ecosystems). This may change how people access and interact with digital products in ways that reduce reliance on traditional software applications, websites, and graphical user interfaces. For example, in an interaction paradigm in which AI agents collaborate with other agents or transact directly with digital services on behalf of users, customers may shift workflows away from traditional user interfaces and toward alternative agent-mediated environments. This could also reduce the amount of traditional interface design, prototyping, and front-end development work that organizations choose to perform or maintain, or cause our customers to shift the performance of certain tasks or workflows into other environments or toolchains outside our platform. For example: customers may consolidate purchasing decisions around vendors that bundle AI capabilities across broader software suites or purchase from other vendors that provide end-to-end “design-to-code” or “prompt-to-product” experiences; organizations may reduce the number of designers, developers, or collaborators required to deliver products, which may lead to them reducing the number of seats purchased or renewed even if output increases; customers may shift preferences from per-seat subscriptions to credit-based, usage-based, or outcome-based billing models, which may increase pricing pressure, reduce predictability of revenue, and adversely affect our margins; and switching costs may decline as AI tools improve interoperability, automated conversion of files, or automated recreation of design systems across platforms. If these changes reduce demand for our platform or disrupt our monetization model, this could adversely affect our business, operating results, and financial condition. Our failure to successfully develop, commercialize, or effectively monetize our products or services involving AI technologies could impact the price of our Class A common stock and impair our ability to raise capital, expand our business, improve and diversify our product offerings, efficiently manage our operating expenses, and respond effectively to competitive developments. Moreover, the use of AI technologies and our investments to integrate AI into our platform may adversely impact our business, operating results, and financial condition. For example, in the short term, we expect that our AI investments and use of AI technologies, including as part of Figma Make and our other AI features, will negatively impact our gross margins and operating margins and, given the newness of and rapid development of these technologies, the impacts on our gross margins and operating margins, and on our business, operating results, financial condition, and future prospects over the longer term, are currently unknown. More generally, advances in AI could be transformative and may occur more rapidly than anticipated. The development of highly capable general-purpose or autonomous AI systems, including the potential emergence of artificial general intelligence or superintelligence, could lead to significant economic, societal, political, and geopolitical disruption. Such disruption could reduce demand for our products, change how organizations staff and budget for design and product development, and increase volatility in customer spending. It could also prompt governments to adopt emergency measures or sweeping new regulations, restrictions, or moratoria on the development, deployment, or use of advanced AI systems, or to regulate access to compute, chips, energy, or cloud infrastructure, any of which could increase our costs, delay or limit our ability to offer AI features, or require us to materially modify our products, business model, or operations. In addition, serious harms attributed to advanced AI systems, including 67 widespread fraud, cyberattacks, misinformation, automated reconnaissance, or other safety incidents, could increase litigation risk and reputational harm for companies offering AI-enabled products, even where such harms are caused by third parties or are outside our control. Any of the foregoing could adversely affect our business, operating results, and financial condition.","ev":{"mit:4.3":"AI-inference 64 related fraud and abuse","mit:2.1":"could increase risks related to data rights, privacy, security, confidentiality, intellectual property, regulatory compliance, and partner dependency","mit:6.3":"could increase risks related to data rights, privacy, security, confidentiality, intellectual property, regulatory compliance, and partner dependency","mit:4.2":"serious harms attributed to advanced AI systems, including 67 widespread fraud, cyberattacks, misinformation, automated reconnaissance, or other safety incidents","mit:3.1":"serious harms attributed to advanced AI systems, including 67 widespread fraud, cyberattacks, misinformation, automated reconnaissance, or other safety incidents","harm:Economic/Property":"Any of these changes could, in turn, lead to a loss of revenue and adversely impact our business, operating results, and financial condition.","harm:Human or fundamental rights":"could increase risks related to data rights, privacy, security, confidentiality, intellectual property, regulatory compliance, and partner dependency","harm:Public interest":"could lead to significant economic, societal, political, and geopolitical disruption","harm:Reputational":"could increase litigation risk and reputational harm for companies offering AI-enabled products, even where such harms are caused by third parties or are outside our control","layer:human_interaction":"serious harms attributed to advanced AI systems, including 67 widespread fraud, cyberattacks, misinformation, automated reconnaissance, or other safety incidents, could increase litigation risk and reputational harm for companies offering AI-enabled products, even where such harms are caused by third parties or are outside our control","layer:systemic":"could lead to significant economic, societal, political, and geopolitical disruption","whose:own":"While we have made, and expect to continue to make, significant investments to integrate AI, including generative AI, into our platform","whose:general":"could lead to significant economic, societal, political, and geopolitical disruption","relation:within_purpose":"While we have made, and expect to continue to make, significant investments to integrate AI, including generative AI, into our platform","relation:misuse":"serious harms attributed to advanced AI systems, including 67 widespread fraud, cyberattacks, misinformation, automated reconnaissance, or other safety incidents, could increase litigation risk and reputational harm for companies offering AI-enabled products, even where such harms are caused by third parties or are outside our control","misuse_by:third_party":"serious harms attributed to advanced AI systems, including 67 widespread fraud, cyberattacks, misinformation, automated reconnaissance, or other safety incidents, could increase litigation risk and reputational harm for companies offering AI-enabled products, even where such harms are caused by third parties or are outside our control"},"rev":null,"harm_quote":"AI-inference 64 related fraud and abuse","status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-24c9b88719","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The markets in which we participate are rapidly evolving and highly competitive, and if we do not compete effectively, our business, operating results, and financial condition could be adversely impacted. We face competition from a number of companies, including companies that cater to multiple stages of the design and development process, point tools that address individual parts of the process but can expand to cover more, and design-to-code and AI-driven companies and tools that compress or accelerate steps in the workflow, take a different approach to building digital experiences, or automatically generate and iterate on designs and code through a prompt or with limited human input. We may also face competition from customized or internal solutions used by our customers or potential customers, particularly with AI’s potential to accelerate the ability to develop and deploy new software. Moreover, we expect to continue to face intense competition from current competitors, as well as from new entrants into the market, including as a result of strategic acquisitions and partnerships, increased use of AI in or as an alternative to dedicated design workflows, or evolving user and customer requirements and industry standards. If we are unable to anticipate or react to these challenges, our competitive position could weaken, and we may experience a decline in revenue, reduced revenue growth, or a loss of market share, which, individually or collectively, could adversely affect our business, operating results, and financial condition.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-093a736558","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Our competitors may be able to devote greater resources to the development, promotion, and sale of their products and services than we can, and they may offer lower pricing than we do or bundle certain competing products and services at lower prices or for free. For example, AI-enabled offerings by large platform companies, AI model providers and other technology providers, whether standalone or embedded in broader platforms, could reduce the perceived value of our standalone offerings and pressure our pricing and market position. Certain of our competitors may also have greater resources for research and development of new technologies, customer support, and to pursue acquisitions, or they may have other financial, technical, or other resource advantages.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-00146617d6","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"The markets for our products and services are relatively new and unproven and may not grow, which would adversely affect our business, operating results, financial condition, and future prospects. Although we launched our initial product, Figma Design, in 2015, the markets for our products and services, and especially those recently introduced, such as FigJam in 2021, Dev Mode in 2023, Figma Slides in 2024, and Figma Sites, Figma Make, Figma Buzz, Figma Draw, and Figma Weave in 2025, as well as the generative AI and code-related capabilities integrated across our platform, including AI-powered design generation, agentic workflows, and native code layers, remain relatively new and unproven. Because the markets for our products and services are relatively new and rapidly evolving, it is difficult to predict customer adoption, customer and user demand for our products and services, the size and growth rate of these markets, the entry of competitive products and services, or the success of existing competitive services. It is also difficult to predict the impact of AI on our markets. Any expansion or contraction in our markets depends on a number of factors, including, but not limited to, the cost, performance, and perceived value associated with our platform and the appetite and ability of customers to pay for and subscribe to our platform.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-9514f1f7be","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["2.1","1.2","1.1","3.1","7.3","2.2","4.3","6.3"],"primary":"2.1","status":"materialised","harm":["Human or fundamental rights","Economic/Property","Reputational"],"layers":["capability","human_interaction"],"whose":["own","general"],"relation":["within_purpose","misuse"],"misuse_by":["user","third_party"],"subjects":[{"name":"end users","type":"Group of persons"},{"name":"our customers","type":"Organization"}],"text":"If the markets for our platform do not grow to the extent that we anticipate or our platform does not achieve further widespread adoption within the markets in which we operate, our business, operating results, financial condition, and future prospects could be adversely affected. Our use of AI in our products and services may result in reputational harm, legal liability, competitive risks, and regulatory concerns that could adversely affect our business, operating results, and financial condition. We have made, and expect to continue to make, significant investments to integrate AI, including generative AI, and machine learning technology into our platform, including as part of our Figma Make product and Figma AI features. Many AI technologies are relatively new and present ethical, legal, regulatory, and reputational challenges. The use of datasets to develop AI models, the content generated by AI systems, or the application of AI systems may be found to be insufficient, offensive, biased, or harmful, or may violate current or future laws and regulations or contractual commitments. Standards and expectations regarding AI safety, acceptable outputs, and appropriate safeguards are evolving and may differ across our industry, customers, regulators, and the public, including across different geographies, cultures, and political environments, and there may be no consensus on what constitutes safe behavior for a given use case. We may be unable or unwilling to implement controls that satisfy all such expectations. Our decisions about whether and how to restrict or moderate AI outputs, and which AI technologies to use, including with respect to open-source and open-weight models, could result in customer dissatisfaction, reputational harm, or regulatory scrutiny. Certain AI technologies have come 70 under public scrutiny due to allegations that they generate inaccurate, incomplete, or misleading content, introduce unintended biases, and produce other discriminatory or unexpected results, errors, or inadequacies. Consumer and societal attitudes toward AI are evolving and there is a risk that regulators or the public may perceive AI technologies negatively. Concerns about automation, automated decision-making, privacy, security, transparency, and other ethical considerations could deter AI adoption. The insurance coverage we maintain may not extend to all AI-related risks we may face, and may not cover us for all losses for errors or omissions caused by AI. Further, we generally rely on third-party models for the AI features on our platform. Our ability to continue to use such technologies at scale may be dependent on access to certain limited or specific third-party software and infrastructure providers. We cannot control the availability or pricing of such third-party AI technologies, especially in a highly competitive environment, and we may be unable to negotiate favorable economic terms with the applicable providers. Providers may also experience capacity constraints or prioritize other customers or strategic partners, which could limit the availability or performance of our AI features. If any such third-party AI technologies become incompatible with our platform or unavailable for use, or if the providers of such models unfavorably change the terms on which their AI technologies are offered or terminate their relationship with us, our platform may become less appealing to our customers, and our business, operating results, and financial condition could be adversely impacted. Moreover, the integration of third-party AI models with our platform relies on certain safeguards implemented by the third-party developers of the underlying AI models, including those related to the accuracy, bias, and other variables of the training data used for such models, and these safeguards may be insufficient. In addition, if our AI features do not provide customers with sufficient administrative controls, transparency, documentation, or governance capabilities, customers may determine that such products and features are not suitable for regulated, security-sensitive, or enterprise use cases, which could reduce adoption, increase contractual disputes, or heighten scrutiny by regulators. If the models underlying our AI technologies, whether developed by a third party or developed by us, are incorrectly designed or implemented; trained or reliant on incomplete, inadequate, inaccurate, biased or otherwise poor quality data, or on data to which we do not have sufficient rights or in relation to which we and/or the providers of such data have not implemented sufficient legal compliance measures; used without sufficient oversight and governance to ensure their responsible use; and/or adversely impacted by unforeseen defects, technical challenges, cybersecurity threats, or material performance issues, the performance of our products, services, and business, as well as our reputation and our customers’ reputations, could suffer, and we could incur liability resulting from the violation of laws, breach of contract claims, or civil claims. For example, we are, and may in the future become, subject to litigation alleging breach of contract and related claims arising from allegations regarding the use of user data in connection with AI training, trade secret misappropriation, and violations of various state and federal statutes. Such claims can be costly to defend, may result in adverse judgments or settlements, may require changes to our products, policies, contracts, or business practices (including limitations on certain AI features or how data may be processed), and could harm our reputation and relationships with users. Further, claims, litigation, or regulatory actions relating to AI data practices may seek remedies beyond monetary damages, including injunctive relief, and could require us to make material changes to our products or business practices. Any such changes could be costly, technically complex, and disruptive to our product roadmap and operations, could reduce the performance or usefulness of our AI features, and could adversely affect customer relationships, revenue, and growth. In addition, the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information. Such leakage or unauthorized exposure of data related to the use of AI applications could result in legal claims or liability or otherwise adversely affect our reputation and operating results. The above risks may be increased by the introduction of our Figma Weave product, which contains many 71 AI models, some of which are entirely independent third-party models that are provided to customers “as is.” AI products and features may introduce additional security vulnerabilities and threat vectors beyond traditional software risks (including prompt injection, data poisoning, model inversion, membership inference, latent or hidden behaviors that are difficult to detect in testing and that may be triggered under certain conditions, and other attacks designed to cause models to disclose sensitive information), behave in unintended ways, or produce harmful or misleading outputs. Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage. Such activity could increase our costs (including AI inference and support costs), result in fraud, billing disputes, or chargebacks, and cause reputational harm or liability. In addition, the use of third-party models and toolchains may increase supply-chain risk, including the risk that model weights, safety layers, or dependencies are compromised, misconfigured, or updated in ways that degrade security or performance. If any of these vulnerabilities result in the unauthorized disclosure of customer content, confidential information, personal data, or proprietary information, or if customers believe our AI features are not sufficiently secure for their use cases, we could face contractual claims, indemnity demands, regulatory scrutiny, reputational harm, and reduced adoption of our AI features or platform. Moreover, our AI technologies could generate output that infringes on third-party intellectual property rights, and we could be subject to claims or lawsuits, including, but not limited to, for infringement of third-party intellectual property rights as a result of the output of such AI technologies. While some providers of AI technologies offer to indemnify their end users for any copyright or other intellectual property infringement claims arising from the output of their AI technologies, such indemnification may be inadequate or we may not be successful in adequately recovering our losses in connection with such claims. Our AI technologies could also generate content that is inaccurate, misleading, or inappropriate, which could harm our reputation, expose us to liability, or cause customers to lose confidence in our platform. The regulatory framework for AI technologies is rapidly evolving as many U.S. federal, state, and foreign government bodies and agencies have introduced or are currently considering additional laws and regulations. Additionally, existing laws and regulations may be interpreted in ways that would affect the operation of our AI technologies or could be rescinded or amended as new administrations take differing approaches to evolving AI technologies. As a result, implementation standards and enforcement practices are likely to remain uncertain for the foreseeable future, and we cannot yet completely determine the impact future laws, regulations, standards, or market perception of their requirements may have on our business and may not always be able to anticipate how to respond to these laws or regulations. Already, certain existing legal regimes, for example, relating to data privacy, regulate certain aspects of AI technologies, and new laws regulating AI technologies have recently entered into force in the United States and the EEA. In the United States, while there is no comprehensive federal AI legislation, a growing number of states have proposed or enacted laws regarding automated decision‑making, algorithmic discrimination, use of AI in employment contexts, and so-called “high‑risk” AI technologies, which may impact our use of AI and AI-powered tools. However, the status of such laws is currently uncertain as the federal government takes steps towards establishing broad federal AI regulation that could preempt all or some state law. Any such additional regulation may impact our ability to develop, use, and commercialize AI technologies in the future. In Europe, the EU Artificial Intelligence Act (the “EU AI Act”) establishes a comprehensive, risk-based governance framework for AI in the EU market. Once fully implemented, the EU AI Act will have a material impact on the way AI is regulated in the EU, as it applies to companies that develop, use, and/or provide AI in the EU and, depending on the AI use case, includes requirements around transparency, conformity assessments and monitoring, risk assessments, human oversight, security, accuracy, general purpose AI, and foundation models, and imposes substantial fines for breaches. The EU AI Act, together 72 with developing guidance and/or decisions in this area, may affect our use of AI technologies and our ability to provide, improve, or commercialize our services, require additional compliance measures and changes to our operations and processes, result in increased compliance costs and potential increases in civil claims against us, and could adversely affect our business, operating results, and financial condition. It is possible that new laws and regulations will be adopted in the United States and in other non-U.S. jurisdictions, or that existing laws and regulations, including competition and antitrust laws, may be interpreted in ways that would limit our ability to use AI technologies for our business, or require us to change the way we use AI technologies in a manner that negatively affects the performance of our offerings and the way in which we use AI technologies. We may need to expend resources to adjust our products, services, or operating procedures in certain jurisdictions if the laws, regulations, or decisions regarding AI technologies are not consistent across jurisdictions. Further, the cost to comply with such laws, regulations, or decisions and/or guidance interpreting existing laws, could be significant and would increase our operating expenses (such as by imposing additional reporting and compliance obligations regarding our use of AI technologies). Such an increase in operating expenses, as well as any actual or perceived failure to comply with such laws and regulations, could adversely affect our business, operating results, and financial condition. Moreover, any changes to the above discussed existing legal regimes with respect to data privacy and AI technologies within the United States and abroad could require us to expend significant resources to modify our products, services, or operations to ensure compliance or remain competitive. Existing and future acquisitions, strategic investments, partnerships, or alliances could be difficult to identify and integrate, divert the attention of key management personnel, disrupt our business, dilute stockholder value, and adversely affect our business, operating results, financial condition, and future prospects.","ev":{"status":"we are, and may in the future become, subject to litigation alleging breach of contract and related claims arising from allegations regarding the use of user data in connection with AI training","mit:2.1":"the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information","mit:1.2":"the content generated by AI systems, or the application of AI systems may be found to be insufficient, offensive, biased, or harmful","mit:1.1":"introduce unintended biases, and produce other discriminatory or unexpected results","mit:3.1":"Our AI technologies could also generate content that is inaccurate, misleading, or inappropriate","mit:7.3":"behave in unintended ways, or produce harmful or misleading outputs","mit:2.2":"prompt injection, data poisoning, model inversion, membership inference","mit:4.3":"result in fraud, billing disputes, or chargebacks","mit:6.3":"our AI technologies could generate output that infringes on third-party intellectual property rights","harm:Human or fundamental rights":"the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information","harm:Economic/Property":"Such activity could increase our costs (including AI inference and support costs), result in fraud, billing disputes, or chargebacks, and cause reputational harm or liability.","harm:Reputational":"could harm our reputation, expose us to liability, or cause customers to lose confidence in our platform","layer:capability":"Our AI technologies could also generate content that is inaccurate, misleading, or inappropriate","layer:human_interaction":"Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage.","whose:own":"We have made, and expect to continue to make, significant investments to integrate AI, including generative AI, and machine learning technology into our platform","whose:general":"Many AI technologies are relatively new and present ethical, legal, regulatory, and reputational challenges.","relation:within_purpose":"Our AI technologies could also generate content that is inaccurate, misleading, or inappropriate","relation:misuse":"Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage.","misuse_by:user":"Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage.","misuse_by:third_party":"Users or third parties may attempt to circumvent or defeat safeguards (including through jailbreaks, prompt manipulation, or other techniques) to generate prohibited content, extract sensitive information, or drive excessive usage."},"rev":null,"harm_quote":"the use of AI applications may result in data leakage or unauthorized exposure of data, including, but not limited to, confidential business information, the personal data of end users, or other sensitive information","status_quote":"we are, and may in the future become, subject to litigation alleging breach of contract and related claims arising from allegations regarding the use of user data in connection with AI training","reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-8b27b14b06","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"additional legal, regulatory, or compliance requirements; risks related to an acquired company’s development, integration, or use of AI; additional risks associated with acquisitions of companies based outside of the United States, including, but not limited to, exposure to political instability, terrorism, acts of war, security risks, and changes in the public perception of governments, and other risks unique to operating in foreign jurisdictions;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-320d882968","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["4.2","2.2","4.3","7.2","2.1"],"primary":"4.2","status":"elsewhere","harm":["Economic/Property","Human or fundamental rights","Reputational"],"layers":["human_interaction"],"whose":["own","others","general"],"relation":["misuse"],"misuse_by":["third_party"],"subjects":[{"name":"our customers","type":"Organization"}],"text":"Any security breach of our platform, our operational systems, physical facilities, or the systems of our third-party processors, or the perception that a breach has occurred, or other adverse impact to the availability, integrity, or confidentiality of such platform and systems, could result in litigation (including class actions), indemnity obligations, regulatory enforcement actions, investigations, compulsory audits, fines, penalties, mitigation and remediation costs, disputes, reputational harm, diversion of management’s attention, and other liabilities and damage to our business. We face evolving cybersecurity risks that threaten the confidentiality, integrity, and availability of our or our customers’ confidential or personal data and our and our third-party service providers’ information technology systems, which could result from human error, system misconfiguration, or from cyber-attacks, including distributed-denial-of-service attacks, reverse-engineering of AI algorithms, prompt injection attacks, automated reconnaissance, web scraping, ransomware attacks, business email compromises, credential stuffing, computer malware, viruses, and social engineering (including phishing, deepfakes, 76 and voice cloning), software supply-chain compromises, including but not limited to via AI agents, templates, designs, icons, widgets, plugins, or other third party software or content, malicious code embedded in open-source software, or misconfigurations, “bugs” or other vulnerabilities in commercial software that is integrated into our and our third-party service providers’ information technology systems, products or services, which are prevalent in our industry. Recent advancements in AI have demonstrated the potential for AI systems to autonomously discover and exploit software vulnerabilities, including zero-day vulnerabilities, at speeds and scales that exceed previous human capability, which may materially accelerate the timeline and severity of potential attacks. These threats may come from a variety of sources, including nation-state sponsored espionage and hacking activities, corporate espionage, organized crime, sophisticated organizations, hacking groups and individuals, and insider threats. Any security breach or disruption could result in the loss or destruction of, or unauthorized access to, or use, alteration, disclosure, or acquisition of confidential or personal data, which may result in damage to our reputation, termination of customer contracts, litigation, regulatory investigations, or other liabilities. More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors. Any circumvention or failure of our cybersecurity defenses or measures could compromise the confidentiality or integrity of our customers’ data or other sensitive information.","ev":{"status":"More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors","mit:4.2":"Recent advancements in AI have demonstrated the potential for AI systems to autonomously discover and exploit software vulnerabilities, including zero-day vulnerabilities, at speeds and scales that exceed previous human capability, which may materially accelerate the timeline and severity of potential attacks.","mit:2.2":"reverse-engineering of AI algorithms, prompt injection attacks","mit:4.3":"social engineering (including phishing, deepfakes, 76 and voice cloning)","mit:7.2":"Recent advancements in AI have demonstrated the potential for AI systems to autonomously discover and exploit software vulnerabilities, including zero-day vulnerabilities, at speeds and scales that exceed previous human capability, which may materially accelerate the timeline and severity of potential attacks.","mit:2.1":"Any security breach or disruption could result in the loss or destruction of, or unauthorized access to, or use, alteration, disclosure, or acquisition of confidential or personal data","harm:Economic/Property":"could result in litigation (including class actions), indemnity obligations, regulatory enforcement actions, investigations, compulsory audits, fines, penalties, mitigation and remediation costs","harm:Human or fundamental rights":"Any security breach or disruption could result in the loss or destruction of, or unauthorized access to, or use, alteration, disclosure, or acquisition of confidential or personal data","harm:Reputational":"which may result in damage to our reputation, termination of customer contracts, litigation, regulatory investigations, or other liabilities","layer:human_interaction":"More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors.","whose:own":"reverse-engineering of AI algorithms, prompt injection attacks","whose:others":"More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors.","whose:general":"Recent advancements in AI have demonstrated the potential for AI systems to autonomously discover and exploit software vulnerabilities, including zero-day vulnerabilities, at speeds and scales that exceed previous human capability, which may materially accelerate the timeline and severity of potential attacks.","relation:misuse":"More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors.","misuse_by:third_party":"More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors."},"rev":null,"harm_quote":"Recent advancements in AI have demonstrated the potential for AI systems to autonomously discover and exploit software vulnerabilities, including zero-day vulnerabilities, at speeds and scales that exceed previous human capability, which may materially accelerate the timeline and severity of potential attacks.","status_quote":"More capable AI models that are or may soon become widely accessible have and will continue to amplify the capabilities of threat actors","reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-5516f36585","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["4.2","7.2","2.1"],"primary":"4.2","status":"elsewhere","harm":["Economic/Property","Human or fundamental rights"],"layers":["human_interaction"],"whose":["others","general"],"relation":["misuse"],"misuse_by":["third_party"],"subjects":[{"name":"our customers","type":"Organization"}],"text":"Any of these outcomes could materially and adversely impact our business and financial condition. Techniques used to obtain unauthorized access or to sabotage systems change frequently, and the emergence of AI-driven offensive cyber capabilities may further compress the time between vulnerability discovery and exploitation. As a result, we may be unable to fully anticipate these techniques or to implement adequate preventative measures before they are exploited. Further, the incidence of state-supported and geopolitical-related cyberattacks may rise in connection with regional geopolitical conflicts which have increased the risk of cyberattacks on various types of infrastructure and operations. Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence, creating unprecedented 77 cybersecurity challenges. In addition, AI systems have demonstrated the capacity to discover and potentially exploit previously unknown software vulnerabilities across widely deployed operating systems, browsers, and other software on which our platform and infrastructure depend, which could expose us or our customers to attacks before patches or mitigations become available. As a result, we may be unable to detect, investigate, remediate, or recover from future attacks or incidents, or to avoid a material adverse impact to our information technology systems, confidential or personal data, or business.","ev":{"status":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks","mit:4.2":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","layer:human_interaction":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","whose:others":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","relation:misuse":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","misuse_by:third_party":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","mit:7.2":"AI systems have demonstrated the capacity to discover and potentially exploit previously unknown software vulnerabilities across widely deployed operating systems, browsers, and other software on which our platform and infrastructure depend","whose:general":"AI systems have demonstrated the capacity to discover and potentially exploit previously unknown software vulnerabilities across widely deployed operating systems, browsers, and other software on which our platform and infrastructure depend","mit:2.1":"we may be unable to detect, investigate, remediate, or recover from future attacks or incidents, or to avoid a material adverse impact to our information technology systems, confidential or personal data, or business","harm:Human or fundamental rights":"we may be unable to detect, investigate, remediate, or recover from future attacks or incidents, or to avoid a material adverse impact to our information technology systems, confidential or personal data, or business","harm:Economic/Property":"Any of these outcomes could materially and adversely impact our business and financial condition"},"rev":null,"harm_quote":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks, circumvent security controls, evade detection, and remove forensic evidence","status_quote":"Bad actors are also utilizing AI-based tools, including generative AI-based tools, to execute attacks","reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-a7e2b3d9bb","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Our business, operating results, and financial condition would be adversely affected if we suffer performance issues or downtime that fails to meet the service level commitments under our agreements with our customers. Our AI credit, usage-based, and rate-limiting systems have experienced, and in the future may continue to experience, defects, errors, or ambiguities, including with respect to usage attribution, balance calculations, limit enforcement, refresh timing, pooled allocations, invoices, or customer-facing reporting. For example, we have experienced, and may continue to experience, errors in the application of AI credits. If these systems fail to operate as intended, customers may be overcharged or undercharged, unexpectedly lose access, consume credits in connection with failed or interrupted outputs, or be unable to understand or verify usage, which could result in credits, refunds, disputes, litigation, regulatory scrutiny, and reputational harm. 80 We also have in the past and may in the future experience issues with respect to our billing processes as a result of errors in our code or the implementation of our billing logic, user permissioning systems, internal controls, information technology infrastructure, or any third-party technologies integrated into our billing processes.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-5571db58fc","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Additionally, with the importance and impact of social media, any negative publicity regarding our policies and practices or organizational decisions or actions by members of our team, including those taken in a personal capacity or unrelated to their roles at our company, may be magnified and reach a large portion of our users, customers, and employees in a very short period of time, which could harm our brand and reputation and adversely affect our business, operating results, and financial condition. Our public statements, marketing materials, customer communications, and disclosures regarding our products (including AI products and features), privacy and security practices, reliability, and pricing, packaging, and billing models may be subject to differing interpretations and may evolve over time, and alleged inconsistencies could expose us to claims or regulatory scrutiny. In particular, as we rapidly develop and introduce new products and AI features, we may update features, controls, defaults, 81 documentation, and policies, and customers, users, regulators, or plaintiffs may assert that certain statements were incomplete, misleading, or inconsistent with their expectations. Such allegations could result in litigation (including class actions), regulatory investigations, enforcement actions, adverse publicity, or reputational harm, any of which could adversely affect our business, operating results, and financial condition.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-352ecf212d","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"We rely on third-party service providers for critical components of our operations, and disruptions or changes in those services could adversely affect our business. In addition to AWS, we also depend on other third-party providers for services that are critical to the operation of our platform and business, including content delivery, identity and access management, payment processing, analytics and monitoring, and certain AI-related services. In particular, we have significant purchase commitments with a limited number of foundational AI model providers and a material portion of our AI features currently depend on models from them. Any of these third-party providers may experience outages, capacity constraints, cybersecurity incidents, business interruptions, or financial distress, may have their models restricted, suspended, or rendered unavailable as a result of export control, sanctions, or other governmental action, or may change pricing, service levels, security or compliance requirements, or contractual terms. If any such provider fails to perform as expected, if our access is limited or terminated, or if we are required to transition to alternative providers on short notice for any reason, we could experience service degradation or outages, delayed product development, increased costs, billing and collections disruption, and customer dissatisfaction, any of which could adversely affect our business, operating results, and financial condition. Additionally, certain customers may require us to restrict or replace the use of specific third-party AI models in order to continue using our platform, which could increase our costs, delay product rollouts, or reduce our ability to serve such customers. Customer requirements to substitute or exclude specific third-party AI models may arise from regulatory or contractual obligations applicable to our customers, government supply-chain or sanctions actions affecting model providers, or evolving customer policies, and may require us to develop, maintain, and operate redundant model integrations or alternative routing arrangements. We may not be able to implement such substitutions on terms that are commercially reasonable, on the timelines our customers require, or while maintaining feature parity, and any inability to do so could result in lost or curtailed sales, customer dissatisfaction, increased costs, or reputational harm.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-a4699c2916","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"There can be no assurance that we will be able to hire sufficient support personnel as and when needed, particularly if our sales exceed our internal forecasts. Additionally, our customer support team uses third-party AI tools to assist them with responding to and resolving customer inquiries. To the extent that we are unsuccessful in hiring, training, and retaining adequate support resources or utilizing AI tools for customer support, our ability to provide high-quality and timely support to our customers will be negatively impacted, and our customers’ satisfaction and their usage of our infrastructure could be adversely affected. 86 Because we primarily recognize subscription revenue over the subscription term, downturns or upturns in new sales and renewals are not immediately reflected in full in our operating results. We primarily derive revenue from sales of subscriptions for access to our platform, which is typically recognized on a ratable basis over the term of the contract subscription period beginning on the date access to our platform is granted, provided all other revenue recognition criteria have been met.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-250c7b5f72","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Our revenue recognition and operating results may be difficult to predict because of the length and unpredictability of the sales cycle for our platform, particularly as we increasingly sell to larger organizations, governmental entities, highly regulated organizations, and organizations outside of the United States or the technology industry that may have different procurement requirements than our historical customers. For example, we have observed a lengthening of the sales cycle recently for some prospective customers that we attribute to increased sensitivity to information technology security concerns, particularly with respect to products that include AI features or otherwise incorporate AI technologies, such as our platform. In addition, larger customers, governmental entities, and highly regulated organizations frequently have rigorous procurement processes and require considerable time to evaluate, test, and qualify our platform prior to entering into or expanding a relationship with us.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-67ee6bd616","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"selling to governmental entities and highly regulated organizations can be highly competitive, expensive, and time consuming, often requiring significant upfront time and expense without any assurance that such efforts will generate a sale; government certification, software supply chain or cybersecurity requirements applicable to us or our platform may change and, in doing so, restrict our ability to sell into the governmental sector and to highly regulated organizations until we have attained the revised certification or meet other new requirements (for example, although we are currently FedRAMP authorized, such authorization is costly to maintain and subject to rigorous compliance and if we lose our authorization, it will restrict our ability to sell to government entities; further, the U.S. federal government recently identified Anthropic PBC (“Anthropic”) as a supply chain risk and directed all federal agencies to cease use of Anthropic’s products, including Claude, the large language model on which we have built the AI features embedded in our governmental offerings, and, although the implementation of this directive has been the subject of ongoing litigation and is currently enjoined as to government entities, if a government-wide ban of Anthropic is upheld in whole or in part and we are unable to find a suitable replacement on a timely basis, on competitive terms, or at all, our sales to governmental entities and highly regulated organizations could suffer, and even if the ongoing litigation is resolved in Anthropic’s favor that may not fully restore customer confidence or reverse contracting decisions made by affected governmental entities and highly regulated organizations prior to such resolution); government entity demand and payment for our platform may be impacted by public sector budgetary cycles and funding authorizations, with funding reductions or delays adversely affecting public sector demand for our platform, including, but not limited to, as a result of sudden, unforeseen, and disruptive events such as geopolitical instability, warfare, and uncertainty, incidents of terrorism, natural disasters, public health concerns or epidemics, governmental defaults on indebtedness, governmental shutdowns, inflation, changes in interest rates, changes in investment and spending environments, and reductions in the government workforce, which may limit or delay governmental entity spending on our platform and adversely affect our revenue; 88","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-212d4c0269","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"More generally, the technology industry, and the software industry more specifically, is also subject to substantial and continuous competition for engineers with high levels of experience in designing, developing, and managing software and related services. This is especially true in the market for AI talent, which remains extremely competitive. We have, from time to time, experienced, and we expect to continue to experience, difficulty in hiring and retaining highly skilled employees with appropriate qualifications at a suitable cost, and this risk may be exacerbated by factors related to, among other things, increased recruiting efforts by other companies and volatility in the price of our Class A common stock.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-7f979508f0","kind":"10-Q","source":null,"discloses":"ai_harm","mit":["6.3","7.3","2.2"],"primary":"6.3","status":"elsewhere","harm":["Economic/Property"],"layers":["capability"],"whose":["own","general"],"relation":["within_purpose","misuse"],"misuse_by":["third_party"],"subjects":[{"name":"our customers","type":"Organization"}],"text":"A loss of key personnel or their work product could hamper or prevent our ability to develop, market, and support potential products or enhancements, which could severely harm our business. Further, we may use AI technologies, including tools provided by third parties, to develop or assist in the development of our own software code. While use of such tools makes our development process more efficient, AI technologies have sometimes generated content that is “substantially similar” to proprietary or open source software code on which the AI tool was trained. If the AI technologies we use generate code that is too similar to other proprietary code, or to software processes that are protected by patents, we could be subject to intellectual property infringement claims. AI-generated code or other outputs may also introduce security vulnerabilities, compliance failures (including accessibility), or license obligations (including open source notices or attribution requirements). We may not be able to anticipate and detect security vulnerabilities in AI-generated software code, including those that could be induced by a maliciously trained AI model. If our tools generate code that is too similar to open source code, we risk losing protection of our own proprietary code that is commingled with such code. Finally, to the extent we use third-party AI technologies to develop software code, the terms of use of these tools may state that the third-party provider retains rights in the generated code. We may also face similar risks in using AI technologies to develop or assist in the development of other materials, such as advertising or marketing materials. 95 Any intellectual property claims, whether with or without merit, could be very time-consuming, could be expensive to settle or litigate, and could divert our management’s attention and other resources, even if such claims do not result in litigation or are resolved in our favor. These claims could also subject us to significant liability for damages, potentially including treble damages if we are found to have willfully infringed patents or copyrights, and may require us to indemnify our customers for liabilities they incur as a result of such claims.","ev":{"status":"AI technologies have sometimes generated content that is “substantially similar” to proprietary or open source software code on which the AI tool was trained","mit:6.3":"If the AI technologies we use generate code that is too similar to other proprietary code, or to software processes that are protected by patents, we could be subject to intellectual property infringement claims","mit:7.3":"AI-generated code or other outputs may also introduce security vulnerabilities, compliance failures (including accessibility), or license obligations","mit:2.2":"We may not be able to anticipate and detect security vulnerabilities in AI-generated software code, including those that could be induced by a maliciously trained AI model","harm:Economic/Property":"These claims could also subject us to significant liability for damages, potentially including treble damages","layer:capability":"AI-generated code or other outputs may also introduce security vulnerabilities, compliance failures (including accessibility), or license obligations","whose:own":"we may use AI technologies, including tools provided by third parties, to develop or assist in the development of our own software code","whose:general":"AI technologies have sometimes generated content that is","relation:within_purpose":"we may use AI technologies, including tools provided by third parties, to develop or assist in the development of our own software code","relation:misuse":"We may not be able to anticipate and detect security vulnerabilities in AI-generated software code, including those that could be induced by a maliciously trained AI model","misuse_by:third_party":"We may not be able to anticipate and detect security vulnerabilities in AI-generated software code, including those that could be induced by a maliciously trained AI model"},"rev":null,"harm_quote":"If the AI technologies we use generate code that is too similar to other proprietary code, or to software processes that are protected by patents, we could be subject to intellectual property infringement claims","status_quote":"AI technologies have sometimes generated content that is “substantially similar” to proprietary or open source software code on which the AI tool was trained","reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-8ee55f22c5","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Certain of our employees outside of the United States are in the process of establishing, and an increasing number may in the future become subject to, mandatory works council, employee representation, or collective bargaining arrangements in accordance with local laws or sector-wide collective agreements, including in jurisdictions where we have established or are establishing direct employment relationships in place of professional employer organization arrangements. These challenges are accentuated by the use and proliferation of emerging technologies within our business, including AI-related technologies, the regulation of which is becoming increasingly complex, including with respect to labor laws and hiring practices. Compliance with such laws, regulations, and policies may require significant investment and expense.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-85832f2112","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"For example, our Class A common stock has traded as high as $124.63 per share on the first day of trading following our IPO and, during the three months ended June 30, 2026, traded as low as $16.60 per share. The trading price of our Class A common stock may continue to be volatile and decline further, including for reasons unrelated to our operating performance, such as valuation compression due to investor sentiment regarding software, AI, or obsolescence risk. You may not be able to resell your shares at or above the price you paid for them, and could lose all or part of your investment in our Class A common stock.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-d1ed2a93ae","kind":"10-Q","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"developments in AI; market or analyst focus on seat count, seat growth, or other per-seat metrics as a perceived indicator of the impact of AI agents on demand for seat-based software; litigation or other proceedings involving us, our industry, or both, or investigations by regulators into our operations or those of our competitors or others that may be associated with us;","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053348"],"forms":{"10-Q":1},"first":"2026-08-05","last":"2026-08-05","end":null}],"k8":[{"id":"1579878-8k-d747ea67c8","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"EX-99.1 2 q225pressrelease.htm EX-99.1 Figma Announces Second Quarter 2025 Financial Results Second quarter revenue grew 41% year-over-year to $249.6 million. Doubled product offering with new design and AI-powered features to help teams go from idea to shipped product, all in one place. San Francisco, CA – September 3, 2025 – Figma, Inc.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000026"],"forms":{"8-K":1},"first":"2025-09-03","last":"2025-09-03","end":null},{"id":"1579878-8k-9a7fa77df4","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Looking ahead, we’re excited to keep building for our customers and help define the next era of digital products and experiences. Design is more important than ever, and we have so much more to build.” “Our performance this quarter highlights the strength of our business and the critical value of design,” said Praveer Melwani, Figma’s Chief Financial Officer. “We delivered best-in-class revenue growth and positive operating margin as we kept investing in AI and expanded our platform. Our 129% Net Dollar Retention Rate also shows that our customers are continuing to deepen their investment in Figma'’s platform.” Second Quarter 2025 Financial Highlights:","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000026"],"forms":{"8-K":1},"first":"2025-09-03","last":"2025-09-03","end":null},{"id":"1579878-8k-d7b3f715d9","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"1,119 Paid Customers with more than $100,000 in ARR as of June 30, 2025. Launched four new products: Figma Make for AI-powered prototyping; Figma Draw for richer visual expression; Figma Sites for publishing designs as live websites; and Figma Buzz for creating marketing assets. Released Figma’s Dev Mode MCP server, which speeds up developer workflows by bringing context from design systems into LLM-generated code. Hosted Config – Figma’s annual user conference.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000026"],"forms":{"8-K":1},"first":"2025-09-03","last":"2025-09-03","end":null},{"id":"1579878-8k-1ed29a51b7","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"About Figma Figma (NYSE: FIG) is where teams come together to turn ideas into the world’s best digital products and experiences. Founded in 2012, Figma has evolved from a design tool to a connected, AI-powered platform that helps teams go from idea to shipped product. Whether you’re ideating, designing, building, or shipping, Figma makes the entire design and product development process more collaborative, efficient, and fun—while keeping everyone on the same page.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001579878-25-000026","0001628280-26-009024","0001628280-26-035087"],"forms":{"8-K":3},"first":"2025-09-03","last":"2026-05-14","end":null},{"id":"1579878-8k-0b2fa8b492","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"EX-99.1 2 q325pressrelease.htm EX-99.1 Figma Announces Third Quarter 2025 Financial Results Third quarter revenue grew 38% year-over-year to a quarterly record of $274.2 million as company raises full-year guidance. Figma accelerated customer growth and multi-product adoption as Figma Make and other AI products continued gaining traction. San Francisco, CA – November 5, 2025 – Figma, Inc. (NYSE:FIG) announced financial results today for its third quarter ended September 30, 2025. “Q3 was the best quarter in Figma’s history: we crossed $1 billion in annual revenue run rate, delivered record revenue and shipped faster than ever for our customers,” said Dylan Field, Figma’s CEO and co-founder. “Our incredible quarter was driven in part by AI product investments in Figma Make and our MCP server which are spreading Figma to new teams and new audiences. AI is redefining how software gets built, moving value up the stack to design––and we are building the platform where anyone can go from idea to product.” “We delivered another strong quarter, beating our third quarter revenue expectations with 38% year-over-year growth,” said Praveer Melwani, Figma’s CFO. “By the end of September, approximately 30% of Paid Customers spending $100,000 or more in ARR were creating on Figma Make on a weekly basis — which shows how strongly our new products are resonating with customers and has given us the confidence to raise our full year outlook for 2025. We have the flexibility to keep investing to drive sustainable, long-term growth.” Third Quarter 2025 Financial Highlights:","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-25-049555"],"forms":{"8-K":1},"first":"2025-11-05","last":"2025-11-05","end":null},{"id":"1579878-8k-c0599959f2","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Launched over 50 new features across the Figma platform during the third quarter. AI features like Copy Design, remote Figma MCP Server, and Make Kits to further support users’ AI-native design and product development workflows. Partnered with OpenAI to launch the Figma App for ChatGPT, one of many product integrations Figma launched in the third quarter. With the Figma App, a user can use conversations with ChatGPT to generate a diagram, a flow chart or Gantt chart in FigJam, and then share, save or continue to edit within Figma. Acquired Weavy, a platform that brings generative AI and professional editing tools into the open canvas. As Figma Weave, the company will help build out image, video, animation, motion design, and VFX media generation and editing capability on the Figma platform. Welcomed Loredana Crisan as Figma’s Chief Design Officer. Loredana joined Figma from Meta, where over the past decade she led product and design teams across Messenger, Instagram, and their GenAI efforts. Published original research report, Shifting Roles: How Product Development Teams Are Evolving In 2025, with comprehensive research on how team roles and workflows are shifting across the full product development lifecycle. The study found that more than half of non-designers (56%) say they now engage “a lot” or “a great deal” in at least one design-centric task, and 72% of respondents cite AI tools as a primary force behind shifts in their role. Fourth Quarter and Full Year 2025 Outlook: Based on information as of today, Figma is providing the following guidance:","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-25-049555"],"forms":{"8-K":1},"first":"2025-11-05","last":"2025-11-05","end":null},{"id":"1579878-8k-98d9738341","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Investor Presentation: An investor presentation providing additional information can be found at https://investor.figma.com. 2 About Figma Figma (NYSE: FIG) is where teams come together to turn ideas into the world’s best digital products and experiences. Founded in 2012, Figma has evolved from a design tool to a connected, AI-powered platform that helps teams go from idea to shipped product. Whether you’re ideating, designing, building, or shipping, Figma makes the entire design and product development process more collaborative, efficient, and fun—while keeping everyone on the same page.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-25-049555"],"forms":{"8-K":1},"first":"2025-11-05","last":"2025-11-05","end":null},{"id":"1579878-8k-1557b28110","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"EX-99.1 2 fy25pressrelease.htm EX-99.1 Figma Announces Fourth Quarter and Fiscal Year 2025 Financial Results Fourth quarter revenue of $303.8 million reflects an accelerated 40% year-over-year growth rate. Net Dollar Retention Rate rose to 136% as Figma drove platform and AI adoption. San Francisco, CA – February 18, 2026 – Figma, Inc.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009024"],"forms":{"8-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-8k-cb32b6d23c","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"This is what Figma’s platform uniquely makes possible.” “Q4 was our best quarter for net new revenue on record, as platform-led adoption across our customer base––including enterprise and international––powered durable growth at scale,” said Praveer Melwani, Figma CFO. “We closed the year with 40% year-over-year revenue growth in Q4, an uptick in Net Dollar Retention Rate, and strong cash generation, with a 13% operating cash flow margin. Our healthy balance sheet and positive free cash flow gives us the flexibility to continue investing in AI and the platform while maintaining financial discipline for sustainable, long-term growth.” Fourth Quarter 2025 Financial Highlights: Revenue was $303.8 million, an increase of 40% year-over-year, and above the range of Figma’s previously issued fourth quarter guidance.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009024"],"forms":{"8-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-8k-5fe3dd5625","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Weekly active users of Figma Make grew over 70% quarter-over-quarter, with over half of Paid Customers with more than $100,000 in ARR building in Figma Make on a weekly basis in the three months ended December 31, 2025. Over 80% of Figma Make’s weekly active users on Full seats also used Figma Design in the three months ended December 31, 2025, reflecting the increased adoption of AI workflows across Figma’s platform. Expanded the functionality and availability of Figma Make, including the ability to use experimental models Gemini 3 Pro and Claude Opus 4.6.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009024"],"forms":{"8-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-8k-793b8d01af","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Released a new Claude Code to Figma feature that allows users to bring user interfaces generated in Claude Code directly into Figma’s infinite canvas as editable layers, which users can manipulate, duplicate, iterate, and refine with their team. Launched three new AI image editing tools for precision editing directly in the Figma canvas, and acquired Weavy, now Figma Weave, which brings the world’s leading AI models together with professional editing tools on a single, browser-based canvas. Partnered with Anthropic to launch the Figma MCP app in Claude, which expands on Figma’s existing MCP server and allows users to turn conversations with Claude into diagrams, flow charts, or Gantt charts in FigJam. Expanded the Figma app in ChatGPT to support the generation of FigJam diagrams, Figma Buzz marketing artifacts, and Figma Slides presentations. Opened an office in Bengaluru and announced local data hosting and governance support for enterprise, to further invest in India, Figma’s second-largest market by monthly active users.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-009024"],"forms":{"8-K":1},"first":"2026-02-18","last":"2026-02-18","end":null},{"id":"1579878-8k-ff5ab80151","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"EX-99.1 2 q126pressrelease.htm EX-99.1 Figma Announces First Quarter 2026 Financial Results Q1 revenue grew 46% year-over-year to $333.4 million, accelerating from 40% year-over-year growth in the previous quarter Figma raises full year revenue and non-GAAP operating income guidance, reflecting sustained seat expansion and AI adoption San Francisco, CA – May 14, 2026 – Figma, Inc. (NYSE:FIG) announced financial results today for its first quarter ended March 31, 2026. “Q1 was an incredible quarter for Figma: revenue growth accelerated for the second consecutive quarter and customers are going bigger and broader with Figma than ever before,” said Figma co-founder and CEO Dylan Field. “When code is a commodity, design is the competitive edge—the craft, point of view, and human judgment that make a great product rise above the rest. Figma is uniquely built for this moment, and we couldn’t be more excited about what we’re building or the opportunity ahead.” “Q1 was an exceptional quarter for Figma, exceeding expectations across multiple dimensions of our business,” said Praveer Melwani, Figma CFO. “Our outperformance in Q1 was fueled by stronger than expected seat expansion across entire organizations, driven by design’s growing importance and adoption of our AI products including Figma Make, MCP, and Figma Weave. We are raising our guidance for the year based on promising early traction on AI monetization and strength across the core platform, a testament to the team’s execution and our confidence in the road ahead.” First Quarter 2026 Financial Highlights: Revenue was $333.4 million, up 46% year-over-year and above the range of Figma’s previously issued first quarter guidance.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035087"],"forms":{"8-K":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-8k-e808dfea82","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Paid Customers grew 54% year-over-year, to approximately 690,000 Paid Customers as of March 31, 2026. In the three months ended March 31, 2026, new Pro team conversions grew more than 150% year-over-year, reflecting continued long-tail adoption of Figma’s AI features. Approximately 60% of Paid Customers with more than $100,000 in ARR used Figma Make on a weekly basis in the three months ended March 31, 2026, up from over 50% in the prior quarter. Implemented AI credit limits for all seats beginning on March 18, 2026. ◦Over 75% of Org and Enterprise users who had previously exceeded AI credit limits continued to use AI credits in April and over 95% of those users remained active on the platform, as of April 30, 2026. ◦Pro teams that purchased AI credit add-ons had more seats per team and an average ARR of more than three times that of teams that had not purchased add-ons as of March 31, 2026. Expanded the Code to Canvas capability across a growing set of prototyping tools and integrated development environments (IDEs), allowing users to bring user interfaces generated in tools like Claude Code, Codex, Cursor, VS Code, and Warp directly into Figma’s multiplayer canvas as editable layers, which users can manipulate, duplicate, iterate and refine with their team. Shipped new Figma Model Context Protocol (“MCP”) capabilities that let agents read and write directly to Figma files—creating and modifying real design assets using users’ components, variables, and tokens. ◦In the three months ended March 31, 2026, MCP weekly active users in Figma Design grew five times quarter-over-quarter. ◦Paid Customers with more than $100,000 in ARR that use Figma’s MCP server grew Full seats at a rate approximately 70% faster in the three months ended March 31, 2026 than those not using Figma’s MCP server. Shipped updates to Figma Weave, formerly Weavy, including a new timeline editor that lets users refine AI-generated video. Second Quarter and Full Year 2026 Outlook: Based on information as of today, Figma is providing the following guidance:","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035087"],"forms":{"8-K":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-8k-0861784167","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Forward-Looking Statements This press release contains “forward-looking statements” within the meaning of applicable securities laws. All statements other than statements of historical fact could be deemed to be forward-looking, including, but not limited to, statements regarding Figma’s future operating results and financial condition, including financial outlook for the second quarter of 2026 and full year 2026, Figma’s business strategy and plans, Figma’s expectations regarding customer adoption, growth, and expansion, Figma’s expectations regarding AI products, features, and monetization, as well as any assumptions relating to the foregoing. The words “believe,” “may,” “will,” “potentially,” “estimate,” “continue,” “anticipate,” “intend,” “could,” “would,” “project,” “target,” “plan,” “expect,” and similar expressions are intended to identify forward-looking statements, although not all forward-looking statements contain these identifying words.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-035087"],"forms":{"8-K":1},"first":"2026-05-14","last":"2026-05-14","end":null},{"id":"1579878-8k-6b3829c92e","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"GAAP and non-GAAP gross profit year-over-year growth accelerated to 40%. Code Layers, the Figma agent, and new creative capabilities expand the surface for AI consumption and what teams can create in Figma. Figma raises full year revenue guidance, reflecting sustained seat expansion and AI adoption. San Francisco, CA – August 5, 2026 – Figma, Inc. (NYSE:FIG) announced financial results today for its second quarter ended June 30, 2026. “Q2 was Figma’s third straight quarter of accelerated revenue growth, and as code gets commoditized and value moves up the stack, the opportunity ahead of us has only grown,” said Dylan Field, Figma's CEO. “By bringing code, new creative capabilities, and agents directly to the canvas, we’re increasing the surface for AI consumption in Figma and expanding the possibilities for what teams can create on our platform. Figma is building the canvas for full-stack creation: one place where anyone can reach for the tool they need to express their vision exactly as they imagine it.” “Q2 was a record quarter and our first full quarter of AI credit monetization,” said Praveer Melwani, Figma’s CFO. “Revenue grew 48% year-over-year, accelerating for the third consecutive quarter, and gross profit growth accelerated alongside it. Net Dollar Retention Rate remained strong at 136% as customers expanded both seats and AI credit add-ons. The strength of these signals gives us the confidence to raise our full year revenue outlook while continuing to invest behind the products we introduced at Config.” Second Quarter 2026 Financial Highlights:","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053331"],"forms":{"8-K":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-8k-df4fd4b0eb","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"1,635 Paid Customers with more than $100,000 in ARR as of June 30, 2026, growing 46% year-over-year. As of June 30, 2026, over 80% of Paid Customers with more than $10,000 in ARR were consuming AI credits weekly. Hosted Config, Figma’s annual user conference, which brought over 10,000 designers, product builders, and executive leaders from the world’s leading companies to San Francisco.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053331"],"forms":{"8-K":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-8k-f20ef6dede","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Also introduced the ability for teams to work directly in their production codebase with Figma Make. Introduced new expressive capabilities on the canvas such as Motion, Shaders, and 3D Transforms; also shipped Figma Weave Tools, which turn complex AI image and video generation workflows into re-usable tools on the canvas. Together, these new capabilities expand the types of work that can happen on Figma.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053331"],"forms":{"8-K":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-8k-9bf1803881","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Forward-Looking Statements This press release contains “forward-looking statements” within the meaning of applicable securities laws. All statements other than statements of historical fact could be deemed to be forward-looking, including, but not limited to, statements regarding Figma’s future operating results and financial condition, including financial outlook for the third quarter of 2026 and full year 2026, Figma’s business strategy and plans, Figma’s expectations regarding opportunity, customer adoption, growth, and expansion, Figma’s expectations regarding AI products, features, and monetization, as well as any assumptions relating to the foregoing. The words “believe,” “may,” “will,” “potentially,” “estimate,” “continue,” “anticipate,” “intend,” “could,” “would,” “project,” “target,” “plan,” “expect,” and similar expressions are intended to identify forward-looking statements, although not all forward-looking statements contain these identifying words.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053331"],"forms":{"8-K":1},"first":"2026-08-05","last":"2026-08-05","end":null},{"id":"1579878-8k-7eb8469d1c","kind":"8-K","source":null,"discloses":"business_only","mit":[],"primary":null,"status":null,"harm":[],"layers":[],"whose":[],"relation":[],"misuse_by":[],"subjects":[],"text":"Figma calculates Net Dollar Retention Rate using ARR from Paid Customers with more than $10,000 in ARR because Figma believes that $10,000 in ARR is an important threshold, as it is a strong indicator of significant paid usage of Figma’s products. Figma calculates Paid Customers with more than $10,000 in ARR consuming AI credits on a weekly basis for a given quarter using the week with the highest number of such users in the quarter. Additional terms are defined in Figma’s Quarterly Report on Form 10-Q for the quarter ended June 30, 2026, filed or to be filed with the SEC on August 5, 2026. 5 Figma, Inc.","ev":{},"rev":null,"harm_quote":null,"status_quote":null,"reports":["0001628280-26-053331"],"forms":{"8-K":1},"first":"2026-08-05","last":"2026-08-05","end":null}]});
